INSERT INTO `blog_posts` (`id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `featured_image_id`, `author_id`, `status`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, '{\"ar\":\"لماذا يبقى Laravel الخيار الأول لتطبيقات الويب المؤسسية في 2026\",\"en\":\"Why Laravel Remains the Top Choice for Enterprise Web Apps in 2026\"}', 'why-laravel-remains-the-top-choice-for-enterprise-web-apps-in-2026', '{\"ar\":\"يواصل Laravel هيمنة تطوير PHP المؤسسي بفضل نظامه البيئي القوي وميزات الأمان وأدوات الإنتاجية.\",\"en\":\"Laravel continues to dominate enterprise PHP development with its robust ecosystem, security features, and developer productivity tools.\"}', '{\"ar\":\"<p>عند بناء تطبيقات ويب على مستوى المؤسسات، يكون اختيار الإطار حاسماً. أثبت Laravel مراراً أنه إطار PHP المفضل للشركات التي تحتاج قابلية التوسع والأمان والتطوير السريع.<\\/p><p>في Ytech، أنجزنا أكثر من 40 مشروع Laravel لعملاء في السعودية والخليج. إليكم لماذا نواصل التوصية به.<\\/p>\",\"en\":\"<p>When building enterprise-grade web applications, choosing the right framework is critical. Laravel has consistently proven itself as the go-to PHP framework for businesses that need scalability, security, and rapid development.<\\/p><p>At Ytech, we have delivered over 40 Laravel projects for clients across Saudi Arabia and the GCC. Here is why we continue to recommend it:<\\/p><h3>1. Security Built-In<\\/h3><p>Laravel provides CSRF protection, SQL injection prevention, and encrypted sessions out of the box — essential for fintech and healthcare applications.<\\/p><h3>2. Eloquent ORM<\\/h3><p>Database interactions become intuitive and maintainable, reducing development time and bugs.<\\/p><h3>3. Ecosystem<\\/h3><p>From Laravel Horizon for queue management to Laravel Sanctum for API authentication, the ecosystem covers every enterprise need.<\\/p>\"}', NULL, 1, 'published', '2026-08-16 17:49:37', NULL, NULL, '2026-08-30 17:49:37', '2026-08-30 17:49:37', NULL),
(2, 3, '{\"ar\":\"5 علامات تدل على أن عملك يحتاج حل برمجي مخصص\",\"en\":\"5 Signs Your Business Needs a Custom Software Solution\"}', '5-signs-your-business-needs-a-custom-software-solution', '{\"ar\":\"البرمجيات الجاهزة تناسبك حتى لا تناسبك. إليك خمس مؤشرات على أن عملك جاهز لحل مخصص.\",\"en\":\"Off-the-shelf software works until it does not. Here are five indicators that your business is ready for a tailored solution.\"}', '{\"ar\":\"<p>تبدأ كثير من الشركات السعودية بأدوات برمجية عامة. مع النمو، غالباً ما تصبح هذه الأدوات عائقاً بدلاً من مُمكّن.<\\/p><p>إذا كان أي من هذه ينطبق عليك، قد يكون الوقت مناسباً للتحدث مع Ytech عن حل مخصص.<\\/p>\",\"en\":\"<p>Many Saudi businesses start with generic software tools. As you grow, these tools often become bottlenecks rather than enablers.<\\/p><p><strong>Sign 1:<\\/strong> Your team uses spreadsheets to fill gaps in your software.<br><strong>Sign 2:<\\/strong> You are paying for features you never use.<br><strong>Sign 3:<\\/strong> Integration between systems requires manual data entry.<br><strong>Sign 4:<\\/strong> Your customer experience suffers due to system limitations.<br><strong>Sign 5:<\\/strong> Competitors are outpacing you with better digital tools.<\\/p><p>If any of these resonate, it may be time to talk to Ytech about a custom solution.<\\/p>\"}', NULL, 1, 'published', '2026-07-31 17:49:37', NULL, NULL, '2026-08-30 17:49:37', '2026-08-30 17:49:37', NULL),
(3, 4, '{\"ar\":\"Ytech توسّع فريقها لدعم الطلب المتزايد من العملاء\",\"en\":\"Ytech Expands Team to Support Growing Client Demand\"}', 'ytech-expands-team-to-support-growing-client-demand', '{\"ar\":\"يسعدنا الإعلان عن انضمام خمسة محترفين جدد لدعم محفظة مشاريعنا المؤسسية المتنامية.\",\"en\":\"We are thrilled to announce the addition of five new team members to support our expanding portfolio of enterprise projects.\"}', '{\"ar\":\"<p>Ytech في نمو! ولمواكبة الطلب المتزايد من العملاء في الخليج، رحّبنا بخمسة محترفين موهوبين في مكتبنا بالرياض.<\\/p><p>يجلب الأعضاء الجدد خبرة في Flutter والبنية السحابية AWS وتصميم UI\\/UX — مما يعزز قدرتنا على تقديم حلول رقمية متكاملة.<\\/p>\",\"en\":\"<p>Ytech is growing! To meet increasing demand from clients across the GCC, we have welcomed five talented professionals to our Riyadh office.<\\/p><p>The new team members bring expertise in Flutter mobile development, AWS cloud architecture, and UI\\/UX design — strengthening our ability to deliver end-to-end digital solutions.<\\/p><p>We remain committed to maintaining the quality and personal attention that our clients expect, even as we scale.<\\/p>\"}', NULL, 1, 'published', '2026-08-23 17:49:37', NULL, NULL, '2026-08-30 17:49:37', '2026-08-30 17:49:37', NULL);

