(1, 'hero', '{\"ar\":\"نبني\",\"en\":\"We build\"}', '{\"ar\":\"من التقنية والأنظمة المخصصة إلى التسويق والفرق المتخصصة، نساعدك على بناء أعمال أكثر كفاءة وقابلية للنمو\",\"en\":\"From technology and custom software to marketing and dedicated teams, we help businesses operate smarter and scale with confidence.\"}', '{\"kicker\": {\"ar\": \"شريكك في التحول الرقمي\", \"en\": \"Your partner in digital transformation\"}, \"cta_primary\": {\"url\": \"/contact\", \"label\": {\"ar\": \"ابدأ مشروعك\", \"en\": \"Start Your Project\"}}, \"description\": {\"ar\": \"من التقنية والأنظمة المخصصة إلى التسويق والفرق المتخصصة، نساعدك على بناء أعمال أكثر كفاءة وقابلية للنمو\", \"en\": \"From technology and custom software to marketing and dedicated teams, we help businesses operate smarter and scale with confidence.\"}, \"script_line1\": {\"ar\": \"Ideas\", \"en\": \"Ideas\"}, \"script_line2\": {\"ar\": \"To Impact\", \"en\": \"To Impact\"}, \"cta_secondary\": {\"url\": \"/work\", \"label\": {\"ar\": \"استكشف أعمالنا\", \"en\": \"Explore Our Work\"}}, \"float_grow_sub\": {\"ar\": \"أعمالك\", \"en\": \"Your Business\"}, \"float_idea_sub\": {\"ar\": \"إلى منتج قابل للتوسع\", \"en\": \"to Scalable Product\"}, \"headline_line2\": {\"ar\": \"تدفع أعمالك إلى الأمام\", \"en\": \"solutions that move your business forward\"}, \"float_grow_title\": {\"ar\": \"نمِّ\", \"en\": \"Grow\"}, \"float_idea_title\": {\"ar\": \"من الفكرة\", \"en\": \"From Idea\"}, \"headline_line1_accent\": {\"ar\": \"حلولًا\", \"en\": \"solutions\"}, \"headline_line1_prefix\": {\"ar\": \"نبني\", \"en\": \"We build\"}}', 1, 1, '2026-08-30 17:49:36', '2026-09-27 10:43:18'),
(2, 'clients', '{\"ar\":\"خبرة تمتد عبر قطاعات مختلفة\",\"en\":\"Experience across diverse industries\"}', '{\"ar\":\"من نعمل معهم\",\"en\":\"Who we work with\"}', '{\"items\": [{\"title\": {\"ar\": \"الشركات والمؤسسات\", \"en\": \"Companies & enterprises\"}, \"description\": {\"ar\": \"منصات وأنظمة تشغيلية تدعم عملياتك اليومية.\", \"en\": \"Operational platforms and systems for day-to-day business.\"}}, {\"title\": {\"ar\": \"الشركات الناشئة\", \"en\": \"Startups\"}, \"description\": {\"ar\": \"منتجات رقمية من الفكرة إلى الإطلاق بسرعة ووضوح.\", \"en\": \"Digital products from idea to launch with clarity.\"}}, {\"title\": {\"ar\": \"القطاع الخدمي\", \"en\": \"Service industries\"}, \"description\": {\"ar\": \"تجارب رقمية احترافية لعملائك وشركائك.\", \"en\": \"Professional digital experiences for clients and partners.\"}}, {\"title\": {\"ar\": \"المؤسسات الكبرى\", \"en\": \"Large organizations\"}, \"description\": {\"ar\": \"حلول قابلة للتوسع بمعايير جودة عالية.\", \"en\": \"Scalable solutions built to high quality standards.\"}}], \"badge_text\": {\"ar\": \"منذ البداية\", \"en\": \"Since day one\"}, \"description\": {\"ar\": \"نبني حلولًا رقمية تتكيف مع طبيعة كل قطاع، من الشركات الناشئة إلى المؤسسات والقطاعات المتخصصة.\", \"en\": \"We build digital solutions tailored to the unique needs of each sector, from startups and enterprises to specialized industries\"}, \"image_media_id\": 34}', 1, 2, '2026-08-30 17:49:36', '2026-09-27 11:29:19'),
(3, 'services', '{\"ar\":\"خدمات متكاملة للشركات التي تسعى للتطور والنمو\",\"en\":\"Integrated services for companies seeking growth and development\"}', '{\"ar\":\"خدماتنا\",\"en\":\"Our Services\"}', '{\"description\": {\"ar\": \"نقدّم حلولًا رقمية عملية صُممت لدعم أعمالك، ورفع الكفاءة، والتطور مع احتياجاتك\", \"en\": \"We provide practical digital solutions designed to support your business, improve efficiency, and grow with your needs\"}}', 1, 3, '2026-08-30 17:49:36', '2026-09-26 17:00:55'),
(4, 'projects', '{\"ar\":\"مشاريعنا.\",\"en\":\"Our Projects.\"}', '{\"ar\":\"معرض الأعمال\",\"en\":\"Portfolio\"}', '{\"description\": {\"ar\": \"حلول برمجية ومشاريع رقمية نفذناها لعملائنا عبر قطاعات متعددة.\", \"en\": \"Software solutions and digital products we have delivered across multiple industries.\"}}', 1, 4, '2026-08-30 17:49:36', '2026-09-02 03:07:09'),
(5, 'business_values', '{\"ar\":\"نعمل بطريقة تناسب أعمالك\",\"en\":\"We work in a way that fits your business\"}', '{\"ar\":\"ما يميزنا\",\"en\":\"What Sets Us Apart\"}', '{\"description\": {\"ar\": \"حلول مرنة، تنفيذ واضح، وشراكة تركز على النتائج من أول خطوة وحتى النمو\", \"en\": \"Flexible solutions, clear execution, and a partnership focused on results from the first step through growth\"}}', 1, 5, '2026-08-30 17:49:36', '2026-09-27 11:49:20'),
(6, 'process', '{\"ar\":\"من الفكرة إلى الإطلاق.\",\"en\":\"From Idea to Launch.\"}', '{\"ar\":\"منهجية العمل\",\"en\":\"Our Work Process\"}', '{\"cta_url\": \"/work\", \"cta_label\": {\"ar\": \"عرض الأعمال\", \"en\": \"View All Work\"}, \"description\": {\"ar\": \"نبدأ بفهم أهدافك، ثم نخطط ونصمم ونبني ونختبر، حتى نصل إلى إطلاق مستقر ودعم مستمر بعد الإطلاق.\", \"en\": \"We start by understanding your goals, then plan, design, build, and test. leading to a stable launch and continuous support beyond release.\"}}', 1, 6, '2026-08-30 17:49:36', '2026-09-27 11:02:48'),
(7, 'technology', '{\"ar\":\"تقنية بلا حدود.\",\"en\":\"Technology Without Limitations.\"}', NULL, '[]', 1, 7, '2026-08-30 17:49:36', '2026-08-30 17:49:36'),
(8, 'statistics', '{\"ar\":\"إنجازات مثبتة.\",\"en\":\"Proven at Scale.\"}', '{\"ar\":\"الأثر\",\"en\":\"Impact\"}', '[]', 1, 8, '2026-08-30 17:49:36', '2026-09-01 20:30:31'),
(9, 'testimonials', '{\"ar\":\"موثوقون من صناع القرار.\",\"en\":\"Trusted by Decision Makers.\"}', NULL, '[]', 1, 9, '2026-08-30 17:49:36', '2026-09-13 07:33:37'),
(10, 'insights', '{\"ar\":\"رؤى ووجهات نظر.\",\"en\":\"Insights & Perspectives.\"}', NULL, '[]', 1, 10, '2026-08-30 17:49:36', '2026-09-13 07:33:37'),
(11, 'cta', '{\"ar\":\"لديك فكرة؟ لنبني شيئاً قوياً.\",\"en\":\"Have an idea? Let’s turn it into something real.\"}', '{\"ar\":\"أخبرنا عن رؤيتك. سنتواصل معك خلال يوم عمل واحد مع الخطوات التالية.\",\"en\":\"Tell us about your vision. We will respond within one business day with next steps.\"}', '{\"cta_url\": \"/contact\", \"eyebrow\": null, \"cta_label\": {\"ar\": \"ابدأ محادثة\", \"en\": \"Start a Conversation\"}, \"description\": null}', 1, 11, '2026-08-30 17:49:36', '2026-09-27 11:52:49'),
(12, 'about', '{\"ar\":\"حلول رقمية مصممة لتطوير أعمالك.\",\"en\":\"Digital solutions designed to grow your business.\"}', '{\"ar\":\"عن الشركة\",\"en\":\"About the Company\"}', '{\"cta_url\": \"/about\", \"cta_label\": {\"ar\": \"المزيد عنا\", \"en\": \"About More\"}, \"since_year\": null, \"description\": {\"ar\": \"من الفكرة إلى الإطلاق، نطوّر مواقع وتطبيقات وحلول برمجية تجمع بين الأداء، سهولة الاستخدام، وقابلية التطور مع نمو شركتك.\", \"en\": \"From idea to impact, we develop websites, applications, and software solutions that combine performance, ease of use, and scalability as your business grows.\"}, \"since_label\": null, \"years_count\": \"8\", \"award_winning\": null, \"progress_text\": {\"ar\": \"رضا عملائنا عن المشاريع والخدمات التي قدمناها.\", \"en\": \"Client satisfaction with the projects and services we’ve delivered.\"}, \"solution_text\": {\"ar\": \"حل واي تك: فرق مخصصة، تسليم تدريجي، وملكية كاملة للكود.\", \"en\": \"YTECH SOLUTION: dedicated teams, incremental delivery, and full code ownership.\"}, \"image_media_id\": 28, \"progress_value\": 96, \"challenge_label\": null, \"experience_label\": null, \"image_two_media_id\": null}', 1, 12, '2026-09-13 07:33:37', '2026-09-26 15:53:04'),
(13, 'wordmark', '{\"ar\":\"واي تك\",\"en\":\"Ytech\"}', NULL, '{\"word\": {\"ar\": \"واي تك\", \"en\": \"Ytech\"}}', 1, 13, '2026-09-13 07:33:37', '2026-09-13 07:33:37'),
(14, 'marquee', '{\"ar\":\"قدراتنا\",\"en\":\"Capabilities\"}', NULL, '{\"items\": [{\"ar\": \"تطوير الويب\", \"en\": \"Web Development\"}, {\"ar\": \"تطبيقات الجوال\", \"en\": \"Mobile Apps\"}, {\"ar\": \"الأنظمة المخصصة\", \"en\": \"Custom Software\"}, {\"ar\": \"تصميم UI/UX\", \"en\": \"UI/UX Design\"}, {\"ar\": \"التجارة الإلكترونية\", \"en\": \"E-commerce\"}, {\"ar\": \"التسويق الرقمي\", \"en\": \"Digital Marketing\"}, {\"ar\": \"تطوير الأعمال\", \"en\": \"Business Development\"}, {\"ar\": \"التعهيد\", \"en\": \"Outsourcing\"}]}', 1, 14, '2026-09-13 07:33:37', '2026-09-26 18:07:55'),
(15, 'team', '{\"ar\":\"تعرّف على فريق العمل.\",\"en\":\"Meet The Team Members.\"}', '{\"ar\":\"فريقنا\",\"en\":\"Our Team\"}', '{\"description\": {\"ar\": \"مهندسون ومصممون ومديرو منتجات يعملون معك مباشرة من الفكرة حتى الإطلاق.\", \"en\": \"Engineers, designers and product leads who work with you directly from idea through launch.\"}}', 1, 15, '2026-09-13 07:33:37', '2026-09-13 07:33:37'),
(16, 'video', '{\"ar\":\"حلول برمجية فريدة لأعمالك\",\"en\":\"Unique Software Solutions for Your Business\"}', '{\"ar\":\"شاهد الفيديو\",\"en\":\"Watch Video\"}', '{\"video_url\": \"/media/hero/ytech-showreel.mp4\"}', 1, 16, '2026-09-13 07:33:37', '2026-09-13 07:33:37'),
(17, 'awards', '{\"ar\":\"تقدير لعملنا.\",\"en\":\"Recognition For Our Work.\"}', '{\"ar\":\"جوائزنا\",\"en\":\"Our Awards\"}', '[]', 1, 17, '2026-09-13 07:33:37', '2026-09-13 07:33:37');

-- --------------------------------------------------------

--
-- Table structure for table `jobs`
--

CREATE TABLE `jobs` (
  `id` bigint UNSIGNED NOT NULL,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint UNSIGNED NOT NULL,
  `reserved_at` int UNSIGNED DEFAULT NULL,
  `available_at` int UNSIGNED NOT NULL,
  `created_at` int UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `job_batches`
--

CREATE TABLE `job_batches` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `media_files`
--

CREATE TABLE `media_files` (
  `id` bigint UNSIGNED NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size` bigint UNSIGNED NOT NULL DEFAULT '0',
  `alt_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `disk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'public',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

