(3, '{\"ar\":\"التطوير\",\"en\":\"Development\"}', '{\"ar\":\"سprints رشيقة مع عروض منتظمة تبقيك على اطلاع. نبني ونختبر ونكرر بناءً على ملاحظاتك.\",\"en\":\"Agile sprints with regular demos keep you informed. We build, test, and iterate based on your feedback.\"}', 3, 'code', NULL, 3, '2026-08-30 17:49:36', '2026-08-30 17:49:36'),
