INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(6, '{\"ar\":\"نظام المشتريات\",\"en\":\"Procurement System\"}', 'procurement-system', NULL, NULL, NULL, 'business_systems', '{\"ar\":\"نظام ويب متكامل لإدارة المشتريات والتوريد يغطي الرحلة الكاملة من طلب الشراء حتى الدفع والتقارير المالية في منصة واحدة مربوطة بصلاحيات وتتبع لكل خطوة.\",\"en\":\"An integrated web-based procurement and supply management system covering the full journey from purchase request to payment and financial reporting all in one connected platform with role-based access and full traceability.\"}', '{\"ar\":\"نظام إدارة المشتريات والتوريد (Procurement Management System) هو حل برمجي مخصص لشركات المقاولات والتوريد وشركات الـ procurement التي تتعامل مع عملاء كبار ومشاريع ضخمة وعقود معقدة.\\r\\n\\r\\nالنظام يوحّد كل عمليات الشراء في قاعدة بيانات واحدة مترابطة: من طلب الشراء (PR) مروراً بـ طلب عروض الأسعار (RFQ) والتسعير الداخلي ومراجعة المحاسب، ثم أوامر الشراء (PO) والتسليم والفواتير، وصولاً إلى طلبات الدفع وإقرارات الدفع والتقارير الإدارية.\\r\\n\\r\\nيدعم النظام سنوات متعددة (2024–2026)، عملات وأسعار صرف متعددة، تصدير واستيراد Excel، تقارير KPI جاهزة، وتتبع العمولات والتكلفة الفعلية والربح مما يجعله مناسباً للشركات ذات الحجم المتوسط والكبير التي تحتاج رؤية مالية ولوجستية لحظية.\",\"en\":\"The Procurement Management System is a specialized software solution for construction, supply, and procurement companies working with large clients, mega-projects, and complex contracts.\\r\\n\\r\\nThe system unifies all purchasing operations in a single interconnected database: from Purchase Requests (PR) through Request for Quotation (RFQ), internal cost estimation, and accountant review, to Purchase Orders (PO), delivery, invoicing, payment requests, payment acknowledgements, and management reports.\\r\\n\\r\\nIt supports multiple fiscal years (2024–2026), multi-currency exchange rates, Excel import\\/export, ready-made KPI reports, and commission, actual cost, and profit tracking making it ideal for medium-to-large companies that need real-time financial and logistical visibility.\"}', '{\"ar\":\"معظم شركات التوريد والمشتريات ما زالت تعتمد على Excel والإيميلات وواتساب لإدارة عملياتها، مما يسبب:\\r\\n\\r\\nبيانات متفرقة: ملفات منفصلة غير مربوطة ببعضها\\r\\nفقدان التتبع : لا يُعرف من وافق ومتى ولماذا\\r\\nتأخير الموافقات : المحاسب ينتظر الملفات خارج النظام\\r\\nفصل PO عن التسليم والفواتير : أوامر شراء غير مربوطة بالواقع\\r\\nفوضى في المدفوعات : بدون أرقام مرجعية أو إثباتات منظمة\\r\\nغياب الرؤية الإدارية : الإدارة لا تملك أرقاماً لحظية للقرار\",\"en\":\"Most supply and procurement companies still rely on Excel, email, and WhatsApp to manage their operations, causing:\\r\\n\\r\\nScattered data : separate, unlinked files across departments\\r\\nNo traceability : unclear who approved what, when, and why\\r\\nDelayed approvals : accountants waiting for files outside the system\\r\\nDisconnected POs : purchase orders not linked to delivery and invoicing\\r\\nPayment chaos : no reference numbers or organized proof of payment\\r\\nLack of management visibility : leadership without real-time data for decisions\"}', '{\"ar\":\"منصة ويب واحدة تربط كل مراحل دورة المشتريات في مسار عمل متسلسل ومحكم:\\r\\n\\r\\nطلب شراء → موافقات → RFQ → تسعير داخلي → مراجعة محاسب → PO → تسليم → فواتير → دفع → تقارير\\r\\n\\r\\nكل خطوة مربوطة بالتي قبلها لا يوجد PO بدون RFQ، ولا دفع بدون مسار موافقات. النظام يوفر:\\r\\n\\r\\nWorkflow موافقات مع قوائم رفض وتعديل\\r\\nتسعير متعدد العملات مع أسعار صرف تلقائية أو مخصصة\\r\\nربط كامل بين RFQ و PO والتسليم والفواتير والدفع\\r\\nتقارير إدارية جاهزة (KPI، VAT، AR، forecast، عمولات)\\r\\nصلاحيات دقيقة لكل قسم (مشتريات، محاسب، مدير موقع)\",\"en\":\"A single web platform that connects every stage of the procurement cycle in a structured, controlled workflow:\\r\\n\\r\\nPurchase Request → Approvals → RFQ → Cost Estimation → Accountant Review → PO → Delivery → Invoices → Payment → Reports\\r\\n\\r\\nEach step is linked to the previous one — no PO without an RFQ, no payment without an approval path. The system provides:\\r\\n\\r\\nApproval workflows with rejection and revision queues\\r\\nMulti-currency pricing with automatic or custom exchange rates\\r\\nFull linkage between RFQ, PO, delivery, invoices, and payments\\r\\nReady-made management reports (KPI, VAT, AR, forecast, commissions)\\r\\nGranular permissions per department (procurement, accountant, site manager)\"}', NULL, NULL, NULL, '[{\"ar\": \"الطلبات والموافقات\", \"en\": \"Requests & Approvals\"}, {\"ar\": \"RFQ (طلب عروض أسعار)\", \"en\": \"RFQ (Request for Quotation)\"}, {\"ar\": \"التسعير والمحاسبة\", \"en\": \"Pricing & Accounting\"}, {\"ar\": \"أوامر الشراء\", \"en\": \"Purchase Orders (PO)\"}, {\"ar\": \"التسليم والمخزن\", \"en\": \"Delivery & Warehouse\"}, {\"ar\": \"الفواتير\", \"en\": \"Invoicing\"}, {\"ar\": \"المدفوعات\", \"en\": \"Payments\"}, {\"ar\": \"التكاليف والأرباح\", \"en\": \"Costs & Profit\"}, {\"ar\": \"الإعدادات والبيانات الأساسية\", \"en\": \"Settings & Master Data\"}, {\"ar\": \"التقارير والإدارة\", \"en\": \"Reports & Management\"}, {\"ar\": \"الأمان والتحكم\", \"en\": \"Security & Access Control\"}]', NULL, NULL, NULL, 4, NULL, NULL, NULL, NULL, 1, 'published', 1, NULL, NULL, '2026-09-02 03:01:21', '2026-09-02 04:42:03', NULL),
(7, '{\"ar\":\"نظام العقارات\",\"en\":\"Property System\"}', 'property-system', NULL, NULL, NULL, 'business_systems', '{\"ar\":\"Real Estate All-Stars منصة ويب متكاملة لأول مسابقة عقارية ترفيهية في العالم تربط المتسابقين والحكام والرعاة والجمهور عبر التسجيل والتصويت والدفع وإدارة مراحل المنافسة.\",\"en\":\"Real Estate All-Stars is a full-stack web platform for the world’s first entertainment-based real estate talent competition connecting contestants, judges, sponsors, and audiences through registration, voting, payments, and multi-stage competition management.\"}', '{\"ar\":\"Real Estate All-Stars منصة رقمية شاملة لمسابقة عقارية كبرى لاكتشاف وتمييز أفضل مواهب المبيعات العقارية. تتكون من موقع عام للجمهور ولوحة تحكم إدارية قوية، تتيح للمتخصصين في العقارات التسجيل والمنافسة عبر مراحل متعددة ورفع الفيديوهات والحصول على أصوات الجمهور بينما يدير المنظمون دورة المسابقة بالكامل من لوحة تحكم مركزية.\\r\\n\\r\\nالمنصة تدعم العربية والإنجليزية، وتتكامل مع بوابات الدفع الإلكتروني (Fawaterak)، وتشمل أدوات للشركاء والرعاة والجهات الحكومية والحكام وإدارة المحتوى. هدفها رفع معايير القطاع وإبراز المواهب وتقديم تجربة تفاعلية للمشاركين والجمهور.\",\"en\":\"Real Estate All-Stars is an end-to-end digital platform built for a large-scale real estate talent competition. It consists of a public-facing website and a powerful admin panel, enabling real estate professionals to register, compete across multiple stages, upload videos, and gain public votes while organizers manage the full lifecycle of the competition from a centralized dashboard.\\r\\n\\r\\nThe platform supports Arabic and English, integrates online payments (Fawaterak), and includes tools for partners, sponsors, government entities, judges, and content management. It was designed to elevate industry standards, showcase talent, and create an interactive experience for both participants and the public.\"}', '{\"ar\":\"قطاع العقارات كان يفتقر لمنصة مخصصة لاكتشاف وتقييم والاحتفاء بأفضل مواهب المبيعات بطريقة منظمة وجذابة وقابلة للتوسع. المسابقات التقليدية اعتمدت على عمليات يدوية تسجيل ورقي، تصويت غير إلكتروني، وتواصل مجزأ مما أدى إلى:\\r\\n\\r\\nصعوبة إدارة آلاف المتسابقين عبر مراحل متعددة\\r\\nعدم إمكانية تصويت عام عادل وشفاف\\r\\nصعوبة معالجة مدفوعات باقات التصويت والتسجيل\\r\\nتعقيد تنسيق الرعاة والشركاء والحكام والجهات الحكومية\\r\\nغياب تجربة رقمية احترافية ثنائية اللغة\",\"en\":\"The real estate industry lacked a dedicated platform to discover, evaluate, and celebrate top sales talent in a structured, engaging, and scalable way. Traditional competitions relied on manual processes paper registrations, offline voting, and fragmented communication making it difficult to:\\r\\n\\r\\nManage thousands of contestants across multiple competition stages\\r\\nEnable fair, transparent public voting\\r\\nHandle payments for vote packages and registrations\\r\\nCoordinate sponsors, partners, judges, and government stakeholders\\r\\nDeliver a bilingual, professional digital experience\"}', '{\"ar\":\"بنينا منصة مزدوجة متكاملة رقّمت دورة المسابقة بالكامل:\\r\\n\\r\\nالموقع العام: يتسجل المتسابقون مع التحقق عبر OTP، ويرفعون بياناتهم وفيديوهاتهم، ويتنافسون على أصوات الجمهور. يمكن للمستخدمين تصفح المتسابقين والتصويت يومياً وشراء أصوات إضافية واستكشاف الأخبار والمشاريع وتفاصيل البرنامج.\\r\\nلوحة التحكم: يدير المنظمون المتسابقين عبر 3 مراحل، ويوافقون أو يرفضون المشاركين، ويحددون الفائزين، ويضبطون محتوى الموقع (CMS)، ويديرون الصلاحيات، ويولّدون تقارير (PDF\\/Excel)، ويشرفون على المدفوعات والشراكات.\\r\\nالحل يمركز العمليات، يؤتمت سير العمل، ويقدم تجربة ثنائية اللغة تلائم حجم ومكانة البرنامج.\",\"en\":\"We built a comprehensive dual-application platform that digitizes the entire competition lifecycle:\\r\\n\\r\\nPublic Website: Contestants register with OTP verification, upload profile data and videos, and compete for public votes. Users can browse contestants, vote daily, purchase extra votes, and explore news, projects, and program details.\\r\\nAdmin Panel: Organizers manage contestants through 3 competition stages, approve\\/reject participants, mark winners, configure all website content (CMS), manage roles & permissions, generate reports (PDF\\/Excel), and oversee payments and partnerships.\\r\\nThe solution centralizes operations, automates workflows, and delivers a polished bilingual experience aligned with the scale and prestige of the program.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المتسابقين\", \"en\": \"Contestant Management\"}, \"points\": [{\"ar\": \"تسجيل متعدد الخطوات مع التحقق عبر OTP\", \"en\": \"Multi-step registration with OTP phone verification\"}, {\"ar\": \"الملف الشخصي والخبرة ومجالات التخصص ورفع الفيديوهات\", \"en\": \"Profile, experience, expertise areas, and video uploads\"}, {\"ar\": \"سير عمل مراجعة متعدد المراحل (المرحلة 1 → 2 → 3)\", \"en\": \"Multi-stage review workflow (Stage 1 → Stage 2 → Stage 3)\"}, {\"ar\": \"اختيار الفائزين وإدارة الحالات\", \"en\": \"Winner selection and status management\"}]}, {\"title\": {\"ar\": \"نظام التصويت\", \"en\": \"Voting System\"}, \"points\": [{\"ar\": \"أصوات مجانية يومية لكل مستخدم\", \"en\": \"Daily free votes per user\"}, {\"ar\": \"شراء أصوات إضافية عبر بوابة الدفع\", \"en\": \"Purchase additional votes via integrated payment gateway\"}, {\"ar\": \"تتبع الأصوات ولوحات المتصدرين\", \"en\": \"Real-time vote tracking and leaderboards\"}, {\"ar\": \"متابعة/إبداء اهتمام بالمتسابقين\", \"en\": \"Interest/follow contestants\"}]}, {\"title\": {\"ar\": \"تكامل الدفع\", \"en\": \"Payment Integration\"}, \"points\": [{\"ar\": \"بوابة Fawaterak (بطاقة ائتمان، فوري، ميزة QR)\", \"en\": \"Fawaterak gateway (Credit Card, Fawry, Meeza QR)\"}, {\"ar\": \"شراء باقات التصويت\", \"en\": \"Vote package purchases\"}, {\"ar\": \"دعم أكواد الخصم (Promo Codes)\", \"en\": \"Promo code support\"}, {\"ar\": \"Webhooks وتتبع حالة الدفع\", \"en\": \"Payment webhooks and status tracking\"}]}, {\"title\": {\"ar\": \"إدارة المحتوى (CMS)\", \"en\": \"Content Management (CMS)\"}, \"points\": [{\"ar\": \"الصفحة الرئيسية الديناميكية (Hero، عد تنازلي، البرنامج، الرعاة، الشركاء)\", \"en\": \"Dynamic homepage (hero, countdown, program, sponsors, partners)\"}, {\"ar\": \"صفحات من نحن، الأسئلة الشائعة، كيف يعمل البرنامج، الشروط والأحكام\", \"en\": \"About, FAQ, How It Works, Terms & Conditions pages\"}, {\"ar\": \"الأخبار والتحديثات مع التصنيفات\", \"en\": \"News & Updates with categories\"}, {\"ar\": \"أقسام الحكام والمقدمين والجهات الحكومية\", \"en\": \"Judges, Presenters, and Government sections\"}, {\"ar\": \"عرض المشاريع والمناطق والمطورين\", \"en\": \"Projects, Areas, and Developers showcase\"}]}, {\"title\": {\"ar\": \"وحدة الشراكات\", \"en\": \"Partnerships Module\"}, \"points\": [{\"ar\": \"تسجيل وإدارة الشركاء\", \"en\": \"Partner registration and management\"}, {\"ar\": \"انضمام الرعاة وعرض المزايا\", \"en\": \"Sponsor onboarding and benefits display\"}, {\"ar\": \"قسم المشاركة الحكومية\", \"en\": \"Government participation section\"}, {\"ar\": \"قوائم المطورين والمشاريع\", \"en\": \"Developer and project listings\"}]}, {\"title\": {\"ar\": \"لوحة التحكم الإدارية\", \"en\": \"Admin Dashboard\"}, \"points\": [{\"ar\": \"صلاحيات حسب الأدوار\", \"en\": \"Role-based access control\"}, {\"ar\": \"موافقة المتسابقين عبر 3 مراحل\", \"en\": \"Contestant approval across 3 stages\"}, {\"ar\": \"تقارير: الأكثر تصويتاً، أحدث المتسابقين، المهتمين\", \"en\": \"Reports: most voted, latest contestants, interested users\"}, {\"ar\": \"تصدير PDF و Excel\", \"en\": \"Export to PDF and Excel\"}, {\"ar\": \"إدارة المستخدمين (إيقاف/استعادة الحسابات)\", \"en\": \"User management (pause/restore accounts)\"}, {\"ar\": \"لوحة الحكام للمرحلة النهائية\", \"en\": \"Referee panel for final-stage judging\"}, {\"ar\": \"إعدادات الموقع والنسخ الاحتياطي\", \"en\": \"Full website settings and backup\"}]}, {\"title\": {\"ar\": \"تجربة المستخدم\", \"en\": \"User Experience\"}, \"points\": [{\"ar\": \"دعم ثنائي اللغة (عربي / إنجليزي)\", \"en\": \"Bilingual support (Arabic / English)\"}, {\"ar\": \"تصميم متجاوب بـ Tailwind CSS\", \"en\": \"Responsive design with Tailwind CSS\"}, {\"ar\": \"استعادة كلمة المرور عبر OTP على الموبايل\", \"en\": \"Mobile-friendly OTP password reset\"}, {\"ar\": \"بحث وتصفية المتسابقين\", \"en\": \"Search and filter contestants\"}, {\"ar\": \"نماذج التواصل وإدارة الاستفسارات\", \"en\": \"Contact forms and inquiry management\"}]}]', NULL, NULL, NULL, 43, NULL, NULL, NULL, NULL, 1, 'published', 2, NULL, NULL, '2026-09-02 03:01:21', '2026-10-01 06:16:07', NULL),
(8, '{\"ar\":\"نظام الحج\",\"en\":\"Haj System\"}', 'haj-system', NULL, NULL, NULL, 'business_systems', '{\"ar\":\"تفاصيل المشروع قيد الإضافة.\",\"en\":\"Project details coming soon.\"}', '{\"ar\":\"تفاصيل المشروع قيد الإضافة.\",\"en\":\"Project details coming soon.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'published', 3, NULL, NULL, '2026-09-02 03:01:21', '2026-09-02 19:57:41', '2026-09-02 19:57:41'),
(9, '{\"ar\":\"دبابي\",\"en\":\"Dababi\"}', 'dababi', NULL, NULL, NULL, 'other', '{\"ar\":\"دبابي منصة تجارة إلكترونية متخصصة في بيع وشراء الدراجات النارية وقطع الغيار والإكسسوارات في المملكة العربية السعودية، مع خدمات مرتبطة مثل الورش، الشحن، نقل الملكية، والتدريب عبر موقع ويب وتطبيق موبايل.\",\"en\":\"Project details coming soon.Dababi is a specialized e-commerce marketplace for buying and selling motorcycles, spare parts, and accessories in Saudi Arabia, with related services such as workshops, shipping, ownership transfer, and training delivered via web and mobile app.\"}', '{\"ar\":\"دبابي منصة رقمية متكاملة تربط بين المشترين والبائعين ومقدمي الخدمات في قطاع الدراجات النارية بالسعودية. المنصة ليست متجرًا عامًا فقط، بل نظام بيئي متخصص يدعم:\\r\\n\\r\\nبيع المنتجات (دراجات، قطع غيار، إكسسوارات)\\r\\nالتفاوض على السعر عبر عروض الشراء\\r\\nحجز وطلب خدمات متخصصة (ورشة، مواقف، تلميع، نقل ملكية، تدريب، شحن)\\r\\nربط المنتجات والخدمات بمواصفات الدراجة (النوع، الماركة، المقاس، السنة)\\r\\nتكامل مع بوابات الدفع المحلية (PayTabs) وشركات الشحن (OTO)\\r\\nلوحات تحكم للإدارة والبائعين ومندوبي التوصيل\\r\\nREST API لتطبيق الموبايل (Laravel Sanctum)\\r\\nالمنصة ثنائية اللغة (عربي \\/ إنجليزي) مع دعم RTL، وتستهدف تجربة تسوق آمنة وموثوقة لعشاق الدراجات في السوق السعودي.\",\"en\":\"Dababi is a full-stack digital platform that connects buyers, sellers, and service providers in Saudi Arabia’s motorcycle sector. It is not a generic store it is a specialized ecosystem supporting:\\r\\n\\r\\nProduct sales (motorcycles, spare parts, accessories)\\r\\nPrice negotiation through purchase offers\\r\\nBooking and ordering specialized services (workshop, parking, polishing, ownership transfer, training, shipping)\\r\\nLinking products and services to bike specs (type, brand, size, year)\\r\\nIntegration with local payment gateways (PayTabs) and logistics (OTO)\\r\\nAdmin, seller, and delivery dashboards\\r\\nREST API for the mobile app (Laravel Sanctum)\\r\\nThe platform is bilingual (Arabic \\/ English) with RTL support, aimed at a safe and trusted shopping experience for motorcycle enthusiasts in the Saudi market.\"}', '{\"ar\":\"سوق الدراجات النارية في السعودية كان يعتمد بشكل كبير على قنوات غير منظمة: مجموعات التواصل، الإعلانات المبعثرة، والصفحات الشخصية. هذا أدى إلى:\\r\\n\\r\\nصعوبة إيجاد قطع غيار متوافقة مع نوع وموديل الدراجة\\r\\nغياب منصة موحدة تجمع البيع والخدمات (صيانة، شحن، نقل ملكية) في مكان واحد\\r\\nضعف الثقة بين البائع والمشتري وغياب آليات واضحة للدفع والتتبع\\r\\nصعوبة التفاوض على الأسعار خاصة للدراجات المستعملة\\r\\nتعقيد إدارة الشحن والتوصيل للبائعين بدون تكامل لوجستي\\r\\nغياب تجربة رقمية احترافية باللغة العربية تناسب السوق المحلي\",\"en\":\"Saudi Arabia’s motorcycle market relied heavily on unstructured channels: social groups, scattered classified ads, and personal pages. This led to:\\r\\n\\r\\nDifficulty finding spare parts compatible with a specific bike type and model\\r\\nNo unified platform combining sales and services (maintenance, shipping, ownership transfer)\\r\\nLow trust between buyers and sellers, with weak payment and tracking mechanisms\\r\\nHard price negotiation, especially for used motorcycles\\r\\nComplex shipping and fulfillment for sellers without logistics integration\\r\\nLack of a professional Arabic-first digital experience for the local market\"}', '{\"ar\":\"تم بناء دبابي كمنصة متخصصة end-to-end تجمع التجارة الإلكترونية متعددة البائعين مع خدمات قطاع الدراجات في نظام واحد:\\r\\n\\r\\nسوق منتجات مع تصنيفات، ماركات، فلاتر، ومقارنة وقوائم أمنيات\\r\\nعروض شراء تسمح للمشتري بتقديم سعر مقترح للبائع\\r\\nسوق خدمات بأنواع محددة (ورشة، مواقف، تلميع، نقل ملكية، تدريب، شحن عادي ومخصص)\\r\\nمواصفات الدراجة (نوع، ماركة، مقاس، سنة) مدمجة في طلبات الخدمة والشحن\\r\\nتكامل OTO لمزامنة نقاط الاستلام والشحن\\r\\nدفع إلكتروني عبر PayTabs وبوابات أخرى\\r\\nتطبيق موبايل عبر API كامل (تسجيل، OTP، تسجيل اجتماعي، طلبات، خدمات)\\r\\nلوحات تحكم للإدارة، البائعين، ومندوبي التوصيل مع تقارير وعمولات\",\"en\":\"Dababi was built as a specialized end-to-end platform combining multi-vendor e-commerce with motorcycle-sector services in one system:\\r\\n\\r\\nProduct marketplace with categories, brands, filters, compare, and wishlists\\r\\nPurchase offers so buyers can submit a proposed price to sellers\\r\\nServices marketplace with defined types (workshop, parking, polishing, ownership transfer, training, standard and custom shipping)\\r\\nVehicle specs (type, brand, size, year) embedded in service and shipping orders\\r\\nOTO integration for pickup locations and shipping sync\\r\\nOnline payments via PayTabs and other gateways\\r\\nMobile app backed by a full API (auth, OTP, social login, orders, services)\\r\\nDashboards for admin, sellers, and delivery staff with reports and commissions\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"التجارة الإلكترونية\", \"en\": \"E-Commerce\"}, \"points\": [{\"ar\": \"متجر متعدد البائعين (Multi-Vendor)\", \"en\": \"Multi-vendor marketplace\"}, {\"ar\": \"دراجات نارية، قطع غيار، وإكسسوارات\", \"en\": \"Motorcycles, spare parts, and accessories\"}, {\"ar\": \"سلة مشتريات، Checkout، كوبونات، وعروض Flash Deals\", \"en\": \"Cart, checkout, coupons, and flash deals\"}, {\"ar\": \"منتجات رقمية ومنتجات مبوبة (Classified)\", \"en\": \"Digital and classified products\"}, {\"ar\": \"مزادات (Auction) وبيع جملة (Wholesale)\", \"en\": \"Auctions and wholesale\"}, {\"ar\": \"مقارنة منتجات وقائمة أمنيات\", \"en\": \"Product compare and wishlist\"}, {\"ar\": \"تقييمات ومراجعات\", \"en\": \"Ratings and reviews\"}, {\"ar\": \"استفسارات المنتجات ومحادثات بين البائع والمشتري\", \"en\": \"Product queries and buyer–seller messaging\"}]}, {\"title\": {\"ar\": \"ميزات مخصصة لدبابي\", \"en\": \"Dababi-Specific\"}, \"points\": [{\"ar\": \"عروض الشراء (Purchase Offers) — حتى 3 عروض لكل منتج\", \"en\": \"Purchase offers — up to 3 offers per product\"}, {\"ar\": \"سوق الخدمات: ورشة، مواقف، تلميع، نقل ملكية، تدريب، شحن\", \"en\": \"Services marketplace: workshop, parking, polishing, ownership transfer, training, shipping\"}, {\"ar\": \"باقات خدمات مع مواعيد وساعات عمل\", \"en\": \"Service packages with scheduling and work hours\"}, {\"ar\": \"مواصفات الدراجة (نوع / ماركة / مقاس / سنة)\", \"en\": \"Vehicle specs (type / brand / size / year)\"}, {\"ar\": \"شحن مخصص بين مناطق ومدن مختلفة\", \"en\": \"Custom inter-city / inter-region shipping\"}, {\"ar\": \"تكامل OTO للشحن ونقاط الاستلام\", \"en\": \"OTO shipping and pickup location integration\"}, {\"ar\": \"أنواع شاحنات مرتبطة بخدمات الشحن\", \"en\": \"Truck types linked to shipping services\"}]}, {\"title\": {\"ar\": \"المستخدمون والصلاحيات\", \"en\": \"Users & Roles\"}, \"points\": [{\"ar\": \"تسجيل دخول بالبريد / OTP / تسجيل اجتماعي (Google, Apple, وغيرها)\", \"en\": \"Email / OTP / social login (Google, Apple, etc.)\"}, {\"ar\": \"لوحة تحكم العميل (طلبات، عروض، خدمات، محفظة)\", \"en\": \"Customer dashboard (orders, offers, services, wallet)\"}, {\"ar\": \"لوحة تحكم البائع (منتجات، خدمات، طلبات، سحب أرباح، POS)\", \"en\": \"Seller dashboard (products, services, orders, withdrawals, POS)\"}, {\"ar\": \"لوحة تحكم الإدارة (إعدادات، تقارير، عمولات، موافقات)\", \"en\": \"Admin panel (settings, reports, commissions, approvals)\"}, {\"ar\": \"مندوبو التوصيل (Delivery Boy) مع تتبع الحالة\", \"en\": \"Delivery staff with status tracking\"}, {\"ar\": \"نظام صلاحيات وأدوار (Spatie Permission)\", \"en\": \"Role-based permissions (Spatie Permission)\"}]}, {\"title\": {\"ar\": \"الدفع والمالية\", \"en\": \"Payments & Finance\"}, \"points\": [{\"ar\": \"PayTabs وبوابات دفع متعددة (Stripe, PayPal, Razorpay, وغيرها)\", \"en\": \"PayTabs and multiple gateways (Stripe, PayPal, Razorpay, etc.)\"}, {\"ar\": \"الدفع عند الاستلام (COD)\", \"en\": \"Cash on delivery (COD)\"}, {\"ar\": \"محفظة إلكترونية (Wallet)\", \"en\": \"Digital wallet\"}, {\"ar\": \"طلبات استرداد (Refund)\", \"en\": \"Refund requests\"}, {\"ar\": \"باقات بائعين وعمولات\", \"en\": \"Seller packages and commissions\"}]}]', NULL, NULL, NULL, 9, NULL, NULL, NULL, NULL, 0, 'published', 4, NULL, NULL, '2026-09-02 03:01:21', '2026-09-02 08:01:09', NULL),
(10, '{\"ar\":\"تعمير\",\"en\":\"Tameer\"}', 'tameer', NULL, NULL, NULL, 'business_systems', '{\"ar\":\"تفاصيل المشروع قيد الإضافة.\",\"en\":\"Project details coming soon.\"}', '{\"ar\":\"تفاصيل المشروع قيد الإضافة.\",\"en\":\"Project details coming soon.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 'published', 5, NULL, NULL, '2026-09-02 03:01:21', '2026-09-06 06:04:21', '2026-09-06 06:04:21'),
(11, '{\"ar\":\"أكام\",\"en\":\"Akam\"}', 'akam', NULL, NULL, NULL, 'business_systems', '{\"ar\":\"نظام رقمي لإدارة حجوزات المستودعات وحركة الشاحنات وتتبع الأصول، يربط المندوبين والمشغّلين والمستودعات في منصة واحدة.\",\"en\":\"A digital platform for warehouse booking, truck scheduling, and asset tracking connecting representatives, operators, and storage sites in one system.\"}', '{\"ar\":\"Akam منصة متكاملة لإدارة عمليات التخزين واللوجستيات، تتيح حجز مواعيد دخول وخروج الشاحنات (Inbound \\/ Outbound)، متابعة المخزون والأصول، إدارة المستودعات ووحدات التخزين، وتنظيم صلاحيات المستخدمين (مسؤول \\/ مندوب \\/ مشغّل). يدعم رفع المستندات والصور المرتبطة بكل عملية، مع تقارير وتحليلات تساعد على متابعة الأداء واتخاذ القرار.\",\"en\":\"Akam is an integrated warehouse and logistics management platform that streamlines inbound and outbound truck bookings, inventory and asset tracking, warehouse and storage unit management, and role-based access for admins, representatives, and operators. It supports document and image uploads for every transaction, plus reporting and checklists that improve operational visibility and decision-making.\"}', '{\"ar\":\"عمليات المستودعات كانت تعتمد على التنسيق اليدوي والتواصل المتكرر، مما يسبب تعارض مواعيد الشاحنات، صعوبة تتبع الكميات المستلمة والمصروفة، تشتت المستندات، وضعف الرؤية على حركة الأصول عبر المواقع والفرق.\",\"en\":\"Warehouse operations relied on manual coordination and fragmented communication, leading to conflicting truck schedules, weak tracking of received and released quantities, scattered documents, and limited visibility across sites and teams.\"}', '{\"ar\":\"بناء نظام API مركزي ينظّم الحجوزات، يربط كل عملية بمستودع ووحدة تخزين ومستخدمين محددين، يتتبع الكميات والمستندات، ويدعم الموافقات والتقارير لتقليل الأخطاء وتحسين الشفافية والكفاءة التشغيلية.\",\"en\":\"A centralized API-driven system that organizes bookings, links each transaction to warehouses, storage units, and users, tracks quantities and documents, and provides approvals and reports reducing errors while improving transparency and operational efficiency.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة الحجوزات والشاحنات\", \"en\": \"Booking & Truck Management\"}, \"points\": [{\"ar\": \"حجز مواعيد الدخول والخروج (Inbound / Outbound)\", \"en\": \"Schedule inbound and outbound appointments\"}, {\"ar\": \"تحديد أنواع الشاحنات وكمياتها (كبيرة / متوسطة / صغيرة)\", \"en\": \"Define truck types and quantities (big / medium / small)\"}, {\"ar\": \"تسجيل بيانات السائق واللوحة والإقامة\", \"en\": \"Capture driver, license plate, and Iqama details\"}, {\"ar\": \"متابعة وقت الوصول والمغادرة الفعلي\", \"en\": \"Track actual arrival and departure times\"}, {\"ar\": \"رقم مرجعي تلقائي لكل حجز\", \"en\": \"Auto-generate a unique booking reference number\"}]}, {\"title\": {\"ar\": \"إدارة المستودعات والتخزين\", \"en\": \"Warehouse & Storage Management\"}, \"points\": [{\"ar\": \"إدارة المستودعات ووحدات التخزين\", \"en\": \"Manage warehouses and storage units\"}, {\"ar\": \"ربط المستخدمين بالمستودعات حسب الصلاحية\", \"en\": \"Assign users to storage locations by role\"}, {\"ar\": \"تنظيم العمليات حسب رقم التخزين والموقع\", \"en\": \"Organize operations by storage number and site\"}]}, {\"title\": {\"ar\": \"تتبع الأصول والمخزون\", \"en\": \"Asset & Inventory Tracking\"}, \"points\": [{\"ar\": \"تسجيل الكميات المستلمة والمصروفة\", \"en\": \"Record received and released quantities\"}, {\"ar\": \"حساب الكميات المتبقية تلقائيًا\", \"en\": \"Calculate remaining stock automatically\"}, {\"ar\": \"قبول أو رفض الكميات\", \"en\": \"Accept or reject quantity updates\"}, {\"ar\": \"عرض الأصول حسب المندوب مع فلاتر بحث\", \"en\": \"View and filter assets by representative\"}]}, {\"title\": {\"ar\": \"إدارة المستخدمين والصلاحيات\", \"en\": \"User & Role Management\"}, \"points\": [{\"ar\": \"أدوار متعددة: مسؤول، مندوب، مشغّل\", \"en\": \"Multi-role access: Admin, Representative, Operator\"}, {\"ar\": \"إنشاء وتعديل وحذف المندوبين والمشغّلين\", \"en\": \"Create, update, and remove representatives and operators\"}, {\"ar\": \"ربط كل مشغّل بمندوبه ومستودعاته\", \"en\": \"Link each operator to their representative and storages\"}]}, {\"title\": {\"ar\": \"المستندات والمرفقات\", \"en\": \"Documents & Attachments\"}, \"points\": [{\"ar\": \"رفع قوائم التعبئة ومذكرات التسليم\", \"en\": \"Upload packing lists and delivery notes\"}, {\"ar\": \"صور السائق والشاحنة والأصناف والإقامة\", \"en\": \"Attach driver, truck, item, and Iqama images\"}, {\"ar\": \"تحديث أو حذف الملفات المرتبطة بالحجز\", \"en\": \"Update or remove files linked to bookings\"}]}, {\"title\": {\"ar\": \"التقارير والمتابعة\", \"en\": \"Reports & Monitoring\"}, \"points\": [{\"ar\": \"تقارير الحجوزات الأساسية والمتقدمة\", \"en\": \"Basic and advanced booking reports\"}, {\"ar\": \"فلترة حسب المستودع، نوع العملية، والمشغّل\", \"en\": \"Filter by warehouse, transaction type, and operator\"}, {\"ar\": \"قوائم تحقق (Checklist) مرتبطة بالعمليات\", \"en\": \"Checklists tied to operational workflows\"}, {\"ar\": \"عرض العناصر حسب تاريخ الاستلام واسم الموقع\", \"en\": \"Retrieve items by receive date and site name\"}]}, {\"title\": {\"ar\": \"المنتجات والعملاء\", \"en\": \"Products & Clients\"}, \"points\": [{\"ar\": \"تصنيفات رئيسية وفرعية للمنتجات\", \"en\": \"Parent and sub-category product structure\"}, {\"ar\": \"تفاصيل المنتجات حسب الفئة\", \"en\": \"Product details by category\"}, {\"ar\": \"إدارة بيانات العملاء\", \"en\": \"Client data management\"}]}]', NULL, NULL, NULL, 21, NULL, NULL, NULL, NULL, 0, 'published', 6, NULL, NULL, '2026-09-02 03:01:21', '2026-09-09 07:52:47', NULL),
