(16, '{\"ar\":\"سيستم مصر مودرن كلينكس\",\"en\":\"Misr Modern Clinics System\"}', 'misr-modern-clinics-system', NULL, NULL, NULL, 'web', '{\"ar\":\"نظام إدارة متكامل لمراكز وعيادات مصر الحديثة لإدارة المرضى، المواعيد، الأطباء، المالية، والمخزون من لوحة واحدة.\",\"en\":\"An all-in-one clinic management system for Misr Modern Center to manage patients, appointments, doctors, finance, and inventory from a single platform.\"}', '{\"ar\":\"عيادات مصر الحديثة منصة ويب لإدارة تشغيل المراكز الطبية بشكل رقمي كامل. النظام يدعم أدوار متعددة (إدارة المركز، الأطباء، ولوحة إشراف عامة)، ويغطي دورة العمل من استقبال المريض حتى الفواتير والتقارير، مع دعم جلسات العلاج، الأشعة، العمليات، التأمين، والموارد البشرية.\",\"en\":\"Misr Modern Clinics is a web platform that digitizes the full operations of a medical center. It supports multiple roles (center admin, doctors, and a supervisory dashboard) and covers the workflow from patient intake to invoicing and reporting including treatment sessions, radiology, operations, insurance, and HR.\"}', '{\"ar\":\"المراكز الطبية كانت تعتمد على الورق أو أنظمة متفرقة، مما يسبب:\\r\\nصعوبة متابعة المواعيد والمرضى\\r\\nتشتت بيانات الأطباء والخدمات\\r\\nضعف الرقابة على الإيرادات والمصروفات\\r\\nغياب تقارير دقيقة ولحظية\\r\\nصعوبة إدارة المخزون والموظفين والتسويق في مكان واحد\",\"en\":\"Medical centers were relying on paper processes or disconnected tools, which led to:\\r\\nDifficulty tracking appointments and patient records\\r\\nScattered doctor and service data\\r\\nWeak control over income and expenses\\r\\nLack of accurate, real-time reports\\r\\nNo unified way to manage inventory, staff, and marketing\"}', '{\"ar\":\"بناء نظام مركزي يوحّد التشغيل اليومي للعيادة: مرضى، مواعيد، كشف، وصفة، مالية، موارد بشرية، مخزون، وتقارير مع صلاحيات حسب الدور وواجهة سهلة للفريق الطبي والإداري.\",\"en\":\"A centralized system that unifies daily clinic operations: patients, appointments, consultations, prescriptions, finance, HR, inventory, and reports with role-based access and a practical interface for medical and administrative teams.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المرضى والمواعيد\", \"en\": \"Patient & Appointment Management\"}, \"points\": [{\"ar\": \"تسجيل ومتابعة بيانات المرضى\", \"en\": \"Patient registration and follow-up\"}, {\"ar\": \"حجز المواعيد وعرضها على التقويم\", \"en\": \"Appointment booking with calendar view\"}, {\"ar\": \"إدارة الكشف وتحديث حالة الموعد\", \"en\": \"Consultation flow and appointment status updates\"}, {\"ar\": \"ربط المريض بالطبيب والخدمة المناسبة\", \"en\": \"Linking patients to the right doctor and service\"}]}, {\"title\": {\"ar\": \"لوحة الأطباء\", \"en\": \"Doctor Portal\"}, \"points\": [{\"ar\": \"لوحة خاصة بكل طبيب\", \"en\": \"Dedicated doctor dashboard\"}, {\"ar\": \"متابعة المرضى والمواعيد\", \"en\": \"Patient and appointment tracking\"}, {\"ar\": \"كتابة الوصفات الطبية\", \"en\": \"Digital prescriptions\"}, {\"ar\": \"الاستشارات والإشعارات\", \"en\": \"Consultations and notifications\"}]}, {\"title\": {\"ar\": \"الخدمات الطبية والعلاج\", \"en\": \"Medical Services & Treatment\"}, \"points\": [{\"ar\": \"إدارة الخدمات ومقدمي الخدمة\", \"en\": \"Services and service providers management\"}, {\"ar\": \"جلسات العلاج الكيماوي\", \"en\": \"Chemotherapy session tracking\"}, {\"ar\": \"جلسات الأشعة والتصوير\", \"en\": \"Radiology and imaging sessions\"}, {\"ar\": \"إدارة العمليات والمستشفيات\", \"en\": \"Operations and hospital management\"}, {\"ar\": \"التأمين الطبي\", \"en\": \"Medical insurance handling\"}]}, {\"title\": {\"ar\": \"المالية والفواتير\", \"en\": \"Finance & Billing\"}, \"points\": [{\"ar\": \"تسجيل المدفوعات وإصدار الفواتير\", \"en\": \"Payments and invoice generation\"}, {\"ar\": \"تقارير الدخل اليومي والشهري\", \"en\": \"Daily and monthly income reports\"}, {\"ar\": \"تقارير المصروفات والعمولات\", \"en\": \"Expense and commission reports\"}, {\"ar\": \"متابعة أتعاب الأطباء\", \"en\": \"Doctor fees tracking\"}]}, {\"title\": {\"ar\": \"الموارد البشرية والرواتب\", \"en\": \"HR & Payroll\"}, \"points\": [{\"ar\": \"إدارة الموظفين\", \"en\": \"Employee management\"}, {\"ar\": \"الرواتب والزيادات والخصومات\", \"en\": \"Salaries, increases, and deductions\"}, {\"ar\": \"تقارير الرواتب الشهرية\", \"en\": \"Monthly payroll reports\"}, {\"ar\": \"نظام أدوار وصلاحيات للمستخدمين\", \"en\": \"Roles and permissions system\"}]}, {\"title\": {\"ar\": \"المخزون والمستلزمات\", \"en\": \"Supplies & Inventory\"}, \"points\": [{\"ar\": \"فئات وماركات المستلزمات\", \"en\": \"Supply categories and brands\"}, {\"ar\": \"فواتير الشراء والسحب من المخزون\", \"en\": \"Purchase invoices and stock withdrawals\"}, {\"ar\": \"تقارير المخزون والنواقص\", \"en\": \"Inventory and shortage reports\"}]}, {\"title\": {\"ar\": \"التسويق والمتابعة\", \"en\": \"Marketing & Follow-up\"}, \"points\": [{\"ar\": \"إدارة العملاء المحتملين (Leads)\", \"en\": \"Leads management\"}, {\"ar\": \"مصادر التسويق\", \"en\": \"Marketing sources tracking\"}, {\"ar\": \"المتابعة والتقويم الخاص بالـ Leads\", \"en\": \"Lead calendar and follow-ups\"}, {\"ar\": \"تغيير الحالة والملاحظات بسهولة\", \"en\": \"Easy status and notes updates\"}]}, {\"title\": {\"ar\": \"التقارير والإشعارات\", \"en\": \"Reports & Notifications\"}, \"points\": [{\"ar\": \"تقارير شاملة للدخل والمصروفات والمواعيد\", \"en\": \"Comprehensive income, expense, and appointment reports\"}, {\"ar\": \"إشعارات داخل النظام\", \"en\": \"In-system notifications\"}, {\"ar\": \"استيراد وتصدير البيانات\", \"en\": \"Data import and export\"}, {\"ar\": \"واجهة API للربط مع تطبيقات أخرى\", \"en\": \"API support for external integrations\"}]}]', NULL, NULL, NULL, 20, NULL, NULL, NULL, NULL, 0, 'published', 11, NULL, NULL, '2026-09-02 03:01:21', '2026-09-30 08:34:02', NULL),
(17, '{\"ar\":\"السوادي\",\"en\":\"Elsawady\"}', 'elsawady', NULL, NULL, NULL, 'saas', '{\"ar\":\"نظام السوادي (EL-Sawady ERP) منصة SaaS متعددة المستأجرين لإدارة المزارع والمشاريع الزراعية والحيوانية، تجمع الإنتاج والمخزون والمبيعات والمشتريات والمالية والموارد البشرية والتجارة الإلكترونية في لوحة تحكم واحدة.\",\"en\":\"EL-Sawady ERP is a multi-tenant SaaS platform for managing farms and agribusiness operations, unifying production, inventory, sales, procurement, finance, HR, and e-commerce in a single dashboard.\"}', '{\"ar\":\"نظام السوادي هو حل ERP متكامل، مصمم خصيصاً لقطاع الزراعة والإنتاج الحيواني في المنطقة العربية. يخدم المزارع، شركات الإنتاج الزراعي، مزارع المواشي والدواجن، وشركات التوزيع التي تحتاج رقابة تشغيلية ومالية من مكان واحد.\\r\\n\\r\\nالنظام يعمل بنموذج SaaS مع عزل بيانات لكل مستأجر (Multi-Tenant)، وباقات اشتراك قابلة للتخصيص، وصلاحيات دقيقة حسب الدور (RBAC). يدعم العربية والإنجليزية مع واجهة RTL، ويوفر REST API لتطبيقات الموبايل والمتاجر الإلكترونية الخارجية.\",\"en\":\"EL-Sawady is a full-stack ERP solution, tailored for agriculture and livestock operations in the MENA region. It serves farms, agribusiness companies, livestock and poultry operations, and distribution companies that need operational and financial control from a single system.\\r\\n\\r\\nThe platform runs as a SaaS model with multi-tenant data isolation, customizable subscription plans, and role-based access control (RBAC). It supports Arabic and English with RTL UI, and exposes a REST API for mobile apps and external e-commerce frontends.\"}', '{\"ar\":\"معظم المزارع والشركات الزراعية تعتمد على أدوات متفرقة Excel، دفاتر ورقية، واتساب مما يؤدي إلى:\\r\\n\\r\\nبيانات مشتتة بدون صورة موحدة للعمليات\\r\\nغياب تتبع دقيق للمواشي: تطعيمات، تربية، إنتاج لبن\\r\\nمخزون غير مراقب يُفاجئ الفريق بنقص المنتجات\\r\\nفصل بين المشتريات والمبيعات والحسابات —> صعوبة معرفة الربحية الحقيقية\\r\\nإدارة يدوية للموظفين —> أخطاء في الحضور والإجازات والمرتبات\\r\\nمتجر إلكتروني منفصل غير مربوط بالمخزون الفعلي\\r\\nصعوبة التوسع لفرع جديد أو عميل SaaS بدون نظام مركزي\",\"en\":\"Most farms and agribusinesses rely on fragmented tools Excel, paper records, and messaging apps which leads to:\\r\\n\\r\\nScattered data with no unified operational view\\r\\nNo accurate livestock tracking for vaccinations, breeding, and milk production\\r\\nUnmonitored inventory that runs out without warning\\r\\nDisconnected procurement, sales, and accounting —> making real profitability hard to measure\\r\\nManual HR management —> errors in attendance, leave, and payroll\\r\\nStandalone e-commerce not linked to actual stock levels\\r\\nDifficulty scaling to new branches or SaaS customers without a centralized platform\"}', '{\"ar\":\"بنى نظام السوادي منصة ERP موحدة تربط كل دورة العمل من الإنتاج حتى الفاتورة:\\r\\n\\r\\nلوحة تحكم مركزية لكل الموديولات من الويب\\r\\nعزل بيانات لكل عميل (Multi-Tenant) مع إدارة اشتراكات وباقات\\r\\nتنبيهات ذكية للتطعيمات، نقص المخزون، انتهاء مستندات الموظفين، ومواعيد الولادة\\r\\nربط تشغيلي ومالي تكاليف الحظائر، المحاصيل، والدواجن تنعكس في تقارير الأرباح والخسائر\\r\\nصلاحيات دقيقة كل موظف يرى ويُدير ما يخصه فقط\\r\\nتفعيل الموديولات حسب الباقة (Feature Gating) لمرونة في التسعير والبيع\\r\\nAPI جاهز للتكامل مع تطبيقات الموبايل والمتاجر الإلكترونية\",\"en\":\"EL-Sawady delivers a unified ERP platform that connects the full business cycle from production to invoicing:\\r\\n\\r\\nCentral dashboard for all modules via web\\r\\nPer-customer data isolation (Multi-Tenant) with subscription and plan management\\r\\nSmart alerts for vaccinations, low stock, employee document expiry, and expected deliveries\\r\\nOperational–financial linkage pen, crop, and poultry costs flow into profit & loss reports\\r\\nFine-grained permissions each user sees and manages only what they need\\r\\nPlan-based module activation (Feature Gating) for flexible pricing and sales\\r\\nReady REST API for mobile apps and e-commerce integration\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المواشي\", \"en\": \"Livestock Management\"}, \"points\": [{\"ar\": \"سجل حيوانات كامل (أنواع، سلالات، حالات)\", \"en\": \"Full animal registry (species, breeds, statuses)\"}, {\"ar\": \"تسجيل تغذية، إنتاج لبن، أوزان، وسجلات صحية\", \"en\": \"Feeding, milk production, weight, and health records\"}, {\"ar\": \"تطعيمات مع مخزون دفعات لقاحات\", \"en\": \"Vaccinations with vaccine batch inventory\"}, {\"ar\": \"دورات تربية: تلقيح، فحص حمل، ولادة\", \"en\": \"Breeding cycles: insemination, pregnancy check, birth\"}, {\"ar\": \"تنبيهات: تطعيم مستحق / متأخر / حيوانات تحت العلاج / مواعيد ولادة متوقعة\", \"en\": \"Alerts: due/overdue vaccinations, animals under treatment, expected deliveries\"}]}, {\"title\": {\"ar\": \"المزارع والحظائر\", \"en\": \"Farms & Pens\"}, \"points\": [{\"ar\": \"إدارة المزارع والحظائر\", \"en\": \"Farm and pen management\"}, {\"ar\": \"ربط الحظائر بالمواشي والمحاصيل والدواجن\", \"en\": \"Link pens to livestock, crops, and poultry\"}, {\"ar\": \"قيود مالية على مستوى الحظيرة وتقارير ربحية\", \"en\": \"Pen-level financial entries and profitability reports\"}]}, {\"title\": {\"ar\": \"الدواجن\", \"en\": \"Poultry\"}, \"points\": [{\"ar\": \"دورات تسمين (Broiler Cycles)\", \"en\": \"Broiler cycles\"}, {\"ar\": \"قطعان بياض (Layer Flocks)\", \"en\": \"Layer flocks\"}, {\"ar\": \"مفارخ ودفعات تفريخ\", \"en\": \"Hatchery machines and batches\"}, {\"ar\": \"سلالات دجاج\", \"en\": \"Chicken breeds\"}, {\"ar\": \"تسجيل نفوق، مبيعات، تكاليف، وإنتاج بيض\", \"en\": \"Mortality, sales, cost, and egg production logging\"}, {\"ar\": \"تنبيهات تشغيلية\", \"en\": \"Operational alerts\"}]}, {\"title\": {\"ar\": \"المحاصيل والأعلاف\", \"en\": \"Crops & Feed\"}, \"points\": [{\"ar\": \"إدارة المحاصيل ومراحل النمو\", \"en\": \"Crop management and growth stages\"}, {\"ar\": \"تكاليف واستخدام مواد\", \"en\": \"Costs and material usage\"}, {\"ar\": \"مخزون شتلات\", \"en\": \"Seedling stock\"}, {\"ar\": \"حركات أعلاف، استهلاك، وتوزيع على المحاصيل\", \"en\": \"Feed movements, consumption, and crop allocations\"}, {\"ar\": \"تقارير تشغيلية\", \"en\": \"Operational reports\"}]}, {\"title\": {\"ar\": \"المخزون والمستودعات\", \"en\": \"Inventory & Warehouse\"}, \"points\": [{\"ar\": \"تصنيفات ومنتجات مخزنية\", \"en\": \"Categories and inventory products\"}, {\"ar\": \"دفعات (Batches)، حركات، إنتاج، وتسليمات\", \"en\": \"Batches, movements, production, and deliveries\"}, {\"ar\": \"تنبيهات نقص المخزون\", \"en\": \"Low-stock alerts\"}, {\"ar\": \"تتبع (Traceability)\", \"en\": \"Traceability\"}, {\"ar\": \"إدارة أصول المستودع\", \"en\": \"Warehouse asset management\"}]}, {\"title\": {\"ar\": \"المبيعات والتوزيع\", \"en\": \"Sales & Distribution\"}, \"points\": [{\"ar\": \"عملاء، عقود، أوامر بيع\", \"en\": \"Customers, contracts, and sales orders\"}, {\"ar\": \"شحنات وفواتير\", \"en\": \"Shipments and invoices\"}, {\"ar\": \"تسجيل مدفوعات ومتابعة التحصيل\", \"en\": \"Payment recording and collection tracking\"}]}, {\"title\": {\"ar\": \"المشتريات\", \"en\": \"Procurement\"}, \"points\": [{\"ar\": \"موردين وطلبات شراء\", \"en\": \"Suppliers and purchase requisitions\"}, {\"ar\": \"RFQ وعروض أسعار\", \"en\": \"RFQs and quotations\"}, {\"ar\": \"أوامر شراء، استلام بضاعة، وفواتير مشتريات\", \"en\": \"Purchase orders, goods receipts, and purchase invoices\"}, {\"ar\": \"دورة شراء كاملة\", \"en\": \"Full procurement cycle\"}]}, {\"title\": {\"ar\": \"المالية\", \"en\": \"Finance\"}, \"points\": [{\"ar\": \"دليل حسابات\", \"en\": \"Chart of accounts\"}, {\"ar\": \"قيود يومية ودفتر أستاذ\", \"en\": \"Journal entries and general ledger\"}, {\"ar\": \"مصروفات\", \"en\": \"Expenses\"}, {\"ar\": \"تقارير أرباح وخسائر\", \"en\": \"Profit & loss reports\"}]}, {\"title\": {\"ar\": \"الموارد البشرية\", \"en\": \"Human Resources\"}, \"points\": [{\"ar\": \"أقسام، مسميات وظيفية، وموظفين\", \"en\": \"Departments, job titles, and employees\"}, {\"ar\": \"مستندات موظفين مع تنبيهات انتهاء\", \"en\": \"Employee documents with expiry alerts\"}, {\"ar\": \"حضور وانصراف\", \"en\": \"Attendance (check-in / check-out)\"}, {\"ar\": \"طلبات إجازات وموافقة/رفض\", \"en\": \"Leave requests with approval/rejection\"}]}, {\"title\": {\"ar\": \"التجارة الإلكترونية\", \"en\": \"E-Commerce\"}, \"points\": [{\"ar\": \"إدارة طلبات المتجر من لوحة التحكم\", \"en\": \"Order management from the dashboard\"}, {\"ar\": \"API للمنتجات، السلة، المفضلة، والطلبات\", \"en\": \"API for products, cart, favorites, and orders\"}, {\"ar\": \"محفظة رقمية (Wallet)\", \"en\": \"Digital wallet\"}, {\"ar\": \"ربط الطلبات بالمخزون والمستأجر\", \"en\": \"Orders linked to inventory and tenant\"}]}, {\"title\": {\"ar\": \"التحليلات\", \"en\": \"Analytics\"}, \"points\": [{\"ar\": \"لوحة تحليلات\", \"en\": \"Analytics dashboard\"}, {\"ar\": \"تقارير تشغيلية\", \"en\": \"Operational reports\"}]}, {\"title\": {\"ar\": \"Super Admin\", \"en\": \"Super Admin\"}, \"points\": [{\"ar\": \"إدارة الباقات (Plans) والميزات (Features)\", \"en\": \"Plans and features management\"}, {\"ar\": \"إدارة اشتراكات العملاء: إنشاء، تجديد، ترقية، إلغاء\", \"en\": \"Customer subscriptions: create, renew, upgrade, cancel\"}, {\"ar\": \"إدارة محتوى المنصة (مقالات، فيديوهات، صفحات)\", \"en\": \"Platform content (articles, videos, pages)\"}, {\"ar\": \"إدارة الدول والمدن\", \"en\": \"Countries and cities management\"}]}, {\"title\": {\"ar\": \"ميزات المنصة\", \"en\": \"Platform Features\"}, \"points\": [{\"ar\": \"Multi-Tenant (عزل بيانات لكل عميل)\", \"en\": \"Multi-Tenant (isolated data per customer)\"}, {\"ar\": \"اشتراكات SaaS وباقات قابلة للتخصيص\", \"en\": \"SaaS subscriptions with customizable plans\"}, {\"ar\": \"صلاحيات وأدوار (RBAC)\", \"en\": \"Role-based access control (RBAC)\"}, {\"ar\": \"عربي / إنجليزي + دعم RTL\", \"en\": \"Arabic / English + RTL support\"}, {\"ar\": \"REST API\", \"en\": \"REST API\"}, {\"ar\": \"تسجيل دخول اجتماعي (Social Auth)\", \"en\": \"Social authentication\"}, {\"ar\": \"بحث عام (Global Search)\", \"en\": \"Global search\"}]}]', NULL, NULL, NULL, 29, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-02 08:42:37', '2026-09-27 10:20:37', NULL);
INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(18, '{\"ar\":\"إشارب\",\"en\":\"Esharb\"}', 'esharb', NULL, NULL, NULL, 'web', '{\"ar\":\"إشارب منصة كتالوج إلكتروني ثنائية اللغة (عربي\\/إنجليزي) لعرض وبيع الحجابات والأوشحة الفاخرة، مع لوحة إدارة عبر API لإدارة المنتجات والمخزون والاستفسارات.\",\"en\":\"Esharb is a bilingual (Arabic\\/English) e-commerce catalog platform for premium hijabs and scarves, with an API-powered admin backend for products, inventory, and customer inquiries.\"}', '{\"ar\":\"إشارب هو نظام متكامل لعرض منتجات الأزياء المحتشمة (حجابات، أوشحة، وإكسسوارات) عبر واجهة متجر إلكتروني عصرية وسريعة الاستجابة\\r\\n\\r\\nالمنصة مصممة خصيصاً للسوق المصري والعربي: دعم كامل للغة العربية واتجاه RTL، تسعير بالجنيه المصري، وربط مباشر مع واتساب لتحويل الاستفسارات إلى مبيعات. تتيح للعميل تصفح المنتجات حسب التصنيف والخامة واللون والسعر، مع صفحات منتج غنية بالصور والمتغيرات (Variants)، بينما يدير فريق العمل كل شيء من المنتجات والبنرات والصفحات الثابتة وحتى تتبع المخزون والصلاحيات.\",\"en\":\"Esharb is an end-to-end catalog system for modest fashion products (hijabs, scarves, and accessories), combining a modern, responsive storefront\\r\\n\\r\\nBuilt for the Egyptian and MENA market, the platform offers full Arabic\\/RTL support, EGP pricing, and direct WhatsApp integration to turn inquiries into sales. Customers can browse products by category, material, color, and price, with rich product pages featuring image galleries and color variants. The operations team manages everything from products and banners to static pages, inventory tracking, and role-based access control.\"}', '{\"ar\":\"كثير من متاجر الحجابات والأوشحة في المنطقة تعتمد على فيسبوك وإنستغرام وواتساب فقط، بدون موقع احترافي يعرض المنتجات بشكل منظم. هذا يؤدي إلى:\\r\\n\\r\\nصعوبة عرض المنتجات بألوانها وخاماتها المتعددة\\r\\nفقدان الاستفسارات بين الرسائل على وسائل التواصل\\r\\nعدم وجود نظام مخزون أو تتبع للكميات\\r\\nضعف الظهور في محركات البحث (SEO)\\r\\nصعوبة إدارة المحتوى بلغتين (عربي وإنجليزي)\\r\\nغياب صلاحيات واضحة لفريق العمل\",\"en\":\"Many hijab and scarf retailers in the region rely solely on Facebook, Instagram, and WhatsApp, without a professional website to showcase products systematically. This leads to:\\r\\n\\r\\nDifficulty displaying products with multiple colors and materials\\r\\nLost inquiries scattered across social media messages\\r\\nNo inventory system or stock tracking\\r\\nPoor search engine visibility (SEO)\\r\\nChallenges managing bilingual content (Arabic & English)\\r\\nNo clear role-based access for team members\"}', '{\"ar\":\"بنينا منصة إشارب كحل متكامل يجمع بين:\\r\\n\\r\\nمتجر إلكتروني أنيق بتصميم عصري يعكس هوية العلامة التجارية الفاخرة\\r\\nكتالوج منتجات ذكي مع متغيرات (ألوان، أسعار، صور) وتصفية وبحث متقدم\\r\\nربط واتساب لإرسال استفسارات جاهزة تلقائياً مع تفاصيل المنتج\\r\\nلوحة إدارة API لإدارة المنتجات، التصنيفات، البنرات، الصفحات، الأسئلة الشائعة، والإعدادات\\r\\nنظام مخزون لتتبع الكميات وحركات المخزون\\r\\nصلاحيات وأدوار (Super Admin \\/ Admin) لحماية العمليات\\r\\nتحسين SEO عبر Sitemap وMeta Tags وStructured Data\",\"en\":\"We built Esharb as an integrated solution combining:\\r\\n\\r\\nAn elegant e-commerce storefront with a modern design reflecting a premium brand identity\\r\\nA smart product catalog with variants (colors, prices, images), advanced filtering, and search\\r\\nWhatsApp integration for auto-generated product inquiries with full details\\r\\nAn API-powered admin panel to manage products, categories, banners, pages, FAQs, and settings\\r\\nInventory management for stock quantities and movement tracking\\r\\nRole-based permissions (Super Admin \\/ Admin) to secure operations\\r\\nSEO optimization via Sitemap, Meta Tags, and Structured Data\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"واجهة المتجر\", \"en\": \"Storefront\"}, \"points\": [{\"ar\": \"واجهة ثنائية اللغة (عربي/إنجليزي) مع دعم RTL\", \"en\": \"Bilingual interface (Arabic/English) with RTL support\"}, {\"ar\": \"صفحة رئيسية مع بنرات ومنتجات مميزة ووصل حديثاً والأكثر مبيعاً\", \"en\": \"Homepage with banners, featured, new arrivals & best sellers\"}, {\"ar\": \"كتالوج منتجات مع تصفية (تصنيف، خامة، لون، سعر، توفر) وترتيب\", \"en\": \"Product catalog with filters (category, material, color, price, availability) & sorting\"}, {\"ar\": \"صفحة منتج مع معرض صور، اختيار اللون، ومتغيرات السعر\", \"en\": \"Product page with image gallery, color picker & price variants\"}, {\"ar\": \"تصنيفات المنتجات مع صفحات مخصصة\", \"en\": \"Product categories with dedicated pages\"}, {\"ar\": \"بحث متقدم في المنتجات والتصنيفات\", \"en\": \"Advanced search across products & categories\"}, {\"ar\": \"استفسار عبر واتساب برسالة جاهزة تلقائياً\", \"en\": \"WhatsApp inquiry with auto-generated message\"}, {\"ar\": \"نموذج تواصل مع تتبع الاستفسارات\", \"en\": \"Contact form with inquiry tracking\"}, {\"ar\": \"صفحات ثابتة (من نحن، تواصل، FAQ)\", \"en\": \"Static pages (About, Contact, FAQ)\"}, {\"ar\": \"تحسين SEO (Sitemap, Meta, Open Graph, Schema)\", \"en\": \"SEO optimization (Sitemap, Meta, Open Graph, Schema)\"}, {\"ar\": \"تصميم متجاوب (Mobile-First)\", \"en\": \"Responsive design (Mobile-First)\"}]}, {\"title\": {\"ar\": \"لوحة الإدارة\", \"en\": \"Admin Panel\"}, \"points\": [{\"ar\": \"إدارة المنتجات (CRUD + استعادة المحذوف)\", \"en\": \"Product management (CRUD + soft delete restore)\"}, {\"ar\": \"إدارة التصنيفات، الخامات، والألوان\", \"en\": \"Categories, materials & colors management\"}, {\"ar\": \"إدارة البنرات الإعلانية\", \"en\": \"Promotional banners management\"}, {\"ar\": \"إدارة الصفحات والأسئلة الشائعة\", \"en\": \"Pages & FAQs management\"}, {\"ar\": \"إدارة الإعدادات العامة (اسم العلامة، واتساب، SEO)\", \"en\": \"General settings (brand name, WhatsApp, SEO)\"}, {\"ar\": \"نظام مخزون مع تتبع الحركات والتنبيهات\", \"en\": \"Inventory system with movement tracking & low-stock alerts\"}, {\"ar\": \"إدارة الاستفسارات والرسائل\", \"en\": \"Inquiries & messages management\"}, {\"ar\": \"إدارة المستخدمين والأدوار والصلاحيات\", \"en\": \"Users, roles & permissions management\"}, {\"ar\": \"رفع وإدارة الصور والملفات\", \"en\": \"File & image upload management\"}, {\"ar\": \"إحصائيات (منتجات، مخزون، مستخدمين، استفسارات)\", \"en\": \"Dashboard stats (products, inventory, users, inquiries)\"}]}]', NULL, NULL, NULL, 11, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-02 18:34:45', '2026-09-02 18:34:51', NULL),
(19, '{\"ar\":\"نُسك العمرة\",\"en\":\"Nusk Al-Umrah\"}', 'nusk-al-umrah', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة رقمية متكاملة لإدارة وحجز باقات العمرة والحج، تشمل موقع ويب، لوحة تحكم إدارية، وتطبيق موبايل، لربط العملاء والمندوبين والإدارة في نظام واحد.\",\"en\":\"An integrated digital platform for managing and booking Umrah and Hajj packages, including a web portal, admin dashboard, and mobile app connecting customers, agents, and management in one unified system.\"}', '{\"ar\":\"نُسك العمرة هو نظام شامل لشركات السياحة الدينية، يتيح بناء باقات عمرة وحج مركّبة من فنادق، شقق، نقل بري وجوي، وجبات، وخدمات إضافية. يوفر تجربة حجز سلسة للعملاء عبر الموقع أو تطبيق، مع لوحة تحكم قوية للإدارة تغطي الحجوزات، المستخدمين، المندوبين، والتقارير المالية.\",\"en\":\"Nusk Al-Umrah is a comprehensive platform for religious tourism companies, enabling the creation of Umrah and Hajj packages composed of hotels, apartments, ground and air transport, meals, and additional services. It delivers a seamless booking experience for customers via the website or mobile app, alongside a powerful admin dashboard covering bookings, users, agents, and financial reporting.\"}', '{\"ar\":\"شركات العمرة والحج غالباً تعتمد على عمليات يدوية ومتفرقة: حجوزات عبر الهاتف أو Excel، مخزون غير موحّد للفنادق والنقل، صعوبة متابعة عمولات المندوبين، وغياب تجربة رقمية موحّدة للعميل. هذا يؤدي إلى أخطاء تشغيلية، بطء في الخدمة، وصعوبة في التوسع وإدارة البيانات.\",\"en\":\"Umrah and Hajj travel agencies often rely on fragmented, manual operations: phone or spreadsheet-based bookings, disconnected hotel and transport inventory, difficulty tracking agent commissions, and no unified digital customer experience. This leads to operational errors, slower service, and challenges in scaling and data management.\"}', '{\"ar\":\"بناء منصة موحّدة متعددة القنوات تجمع كل عمليات الحجز والإدارة في مكان واحد: العميل يتصفح الباقات ويحجز من الويب أو الموبايل، المندوب يدير حجوزاته وعمولاته من بوابة خاصة، والإدارة تتحكم في المخزون والباقات والحجوزات والمستخدمين من لوحة تحكم مركزية مع إحصائيات وتقارير فورية، وإصدار فواتير PDF تلقائياً.\",\"en\":\"A unified multi-channel platform that centralizes all booking and management operations: customers browse and book packages via web or mobile, agents manage their bookings and commissions through a dedicated portal, and administrators control inventory, packages, bookings, and users from a central dashboard with real-time statistics and automated PDF invoicing.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"للعملاء (ويب + موبايل)\", \"en\": \"For Customers (Web + Mobile)\"}, \"points\": [{\"ar\": \"تسجيل الدخول وإنشاء حساب\", \"en\": \"Registration and login\"}, {\"ar\": \"استعراض الباقات وتفاصيلها (صور، أسعار، مدة الرحلة، المواقع)\", \"en\": \"Browse packages and view details (images, prices, trip duration, locations)\"}, {\"ar\": \"إنشاء حجز وإضافة بيانات المسافرين\", \"en\": \"Create bookings and add passenger information\"}, {\"ar\": \"حساب السعر تلقائياً (بما في ذلك قواعد التسعير حسب العمر)\", \"en\": \"Automatic price calculation (including age-based pricing rules)\"}, {\"ar\": \"متابعة حالة الحجز والدفع\", \"en\": \"Track booking and payment status\"}, {\"ar\": \"تأكيد أو إلغاء الحجز\", \"en\": \"Confirm or cancel bookings\"}, {\"ar\": \"تحميل فاتورة PDF\", \"en\": \"Download PDF invoices\"}, {\"ar\": \"إدارة الملف الشخصي وتغيير كلمة المرور (موبايل)\", \"en\": \"Profile management and password change (mobile)\"}]}, {\"title\": {\"ar\": \"لوحة الإدارة\", \"en\": \"Admin Dashboard\"}, \"points\": [{\"ar\": \"لوحة تحكم بإحصائيات الحجوزات والإيرادات والمستخدمين والمندوبين\", \"en\": \"Dashboard with booking, revenue, user, and agent statistics\"}, {\"ar\": \"رسوم بيانية للحجوزات والإيرادات الشهرية\", \"en\": \"Monthly booking and revenue charts\"}, {\"ar\": \"إدارة الباقات (إنشاء، تعديل، موافقة، حذف)\", \"en\": \"Package management (create, edit, approve, delete)\"}, {\"ar\": \"تجميع الباقات من: فنادق، شقق، نقل بري، نقل جوي، وجبات، خدمات\", \"en\": \"Package composition from: hotels, apartments, ground transport, air transport, meals, services\"}, {\"ar\": \"إدارة الحجوزات (عرض، تحديث، إلغاء)\", \"en\": \"Booking management (view, update, cancel)\"}, {\"ar\": \"إدارة المستخدمين والأدوار والصلاحيات\", \"en\": \"User, role, and permission management\"}, {\"ar\": \"إدارة العملاء والشركات\", \"en\": \"Customer and corporate account management\"}, {\"ar\": \"إدارة المندوبين وعمولاتهم ودفع العمولات\", \"en\": \"Agent management, commission tracking, and payout\"}, {\"ar\": \"إدارة السائقين\", \"en\": \"Driver management\"}, {\"ar\": \"رفع وإدارة الصور\", \"en\": \"Image upload and management\"}]}, {\"title\": {\"ar\": \"بوابة المندوب\", \"en\": \"Agent Portal\"}, \"points\": [{\"ar\": \"لوحة تحكم خاصة\", \"en\": \"Dedicated dashboard\"}, {\"ar\": \"متابعة الحجوزات\", \"en\": \"Booking tracking\"}, {\"ar\": \"متابعة العمولات\", \"en\": \"Commission tracking\"}]}]', NULL, NULL, NULL, 12, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-02 19:55:43', '2026-10-01 05:26:13', NULL),
(20, '{\"ar\":\"SportHub — نظام إدارة الأندية والمراكز الرياضية\",\"en\":\"SportHub — Sports Club & Fitness Center Management System\"}', 'sporthub-sports-club-fitness-center-management-system', NULL, NULL, NULL, 'web', '{\"ar\":\"نظام متكامل لإدارة الأندية والمراكز الرياضية، يجمع إدارة المشتركين والاشتراكات والمدفوعات مع التكامل مع أجهزة التعرّف على الوجه، لتسهيل التشغيل اليومي وتنظيم الدخول ومتابعة الحضور.\",\"en\":\"An integrated management system for sports clubs and fitness centers, combining member, subscription, and payment management with facial recognition device integration to simplify daily operations, manage access, and track attendance.\"}', '{\"ar\":\"طوّرنا منصة رقمية توحّد العمليات الإدارية والتشغيلية للأندية والمراكز الرياضية في لوحة تحكم تدعم العربية والإنجليزية. تتيح المنصة إدارة المشتركين والمدربين والأقسام، وتنظيم باقات الاشتراك ومددها وتجميدها وتمديدها، إلى جانب متابعة المدفوعات والمعاملات والفواتير.\\r\\n\\r\\nوتتكامل المنصة مع أجهزة التعرّف على الوجه لربط صلاحيات الدخول بحالة الاشتراك وتسجيل أحداث الدخول، مع تقديم مؤشرات للازدحام بناءً على سجلات الحركة. كما تتضمن واجهات برمجية لخدمات المشتركين، تشمل التسجيل، واستعراض الباقات والاشتراكات، ورفع إيصالات التحويل البنكي، واستقبال الإشعارات.\",\"en\":\"We developed a digital platform that brings the administrative and operational workflows of sports clubs and fitness centers into a centralized dashboard supporting Arabic and English. The platform manages members, trainers, and facility sections, alongside subscription plans, pricing, durations, freezes, reactivation, and extensions. It also supports payment, transaction, and invoice tracking.\\r\\n\\r\\nThe platform integrates with facial recognition devices to connect access permissions with subscription status and record entry events. It provides traffic indicators based on access logs and includes APIs for member services such as registration, browsing plans and subscriptions, uploading bank transfer receipts, and receiving notifications.\"}', '{\"ar\":\"تواجه الأندية والمراكز الرياضية صعوبة في متابعة بيانات المشتركين والاشتراكات والمدفوعات عندما تتوزع بين سجلات يدوية وأنظمة منفصلة. ويزيد فصل أجهزة الدخول عن بيانات الاشتراك من عبء التحقق على الموظفين، ويصعّب متابعة الاشتراكات المنتهية أو المجمّدة. كذلك، يحد غياب بيانات الحضور المجمّعة من وضوح أوقات الذروة ومستويات الإقبال على الأقسام.\",\"en\":\"Sports clubs and fitness centers face operational challenges when member records, subscriptions, and payments are spread across manual records and disconnected systems. Managing entry devices separately from subscription data adds verification work for staff and makes expired or frozen memberships harder to monitor. Without consolidated attendance data, managers also have limited visibility into peak hours and activity across facility sections.\"}', '{\"ar\":\"جمع العمليات الأساسية في منصة واحدة، وربط بيانات المشتركين واشتراكاتهم ومدفوعاتهم بأجهزة الدخول. يتيح النظام تحديث صلاحيات الوصول وفقًا لحالة الاشتراك، وتوثيق الحضور، ومراجعة المعاملات المالية من لوحة تحكم مركزية. وتساعد مؤشرات الحركة والإشعارات وخدمات المشتركين الرقمية على تقليل المتابعة اليدوية وتسهيل إدارة النادي وتحسين تجربة المشترك.\",\"en\":\"A centralized platform that connects member records, subscriptions, and payments with entry devices. The system updates access permissions according to subscription status, records attendance, and brings financial transaction reviews into one dashboard. Traffic indicators, notifications, and digital member services help reduce manual follow-up, simplify club operations, and improve the member experience.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المشتركين والمدربين\", \"en\": \"Member and Trainer Management\"}, \"points\": [{\"ar\": \"إنشاء وتحديث ملفات المشتركين وبياناتهم الشخصية.\", \"en\": \"Create and update member profiles and personal details.\"}, {\"ar\": \"متابعة اشتراكات كل مشترك.\", \"en\": \"Track each member’s subscriptions.\"}, {\"ar\": \"إدارة بيانات المدربين.\", \"en\": \"Manage trainer records.\"}, {\"ar\": \"استيراد بيانات المشتركين من الملفات.\", \"en\": \"Import member data from files.\"}]}, {\"title\": {\"ar\": \"إدارة الأقسام والباقات والاشتراكات\", \"en\": \"Sections, Plans, and Subscriptions\"}, \"points\": [{\"ar\": \"إنشاء وإدارة الأقسام الرياضية.\", \"en\": \"Create and manage sports sections.\"}, {\"ar\": \"إعداد باقات الاشتراك وتحديد الأسعار والمدد.\", \"en\": \"Configure subscription plans, pricing, and durations.\"}, {\"ar\": \"تجميد الاشتراكات وإعادة تفعيلها.\", \"en\": \"Freeze and reactivate subscriptions.\"}, {\"ar\": \"تمديد الاشتراكات ومتابعة تواريخ انتهائها.\", \"en\": \"Extend subscriptions and track expiration dates.\"}]}, {\"title\": {\"ar\": \"التكامل مع أجهزة الدخول\", \"en\": \"Access Device Integration\"}, \"points\": [{\"ar\": \"الربط مع أجهزة التعرّف على الوجه.\", \"en\": \"Integrate with facial recognition devices.\"}, {\"ar\": \"ربط المشتركين بأجهزة الدخول ومزامنة بياناتهم.\", \"en\": \"Assign members to entry devices and synchronize their data.\"}, {\"ar\": \"تحديث صلاحيات الدخول وفقًا لحالة الاشتراك.\", \"en\": \"Update access permissions according to subscription status.\"}, {\"ar\": \"تخصيص الوصول حسب القسم المرتبط بالاشتراك.\", \"en\": \"Manage access based on the section associated with each subscription.\"}]}, {\"title\": {\"ar\": \"الحضور ومؤشرات الازدحام\", \"en\": \"Attendance and Traffic Insights\"}, \"points\": [{\"ar\": \"تسجيل أحداث الدخول ومتابعة سجلات الحضور.\", \"en\": \"Record entry events and review attendance logs.\"}, {\"ar\": \"عرض إحصائيات ورسوم بيانية للحضور.\", \"en\": \"View attendance statistics and charts.\"}, {\"ar\": \"متابعة مؤشرات حركة الدخول لكل قسم.\", \"en\": \"Monitor entry activity indicators for each section.\"}, {\"ar\": \"تحديد الفترات الأكثر والأقل ازدحامًا بناءً على السجلات.\", \"en\": \"Identify busier and quieter periods based on recorded activity.\"}]}, {\"title\": {\"ar\": \"الإدارة المالية والفواتير\", \"en\": \"Financial Management and Invoices\"}, \"points\": [{\"ar\": \"متابعة المدفوعات والمبالغ المتبقية.\", \"en\": \"Track payments and outstanding balances.\"}, {\"ar\": \"إدارة وسائل الدفع والمعاملات المالية.\", \"en\": \"Manage payment methods and financial transactions.\"}, {\"ar\": \"استقبال إيصالات التحويل البنكي ومراجعتها.\", \"en\": \"Receive and review bank transfer receipts.\"}, {\"ar\": \"اعتماد المعاملات أو رفضها.\", \"en\": \"Approve or reject transactions.\"}, {\"ar\": \"عرض الفواتير وطباعتها.\", \"en\": \"View and print invoices.\"}]}, {\"title\": {\"ar\": \"التواصل مع المشتركين\", \"en\": \"Member Communication\"}, \"points\": [{\"ar\": \"إدارة قوالب الرسائل الترحيبية.\", \"en\": \"Manage welcome message templates.\"}, {\"ar\": \"إرسال الرسائل لمشتركين محددين أو للجميع.\", \"en\": \"Send messages to selected members or all members.\"}, {\"ar\": \"متابعة سجل إرسال الرسائل.\", \"en\": \"Review message delivery records.\"}, {\"ar\": \"توفير الإشعارات ومتابعة حالة قراءتها.\", \"en\": \"Provide notifications and track read status.\"}]}, {\"title\": {\"ar\": \"الإدارة والصلاحيات\", \"en\": \"Administration and Permissions\"}, \"points\": [{\"ar\": \"إدارة حسابات المسؤولين.\", \"en\": \"Manage administrator accounts.\"}, {\"ar\": \"إنشاء الأدوار وتحديد صلاحيات الوصول.\", \"en\": \"Create roles and configure access permissions.\"}, {\"ar\": \"تتبّع العمليات الإدارية من خلال سجل النشاط.\", \"en\": \"Track administrative actions through activity logs.\"}, {\"ar\": \"تخصيص الإعدادات العامة للنظام.\", \"en\": \"Customize general system settings.\"}, {\"ar\": \"دعم العربية والإنجليزية.\", \"en\": \"Support Arabic and English.\"}]}, {\"title\": {\"ar\": \"خدمات المشتركين عبر الـ API\", \"en\": \"Member Services via API\"}, \"points\": [{\"ar\": \"التسجيل والتحقق باستخدام رمز OTP.\", \"en\": \"Register and verify accounts using OTP.\"}, {\"ar\": \"إدارة الملف الشخصي واستعادة كلمة المرور.\", \"en\": \"Manage profiles and reset passwords.\"}, {\"ar\": \"استعراض الأقسام والباقات والاشتراكات.\", \"en\": \"Browse sections, plans, and subscriptions.\"}, {\"ar\": \"رفع إيصالات التحويل البنكي.\", \"en\": \"Upload bank transfer receipts.\"}, {\"ar\": \"الاطلاع على الإشعارات والرسائل الترحيبية.\", \"en\": \"Access notifications and welcome messages.\"}, {\"ar\": \"استعراض مؤشرات ازدحام النادي.\", \"en\": \"View club traffic indicators.\"}]}]', NULL, NULL, NULL, 13, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-05 06:05:33', '2026-09-05 06:30:37', NULL),
(21, '{\"ar\":\"إستيت فلو - نظام إدارة العقارات والأملاك\",\"en\":\"EstateFlow - Property & Asset Management\"}', 'estateflow-property-asset-management', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة متكاملة لإدارة العقارات والأملاك، تجمع بيانات العقارات والملاك والمستأجرين والعقود والمدفوعات والمستندات في مكان واحد، لتبسيط العمليات اليومية وتحسين متابعة المحفظة العقارية.\",\"en\":\"An integrated real estate and property management platform that consolidates data on properties, owners, tenants, contracts, payments, and documents in one place, streamlining daily operations and enhancing portfolio tracking.\"}', '{\"ar\":\"طوّرنا نظامًا لإدارة العقارات يساعد الشركات ومكاتب إدارة الأملاك على تنظيم الجوانب الإدارية والمالية والمستندية لأصولها العقارية من خلال منصة مركزية.\\r\\n\\r\\nيدعم النظام أنواعًا متعددة من العقارات، تشمل الأراضي والشقق والفلل والعقارات التجارية والمستودعات، مع تسجيل التفاصيل الخاصة بكل نوع. ويربط العقارات بملاكها ووحداتها ومستأجريها وعقودها، ويتيح متابعة الدفعات والمصاريف وحصص الملاك، إلى جانب حفظ المستندات وإعداد التقارير وتصدير البيانات.\",\"en\":\"We have developed a real estate management system that enables companies and property management firms to organize the administrative, financial, and documentation aspects of their real estate assets through a centralized platform.\\r\\n\\r\\nThe system supports various property types—including land, apartments, villas, commercial properties, and warehouses—while capturing specific details for each. It links properties to their owners, units, tenants, and contracts, facilitating the tracking of payments, expenses, and owner shares, alongside document storage, report generation, and data export capabilities.\"}', '{\"ar\":\"تتطلب إدارة محفظة عقارية متابعة عدد كبير من البيانات المترابطة، مثل نسب الملكية وعقود الإيجار ومواعيد السداد والمستندات والمصاريف. وعندما تتوزع هذه المعلومات بين ملفات منفصلة وجداول ومتابعات يدوية، يصبح الوصول إلى بيانات دقيقة أكثر صعوبة، وتزداد احتمالات تكرار البيانات وإغفال المستحقات أو مواعيد انتهاء العقود والوثائق.\",\"en\":\"Managing a real estate portfolio requires tracking a vast amount of interconnected data, such as ownership stakes, lease agreements, payment schedules, documentation, and expenses. When this information is scattered across separate files, spreadsheets, and manual tracking systems, accessing accurate data becomes difficult, and the risks of data duplication and overlooking outstanding payments or lease and document expiration dates increase.\"}', '{\"ar\":\"جمعنا هذه العمليات داخل نظام واحد يربط كل عقار ببياناته الإدارية والمالية والمستندات المرتبطة به. ويوفر النظام ملفات منظمة للعقارات والملاك والمستأجرين، وأدوات لمتابعة العقود والدفعات، ولوحة تحكم توضح المؤشرات الأساسية والعقود والوكالات التي تقترب من الانتهاء.\\r\\n\\r\\nيساعد هذا التنظيم فرق العمل على تقليل المتابعة اليدوية، وتسهيل مراجعة البيانات، واتخاذ قرارات تستند إلى معلومات موحدة.\",\"en\":\"We have consolidated these processes into a single system that links each property to its administrative and financial data, as well as all related documentation. The system provides organized profiles for properties, owners, and tenants, along with tools for tracking contracts and payments, and a dashboard displaying key indicators and details on contracts or agency agreements nearing expiration.\\r\\n\\r\\nThis streamlined approach helps teams reduce manual follow-up, simplifies data review, and enables decision-making based on unified information.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة العقارات والوحدات\", \"en\": \"Property & Unit Management\"}, \"points\": [{\"ar\": \"إدارة الأراضي والشقق والفلل والعقارات التجارية والمستودعات.\", \"en\": \"Manage land, apartments, villas, commercial properties, and warehouses.\"}, {\"ar\": \"تسجيل الموقع والمساحة والحدود والتفاصيل الخاصة بكل عقار.\", \"en\": \"Record property locations, areas, boundaries, and specific details.\"}, {\"ar\": \"تنظيم الوحدات الإيجارية وربطها بالعقارات.\", \"en\": \"Organize rental units and link them to properties.\"}, {\"ar\": \"إضافة صور العقارات والوحدات ومتابعة حالتها.\", \"en\": \"Add property and unit images and track their status.\"}, {\"ar\": \"البحث عن العقارات وتصفيتها بمعايير متعددة.\", \"en\": \"Search and filter properties using multiple criteria.\"}]}, {\"title\": {\"ar\": \"إدارة الملاك والمستأجرين\", \"en\": \"Owner & Tenant Management\"}, \"points\": [{\"ar\": \"إنشاء ملفات للملاك تتضمن بيانات التواصل والمستندات.\", \"en\": \"Maintain owner profiles with contact details and documents.\"}, {\"ar\": \"ربط عدة ملاك بالعقار وتحديد نسب وحصص الملكية.\", \"en\": \"Link multiple owners to a property and define ownership percentages and shares.\"}, {\"ar\": \"تسجيل العمولات المرتبطة بالملاك.\", \"en\": \"Record owner-related commissions.\"}, {\"ar\": \"إدارة بيانات المستأجرين وممثليهم ومرفقاتهم.\", \"en\": \"Manage tenants, their representatives, and supporting attachments.\"}, {\"ar\": \"ربط المستأجرين بالوحدات والعقود الخاصة بهم.\", \"en\": \"Connect tenants with their units and contracts.\"}]}, {\"title\": {\"ar\": \"إدارة العروض والعقود\", \"en\": \"Offer & Contract Management\"}, \"points\": [{\"ar\": \"تسجيل العروض وربطها بالعقارات.\", \"en\": \"Record offers and link them to properties.\"}, {\"ar\": \"إدارة عقود العقارات والوحدات الإيجارية.\", \"en\": \"Manage property and rental unit contracts.\"}, {\"ar\": \"تسجيل تفاصيل العقود ومددها ومرفقاتها.\", \"en\": \"Maintain contract details, terms, and attachments.\"}, {\"ar\": \"متابعة العقود التي تقترب من الانتهاء خلال 30 و60 و90 يومًا.\", \"en\": \"Track contracts expiring within 30, 60, and 90 days.\"}]}, {\"title\": {\"ar\": \"الإدارة المالية والمدفوعات\", \"en\": \"Financial & Payment Management\"}, \"points\": [{\"ar\": \"إدارة جداول السداد والدفعات الإيجارية.\", \"en\": \"Manage payment schedules and rental payments.\"}, {\"ar\": \"تسجيل الفواتير وطرق الدفع وبيانات البنك.\", \"en\": \"Record invoices, payment methods, and bank details.\"}, {\"ar\": \"إرفاق المستندات والإيصالات بالدفعات.\", \"en\": \"Attach supporting documents and receipts to payments.\"}, {\"ar\": \"تسجيل الإيرادات والمصروفات وإعداد كشوف الحساب.\", \"en\": \"Record income and expenses and prepare account statements.\"}, {\"ar\": \"توثيق توزيع الدفعات على الملاك.\", \"en\": \"Document payment distributions to owners.\"}]}, {\"title\": {\"ar\": \"إدارة المستندات والوثائق\", \"en\": \"Document Management\"}, \"points\": [{\"ar\": \"حفظ الصكوك والوكالات وربطها بالعقارات والملاك.\", \"en\": \"Store title deeds and powers of attorney linked to properties and owners.\"}, {\"ar\": \"تسجيل رخص البناء ومستندات الدفاع المدني.\", \"en\": \"Maintain building permits and civil defense documents.\"}, {\"ar\": \"رفع المخططات والصور والمرفقات وتصنيفها.\", \"en\": \"Upload and categorize drawings, images, and attachments.\"}, {\"ar\": \"متابعة الوكالات التي تقترب من انتهاء صلاحيتها.\", \"en\": \"Track upcoming power of attorney expirations.\"}]}, {\"title\": {\"ar\": \"متابعة الصيانة والمصاريف\", \"en\": \"Maintenance & Expense Tracking\"}, \"points\": [{\"ar\": \"تسجيل أعمال الصيانة السنوية.\", \"en\": \"Record annual maintenance activities.\"}, {\"ar\": \"توثيق تكاليف الصيانة والفترات الخاصة بها.\", \"en\": \"Document maintenance costs and associated periods.\"}, {\"ar\": \"إرفاق المستندات الداعمة لكل سجل.\", \"en\": \"Attach supporting documents to each record.\"}, {\"ar\": \"ربط سجلات الصيانة بالعقار لتسهيل مراجعة مصروفاته.\", \"en\": \"Link maintenance records to properties for easier expense review.\"}]}, {\"title\": {\"ar\": \"لوحة التحكم والتقارير\", \"en\": \"Dashboard & Reporting\"}, \"points\": [{\"ar\": \"عرض ملخصات العقارات والملاك والوثائق.\", \"en\": \"View summaries of properties, owners, and documents.\"}, {\"ar\": \"متابعة العقود والوكالات القريبة من الانتهاء.\", \"en\": \"Monitor upcoming contract and power of attorney expirations.\"}, {\"ar\": \"عرض تقارير الأصول والإيجارات والوحدات الشاغرة وانتهاء العقود.\", \"en\": \"Access asset, rental, vacancy, and lease expiry reports.\"}, {\"ar\": \"تصدير البيانات والتقارير المدعومة إلى Excel وPDF.\", \"en\": \"Export supported data and reports to Excel and PDF.\"}]}, {\"title\": {\"ar\": \"إدارة المستخدمين ومرونة البيانات\", \"en\": \"User Management & Data Flexibility\"}, \"points\": [{\"ar\": \"إدارة حسابات المستخدمين وبياناتهم.\", \"en\": \"Manage user accounts and profile details.\"}, {\"ar\": \"تسجيل التغييرات على السجلات لتسهيل المراجعة.\", \"en\": \"Track record changes through an audit trail.\"}, {\"ar\": \"تنظيم المواقع حسب الدولة والمدينة والحي.\", \"en\": \"Organize locations by country, city, and neighborhood.\"}, {\"ar\": \"اختيار العملات وإدخال الأسماء بالعربية والإنجليزية.\", \"en\": \"Select currencies and enter names in Arabic and English.\"}]}]', NULL, NULL, NULL, 14, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-05 06:30:09', '2026-10-01 05:41:34', NULL);
INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(22, '{\"ar\":\"سكولينا\",\"en\":\"Schoolina\"}', 'schoolina', NULL, NULL, NULL, 'web', '{\"ar\":\"سكولينا منصة متكاملة لإدارة المدارس، تجمع الإدارة الأكاديمية والمالية والتشغيلية في مكان واحد، وتربط الإدارة والمعلمين والطلاب وأولياء الأمور لتسهيل العمل اليومي ومتابعة العملية التعليمية.\",\"en\":\"Schoolina is an integrated school management platform that brings academic, financial, and operational processes together, connecting administrators, teachers, students, and parents to simplify daily work and support educational oversight.\"}', '{\"ar\":\"سكولينا نظام لإدارة المدارس والمجموعات التعليمية، يغطي رحلة الطالب من التسجيل وإدارة ملفه إلى متابعة الحضور والواجبات والاختبارات والنتائج. ويجمع النظام إدارة الرسوم والحسابات والموارد البشرية والنقل والمرافق المدرسية ضمن بيئة موحدة.\\r\\n\\r\\nيوفر المشروع بوابات مخصصة للإدارة والمعلمين والطلاب وأولياء الأمور، مع صلاحيات وصول وتقارير تساعد كل مستخدم على متابعة مسؤولياته. كما يدعم إدارة مدارس متعددة، بما يتيح للمؤسسات التعليمية تنظيم أعمالها ومتابعة مدارسها من خلال نظام واحد.\",\"en\":\"Schoolina is a management system for schools and educational groups, covering the student journey from enrollment and record management to attendance, assignments, examinations, and results. It also brings tuition fees, accounting, human resources, transportation, and school resources into one unified environment.\\r\\n\\r\\nThe platform provides dedicated portals for administrators, teachers, students, and parents, supported by access permissions and reports tailored to their responsibilities. Its multi-school capabilities allow educational organizations to manage and oversee several schools through a single system.\"}', '{\"ar\":\"تواجه المدارس صعوبة في تنسيق أعمالها عندما تتوزع بيانات الطلاب والحضور والرسوم والموظفين بين ملفات ورقية وجداول وبرامج منفصلة. يؤدي ذلك إلى تكرار إدخال البيانات، وصعوبة الوصول إلى معلومات محدثة، وتأخر التواصل مع أولياء الأمور، وزيادة الوقت المطلوب لإعداد التقارير.\\r\\n\\r\\nوتزداد هذه التحديات لدى المؤسسات التي تدير عدة مدارس وتحتاج إلى رؤية واضحة للأداء الأكاديمي والمالي والتشغيلي.\",\"en\":\"Schools face coordination challenges when student records, attendance, fees, and employee information are scattered across paper documents, spreadsheets, and separate applications. This creates duplicate data entry, makes updated information harder to access, delays communication with parents, and increases the effort required to prepare reports.\\r\\n\\r\\nThese challenges become more complex for organizations managing multiple schools that need a clear view of academic, financial, and operational performance.\"}', '{\"ar\":\"يجمع سكولينا العمليات المدرسية في منصة واحدة تربط بيانات الطلاب والمعلمين وأولياء الأمور بالعمليات الأكاديمية والمالية والإدارية. وتساعد مسارات العمل المنظمة، والإشعارات، والتقارير، والصلاحيات المحددة على تقليل العمل اليدوي، وتيسير المتابعة، وتحسين التنسيق بين أقسام المدرسة.\",\"en\":\"Schoolina consolidates school operations into one platform, connecting student, teacher, and parent information with academic, financial, and administrative workflows. Structured processes, notifications, reporting, and defined access permissions help reduce manual work, simplify monitoring, and improve coordination across school departments.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المدارس والنظام\", \"en\": \"Schools & System Management\"}, \"points\": [{\"ar\": \"إدارة أكثر من مدرسة: فصل بيانات المدارس بالاعتماد على المدرسة/المستأجر الحالي ومسارات النطاقات الفرعية.\", \"en\": \"Multi-school management: Separate school data by the current school/tenant and subdomain routing.\"}, {\"ar\": \"لوحة مدير النظام: إنشاء المدارس وإدارة الاشتراكات وحذف المدرسة من لوحة الإدارة العليا.\", \"en\": \"System admin dashboard: Create schools, manage subscriptions, and delete schools from the super admin panel.\"}, {\"ar\": \"تخصيص قائمة كل مدرسة: إظهار وإخفاء عناصر القائمة وإعادة ترتيب الأقسام والقوائم للمدرسة.\", \"en\": \"Per-school menu customization: Show or hide menu items and reorder sections for each school.\"}, {\"ar\": \"لوحات تحكم حسب الدور: واجهات مختلفة للإدارة والمعلمين والطلاب وأولياء الأمور والخريجين.\", \"en\": \"Role-based dashboards: Different interfaces for admins, teachers, students, parents, and alumni.\"}, {\"ar\": \"المهام اليومية: إضافة مهام «To Do» وعرضها وتعديلها وحذفها من لوحة التحكم.\", \"en\": \"Daily tasks: Add, view, edit, and delete To Do tasks from the dashboard.\"}, {\"ar\": \"الأدوار والصلاحيات: إنشاء الأدوار، تعيين صلاحيات الشاشات والعمليات، وتحديد صلاحيات الوحدات.\", \"en\": \"Roles and permissions: Create roles, assign screen and action permissions, and set module access.\"}, {\"ar\": \"إدارة المستخدمين: إنشاء حسابات المستخدمين وإدارة الوصول وإعادة تعيين كلمات المرور.\", \"en\": \"User management: Create user accounts, manage access, and reset passwords.\"}, {\"ar\": \"إدارة الوحدات الإضافية: إعداد الوحدات وتفعيلها أو تعطيلها وفق إعدادات النظام.\", \"en\": \"Add-on module management: Configure modules and enable or disable them based on system settings.\"}, {\"ar\": \"إدارة القوائم الجانبية: إنشاء الأقسام والقوائم، تعديل ترتيبها وإرجاع التصميم الافتراضي.\", \"en\": \"Sidebar menu management: Create sections and menus, reorder them, and restore the default layout.\"}, {\"ar\": \"التحقق بخطوتين: إرسال رمز تحقق وإعادة إرساله وضبط إعدادات التحقق.\", \"en\": \"Two-factor authentication: Send and resend verification codes and configure 2FA settings.\"}, {\"ar\": \"سجل الأنشطة: متابعة العمليات المسجلة في النظام وفق الصلاحية.\", \"en\": \"Activity log: Track recorded system actions according to permissions.\"}, {\"ar\": \"نسخ احتياطي وإعدادات الصيانة: إدارة النسخ الاحتياطية ووضع الصيانة وتحديث النظام.\", \"en\": \"Backup and maintenance: Manage backups, maintenance mode, and system updates.\"}, {\"ar\": \"تعدد اللغات والإعدادات المحلية: إدارة اللغات وتنسيق التاريخ والعملة والمنطقة الزمنية وإعدادات الهوية.\", \"en\": \"Languages and localization: Manage languages, date formats, currency, time zones, and branding settings.\"}, {\"ar\": \"إعدادات العرض: ضبط مظهر لوحة التحكم والثيم والخلفيات والتحميل المسبق.\", \"en\": \"Display settings: Configure dashboard appearance, themes, backgrounds, and preloading.\"}, {\"ar\": \"واجهة API: مسارات للمصادقة واسترجاع البيانات والواجبات والتكامل مع التطبيقات.\", \"en\": \"API interface: Endpoints for authentication, data retrieval, homework, and app integrations.\"}]}, {\"title\": {\"ar\": \"الإعداد الأكاديمي والجدول\", \"en\": \"Academic Setup & Timetable\"}, \"points\": [{\"ar\": \"السنوات الدراسية والفصول: تعريف السنوات والجلسات الدراسية وإعداد بياناتها.\", \"en\": \"Academic years and sessions: Define academic years and sessions and manage their data.\"}, {\"ar\": \"الصفوف والشعب: إنشاء الصفوف والشعب وإسناد الطلاب إليها.\", \"en\": \"Classes and sections: Create classes and sections and assign students to them.\"}, {\"ar\": \"المواد: تعريف المواد وربطها بالصفوف والشعب.\", \"en\": \"Subjects: Define subjects and link them to classes and sections.\"}, {\"ar\": \"المواد الاختيارية: تعيين المواد الاختيارية للطلاب.\", \"en\": \"Optional subjects: Assign optional subjects to students.\"}, {\"ar\": \"توزيع المعلمين على المواد: تحديد معلم كل مادة للصف والشعبة.\", \"en\": \"Subject teacher assignment: Assign a teacher to each subject for a class and section.\"}, {\"ar\": \"معلمو الصفوف: إسناد معلم أو أكثر إلى الصفوف والشعب.\", \"en\": \"Class teachers: Assign one or more teachers to classes and sections.\"}, {\"ar\": \"القاعات ومواعيد الحصص: إدارة الغرف الدراسية وأوقات الحصص.\", \"en\": \"Rooms and class periods: Manage classrooms and period times.\"}, {\"ar\": \"جدول الحصص: إنشاء وتعديل وحذف الحصص وعرض الجداول حسب الصف أو المعلم.\", \"en\": \"Class timetable: Create, edit, and delete periods and view schedules by class or teacher.\"}, {\"ar\": \"الجدول الأسبوعي: تحديد أسابيع الجدول وتنظيم التوزيع الأسبوعي للحصص.\", \"en\": \"Weekly schedule: Define timetable weeks and organize weekly period distribution.\"}, {\"ar\": \"طباعة الجداول: طباعة جدول المعلم والصف وجداول الاختبارات.\", \"en\": \"Print schedules: Print teacher, class, and exam timetables.\"}, {\"ar\": \"تعويض غياب المعلم: تسجيل تغطية حصص المعلم الغائب وإصدار تقارير يومية وأسبوعية.\", \"en\": \"Teacher absence cover: Record substitute coverage and generate daily and weekly reports.\"}, {\"ar\": \"إعدادات أكاديمية موحدة: صفحات مخصصة لإعدادات الأكاديميات وتقاريرها.\", \"en\": \"Unified academic settings: Dedicated pages for academic settings and reports.\"}]}, {\"title\": {\"ar\": \"شؤون الطلاب وأولياء الأمور\", \"en\": \"Students & Parents Affairs\"}, \"points\": [{\"ar\": \"طلبات الالتحاق: تسجيل استفسارات القبول ومتابعاتها.\", \"en\": \"Admission inquiries: Register and follow up on admission requests.\"}, {\"ar\": \"قبول الطلاب: إدخال بيانات الطالب وصورته وبيانات ولي الأمر وسجله الدراسي.\", \"en\": \"Student admission: Enter student details, photo, parent data, and academic history.\"}, {\"ar\": \"استيراد الطلاب جماعيًا: إدخال الطلاب دفعة واحدة عبر الملفات.\", \"en\": \"Bulk student import: Import multiple students at once from files.\"}, {\"ar\": \"قائمة الطلاب والبحث: عرض الطلاب مع التصفية والبحث وتصدير القائمة إلى Excel.\", \"en\": \"Student list and search: View, filter, search, and export students to Excel.\"}, {\"ar\": \"ملف الطالب: عرض البيانات الشخصية والدراسية والمستندات والخط الزمني.\", \"en\": \"Student profile: View personal and academic data, documents, and timeline.\"}, {\"ar\": \"حقول الطالب: تخصيص الحقول الظاهرة والمطلوبة في نموذج الطالب.\", \"en\": \"Student fields: Customize visible and required fields on the student form.\"}, {\"ar\": \"بيانات الطالب الحساسة: شاشة مستقلة للبيانات الحساسة مع إمكانية طباعتها وفق الصلاحية.\", \"en\": \"Sensitive student data: A separate screen for sensitive data with permission-based printing.\"}, {\"ar\": \"فئات ومجموعات الطلاب: تصنيف الطلاب بحسب النوع أو المجموعة وإدارتها.\", \"en\": \"Student categories and groups: Classify and manage students by type or group.\"}, {\"ar\": \"أنشطة الطلاب: تسجيل الأنشطة والرجوع إلى سجلاتها.\", \"en\": \"Student activities: Record activities and review their history.\"}, {\"ar\": \"تعيين الصف والشعبة جماعيًا: تغيير موضع عدة طلاب دفعة واحدة.\", \"en\": \"Bulk class and section assignment: Move multiple students at once.\"}, {\"ar\": \"ترقية الطلاب: نقل الطلاب للصف أو السنة التالية، مع خيارات تعتمد على نتائج الاختبارات.\", \"en\": \"Student promotion: Move students to the next class or year, with exam-based options.\"}, {\"ar\": \"تعطيل سجل الطالب وأسباب عدم التفعيل: حفظ حالة الطالب وسبب إيقافها.\", \"en\": \"Disable student records: Save student status and the reason for deactivation.\"}, {\"ar\": \"سجل الطالب السابق: مراجعة تاريخ الطالب وتنقلاته الدراسية.\", \"en\": \"Previous student record: Review student history and academic transfers.\"}, {\"ar\": \"الخريجون: البحث في قائمة الخريجين، عرض/طباعة كشف الدرجات وإعادة الخريج إلى حالة طالب.\", \"en\": \"Alumni: Search alumni, view or print transcripts, and restore alumni to student status.\"}, {\"ar\": \"طريقة انصراف الطالب: تحديد طريقة الانصراف من جهة ولي الأمر.\", \"en\": \"Student pickup method: Define the pickup method from the parent side.\"}, {\"ar\": \"طلبات تغيير الانصراف: إنشاء الطلب ومراجعته واعتماده وتتبع حالته من الإدارة.\", \"en\": \"Pickup change requests: Create, review, approve, and track request status from admin.\"}, {\"ar\": \"حالات طلب الانصراف: إدارة الحالات المستخدمة في دورة الموافقات.\", \"en\": \"Pickup request statuses: Manage statuses used in the approval workflow.\"}, {\"ar\": \"استدعاء ولي الأمر: إنشاء الاستدعاء ومتابعة تأكيد اطلاع ولي الأمر عليه.\", \"en\": \"Parent summons: Create summons and track parent acknowledgment.\"}, {\"ar\": \"تقارير الطلاب: بيانات الطلاب وتاريخهم وسجل دخولهم والتقارير الأكاديمية.\", \"en\": \"Student reports: Student data, history, login records, and academic reports.\"}, {\"ar\": \"تقارير أولياء الأمور: البحث في بيانات أولياء الأمور المرتبطة بالطلاب.\", \"en\": \"Parent reports: Search parent data linked to students.\"}, {\"ar\": \"شهادات الطلاب: تصميم/توليد الشهادات وطباعتها.\", \"en\": \"Student certificates: Design, generate, and print certificates.\"}, {\"ar\": \"بطاقات الطلاب: إعداد البطاقات وتوليدها وطباعتها.\", \"en\": \"Student ID cards: Configure, generate, and print student cards.\"}]}, {\"title\": {\"ar\": \"الحضور والغياب\", \"en\": \"Attendance & Absence\"}, \"points\": [{\"ar\": \"حضور الطلاب اليومي: تسجيل الحضور والغياب والعطلات للصفوف والشعب.\", \"en\": \"Daily student attendance: Record attendance, absence, and holidays for classes and sections.\"}, {\"ar\": \"حضور الطلاب حسب المادة: تسجيل ومراجعة حضور كل مادة على حدة.\", \"en\": \"Subject-based attendance: Record and review attendance per subject.\"}, {\"ar\": \"استيراد الحضور: رفع سجلات حضور الطلاب والموظفين جماعيًا.\", \"en\": \"Attendance import: Bulk upload student and staff attendance records.\"}, {\"ar\": \"تقارير حضور الطلاب: تقارير شهرية وتفصيلية ومتوسط الحضور مع الطباعة.\", \"en\": \"Student attendance reports: Monthly and detailed reports with averages and printing.\"}, {\"ar\": \"تقارير الغياب: البحث عن الغياب وطباعة تقاريره.\", \"en\": \"Absence reports: Search absences and print related reports.\"}, {\"ar\": \"تعليق ولي الأمر على الحضور: تسجيل تعليق ومرفق على سجل الحضور.\", \"en\": \"Parent attendance comments: Add a comment and attachment to an attendance record.\"}, {\"ar\": \"حضور الموظفين: تسجيل الحضور والغياب والعطلات وإصدار التقارير وطباعتها.\", \"en\": \"Staff attendance: Record attendance, absence, and holidays and generate printable reports.\"}, {\"ar\": \"إعدادات الحضور: ضبط قواعد التسجيل والورديات المرتبطة به.\", \"en\": \"Attendance settings: Configure recording rules and related shifts.\"}, {\"ar\": \"تنبيهات غياب الطلاب: إعداد مواعيد إرسال تنبيهات الغياب.\", \"en\": \"Student absence alerts: Configure when absence notifications are sent.\"}]}, {\"title\": {\"ar\": \"الاختبارات والنتائج\", \"en\": \"Exams & Results\"}, \"points\": [{\"ar\": \"أنواع ومجموعات الاختبارات: تنظيم الاختبارات وفتراتها وإعداداتها.\", \"en\": \"Exam types and groups: Organize exams, periods, and settings.\"}, {\"ar\": \"جدول الاختبارات: إعداد المواعيد حسب المادة والصف والشعبة وطباعتها.\", \"en\": \"Exam timetable: Set schedules by subject, class, and section and print them.\"}, {\"ar\": \"درجات الاختبارات: إدخال العلامات ومراجعتها وإعداد سجل الدرجات.\", \"en\": \"Exam marks: Enter and review marks and prepare mark sheets.\"}, {\"ar\": \"سلم الدرجات: تعريف حدود الدرجات والتقديرات.\", \"en\": \"Grading scale: Define grade ranges and ratings.\"}, {\"ar\": \"حضور الاختبارات: تسجيل غياب/حضور الطلاب في جلسات الاختبار.\", \"en\": \"Exam attendance: Record student presence or absence in exam sessions.\"}, {\"ar\": \"توزيع المقاعد: إعداد مخططات جلوس الطلاب للاختبارات.\", \"en\": \"Seat allocation: Prepare student seating plans for exams.\"}, {\"ar\": \"بطاقات دخول الاختبار: إعداد نموذج البطاقة وتوليدها للطلاب وأولياء الأمور.\", \"en\": \"Exam admit cards: Configure templates and generate cards for students and parents.\"}, {\"ar\": \"بنك الأسئلة: تنظيم الأسئلة بحسب المجموعة والمستوى واستخدامها في الاختبارات.\", \"en\": \"Question bank: Organize questions by group and level and use them in exams.\"}, {\"ar\": \"الاختبارات الإلكترونية: إنشاء الاختبار، تقديمه من حساب الطالب، مراجعة الإجابات والنتيجة؛ يتطلب تفعيل الوحدة المعنية.\", \"en\": \"Online exams: Create exams, let students submit answers, and review results; requires the related module.\"}, {\"ar\": \"النتائج وكشوف الدرجات: عرض النتيجة، تقارير المواد والصفوف والكشوف التجميعية.\", \"en\": \"Results and mark sheets: View results, subject and class reports, and consolidated sheets.\"}, {\"ar\": \"بطاقة تقدم الطالب: إعداد تقارير التقدم والبطاقات التفصيلية للنسبة والدرجات.\", \"en\": \"Student progress card: Prepare progress reports and detailed percentage and grade cards.\"}, {\"ar\": \"تقارير مستوى الطالب: ملخص الدرجات والتقديرات وأسباب الضعف والبرامج العلاجية.\", \"en\": \"Student level reports: Summarize marks, ratings, weak areas, and remedial programs.\"}, {\"ar\": \"إعدادات تنسيق النتائج: تخصيص طريقة حساب النتائج ونماذج العرض والطباعة.\", \"en\": \"Result format settings: Customize result calculation, display templates, and printing.\"}, {\"ar\": \"إرسال الدرجات برسائل قصيرة: مسارات لإرسال العلامات عبر SMS عند ضبط الخدمة.\", \"en\": \"SMS marks delivery: Send marks via SMS when the service is configured.\"}]}, {\"title\": {\"ar\": \"الدروس والواجبات والمواد التعليمية\", \"en\": \"Lessons, Homework & Learning Materials\"}, \"points\": [{\"ar\": \"الدروس والموضوعات: تعريف الدروس والموضوعات لكل مادة وصف.\", \"en\": \"Lessons and topics: Define lessons and topics for each subject and class.\"}, {\"ar\": \"تخطيط الدروس: إنشاء خطة درس وربطها بالمعلم والتاريخ وجدول الحصص.\", \"en\": \"Lesson planning: Create lesson plans linked to teacher, date, and timetable.\"}, {\"ar\": \"الخطة الأسبوعية: إدخال الخطة الأسبوعية ومراجعتها واعتمادها.\", \"en\": \"Weekly plan: Enter, review, and approve weekly plans.\"}, {\"ar\": \"الإذاعة المدرسية: إعداد برنامج الإذاعة ومراجعته واعتماده وطباعته.\", \"en\": \"School assembly: Prepare, review, approve, and print assembly programs.\"}, {\"ar\": \"الواجبات: إنشاء واجب، تحديد المستلمين وموعد التسليم، وإرفاق الملفات.\", \"en\": \"Homework: Create assignments, set recipients and due dates, and attach files.\"}, {\"ar\": \"تسليم الواجبات: رفع الطالب لإجابته وملفاته من حسابه.\", \"en\": \"Homework submission: Students upload answers and files from their accounts.\"}, {\"ar\": \"تقييم الواجبات: متابعة التسليم وتقييم عمل الطلاب.\", \"en\": \"Homework evaluation: Track submissions and grade student work.\"}, {\"ar\": \"تقارير الواجبات: استعراض حالة الواجبات ونتائج تقييمها بحسب الطالب والصف.\", \"en\": \"Homework reports: Review assignment status and grades by student and class.\"}, {\"ar\": \"المواد الدراسية: رفع المحتوى والملفات وتوزيعها على الفئات المستهدفة.\", \"en\": \"Study materials: Upload content and files and distribute them to target groups.\"}, {\"ar\": \"مركز التحميل: تصنيف المحتوى، إدارة الملفات وروابط المشاركة، وعرض المحتوى للطلاب وأولياء الأمور.\", \"en\": \"Download center: Categorize content, manage files and share links, and show content to students and parents.\"}, {\"ar\": \"مكتبة الفيديو: رفع الفيديوهات وتصنيفها وإتاحة عرضها وتتبع المشاهدة.\", \"en\": \"Video library: Upload and categorize videos, enable viewing, and track watch history.\"}]}, {\"title\": {\"ar\": \"الرسوم والمدفوعات والمحفظة\", \"en\": \"Fees, Payments & Wallet\"}, \"points\": [{\"ar\": \"مجموعات وأنواع الرسوم: تعريف البنود المالية وتجميعها.\", \"en\": \"Fee groups and types: Define and group financial fee items.\"}, {\"ar\": \"الخصومات: إعداد خصومات الطلاب وربطها بالرسوم.\", \"en\": \"Discounts: Configure student discounts and link them to fees.\"}, {\"ar\": \"فواتير الرسوم: إنشاء الفواتير وتعديلها وعرضها والبحث فيها.\", \"en\": \"Fee invoices: Create, edit, view, and search fee invoices.\"}, {\"ar\": \"تحصيل الرسوم: تسجيل دفعات الرسوم ومراجعة كل معاملة.\", \"en\": \"Fee collection: Record fee payments and review each transaction.\"}, {\"ar\": \"ترحيل الأرصدة: نقل المتبقي من رسوم الطالب إلى فترة دراسية أخرى.\", \"en\": \"Balance carry-forward: Move remaining student fees to another academic period.\"}, {\"ar\": \"بحث المتأخرات: البحث عن الرسوم المستحقة وغير المسددة.\", \"en\": \"Due fees search: Find outstanding and unpaid fees.\"}, {\"ar\": \"كشف حساب الرسوم: عرض مدفوعات الطالب ورصيده والمتأخرات.\", \"en\": \"Fee statement: View student payments, balance, and overdue amounts.\"}, {\"ar\": \"تقارير الرسوم: التحصيل، الأرصدة، المعاملات، الغرامات والرسوم بحسب الصف.\", \"en\": \"Fee reports: Collection, balances, transactions, fines, and fees by class.\"}, {\"ar\": \"إعدادات الرسوم: إعداد الخصومات والأسعار والفواتير والقسائم بحسب الصفحات المتاحة.\", \"en\": \"Fee settings: Configure discounts, pricing, invoices, and vouchers.\"}, {\"ar\": \"السداد الإلكتروني: مسارات للمدفوعات الإلكترونية بحسب بوابات الدفع المضبوطة.\", \"en\": \"Online payment: Electronic payment flows based on configured gateways.\"}, {\"ar\": \"قيود الرسوم المتأخرة: إعداد صلاحيات الدخول المرتبطة بالرسوم المستحقة.\", \"en\": \"Overdue fee restrictions: Configure access rules tied to outstanding fees.\"}, {\"ar\": \"محفظة المستخدم: عرض الرصيد وإضافة طلب إيداع ومراجعة المعاملات.\", \"en\": \"User wallet: View balance, request deposits, and review transactions.\"}, {\"ar\": \"مراجعة طلبات المحفظة: قبول أو رفض الإيداعات والمدفوعات وطلبات الاسترداد.\", \"en\": \"Wallet request review: Approve or reject deposits, payments, and refund requests.\"}, {\"ar\": \"تقارير المحفظة: البحث في عمليات المحفظة وإصدار تقرير عنها.\", \"en\": \"Wallet reports: Search wallet operations and generate reports.\"}]}, {\"title\": {\"ar\": \"الحسابات والمشتريات والأصول\", \"en\": \"Accounts, Purchasing & Assets\"}, \"points\": [{\"ar\": \"دليل الحسابات: تعريف الحسابات الرئيسية والفرعية.\", \"en\": \"Chart of accounts: Define main and sub accounts.\"}, {\"ar\": \"الإيرادات والمصروفات: تعريف البنود وتسجيل الإيرادات والمصروفات.\", \"en\": \"Income and expenses: Define items and record income and expenses.\"}, {\"ar\": \"القيود اليومية: إدخال القيود والمراجعة المحاسبية.\", \"en\": \"Journal entries: Enter journals and perform accounting review.\"}, {\"ar\": \"التحويلات بين الحسابات: تنفيذ التحويلات المالية الداخلية.\", \"en\": \"Account transfers: Perform internal financial transfers.\"}, {\"ar\": \"مراكز التكلفة: تعريف الأنواع والمراكز وربط العمليات بها.\", \"en\": \"Cost centers: Define types and centers and link transactions to them.\"}, {\"ar\": \"الحسابات البنكية: إضافة الحسابات البنكية وإدارتها.\", \"en\": \"Bank accounts: Add and manage bank accounts.\"}, {\"ar\": \"الميزانية وميزان المراجعة: عرض الميزانية وميزان المراجعة العام والفرعي.\", \"en\": \"Budget and trial balance: View budgets and general or detailed trial balances.\"}, {\"ar\": \"تقارير الحسابات: تقارير الإيرادات والمصروفات وكشوف الحساب والحركة المالية.\", \"en\": \"Account reports: Income, expense, statement, and financial movement reports.\"}, {\"ar\": \"التقارير الضريبية: تقارير ضريبية وتصدير الإقرارات بحسب النماذج الموجودة.\", \"en\": \"Tax reports: Generate tax reports and export filings using available templates.\"}, {\"ar\": \"فئات الموردين: تصنيف الموردين وتسجيل بياناتهم.\", \"en\": \"Vendor categories: Classify vendors and manage their records.\"}, {\"ar\": \"العقود: إنشاء العقود وقوالب العقود ومتابعتها.\", \"en\": \"Contracts: Create contracts and templates and track them.\"}, {\"ar\": \"الفواتير العامة: إدارة الفواتير خارج رسوم الطلاب من وحدة الفواتير.\", \"en\": \"General invoices: Manage invoices outside student fees via the billing module.\"}, {\"ar\": \"الأصول الثابتة: إدارة الأصل وفئات الأصول وأنواعها والعمليات المرتبطة بها في المسارات الموجودة.\", \"en\": \"Fixed assets: Manage assets, categories, types, and related operations.\"}, {\"ar\": \"العهد: تسليم العهد وتتبعها وتقاريرها.\", \"en\": \"Custody items: Hand over, track, and report on custodial assets.\"}]}, {\"title\": {\"ar\": \"الموارد البشرية\", \"en\": \"Human Resources\"}, \"points\": [{\"ar\": \"دليل الموظفين: إضافة الموظفين، تعديل ملفاتهم، البحث عنهم وتصدير البيانات.\", \"en\": \"Staff directory: Add employees, edit profiles, search, and export data.\"}, {\"ar\": \"تصنيف الموظفين: إدارة الأقسام والمسميات الوظيفية والفروع والفئات.\", \"en\": \"Staff classification: Manage departments, designations, branches, and categories.\"}, {\"ar\": \"بيانات الوظيفة: أنواع الوظائف والمؤهلات/الأهلية التعليمية والجنسيات والمرشدين.\", \"en\": \"Job data: Job types, qualifications, nationalities, and counselors.\"}, {\"ar\": \"ملف الموظف: المستندات والصورة والخط الزمني وحالة التفعيل.\", \"en\": \"Employee profile: Documents, photo, timeline, and activation status.\"}, {\"ar\": \"الرواتب: إعداد بنود الرواتب، توليد كشوف الرواتب وتقاريرها.\", \"en\": \"Payroll: Configure salary items and generate payroll sheets and reports.\"}, {\"ar\": \"مسار الراتب: تقرير مستقل لمسار الراتب مع الطباعة والتصدير.\", \"en\": \"Salary trail: A dedicated salary trail report with print and export.\"}, {\"ar\": \"تقارير الدوام والانصراف: تقارير يومية وشهرية لحضور الموظفين وانصرافهم.\", \"en\": \"Attendance reports: Daily and monthly staff attendance and departure reports.\"}, {\"ar\": \"تقييم المعلمين: إعداد التقييم، إرساله من حساب الطالب/ولي الأمر، مراجعة الطلبات وتقارير المعلم.\", \"en\": \"Teacher evaluation: Set up evaluations, collect student/parent submissions, and review teacher reports.\"}, {\"ar\": \"أجر الساعة: تعريف معدلات الأجر بالساعة.\", \"en\": \"Hourly rates: Define hourly pay rates.\"}, {\"ar\": \"الإجازات: تحديد الأنواع والأرصدة وطلبات الإجازة واعتمادها.\", \"en\": \"Leave management: Define leave types and balances and approve leave requests.\"}, {\"ar\": \"الورديات: إنشاء الورديات وإسنادها للموظفين.\", \"en\": \"Shifts: Create shifts and assign them to staff.\"}, {\"ar\": \"ربط الموظف بولي أمر: تسجيل الموظف كولي أمر عند الحاجة.\", \"en\": \"Link staff to parents: Register an employee as a parent when needed.\"}]}, {\"title\": {\"ar\": \"المكتبة والنقل والسكن والمخزون\", \"en\": \"Library, Transport, Hostel & Inventory\"}, \"points\": [{\"ar\": \"فهرس المكتبة: إدارة الكتب والتصنيفات والموضوعات.\", \"en\": \"Library catalog: Manage books, categories, and subjects.\"}, {\"ar\": \"أعضاء المكتبة: تسجيل الأعضاء وحركة استعارة الكتب وإعادتها.\", \"en\": \"Library members: Register members and track book issue and return.\"}, {\"ar\": \"النقل المدرسي: إدارة الخطوط والمركبات والسائقين وإسناد المركبات للطلاب.\", \"en\": \"School transport: Manage routes, vehicles, and drivers and assign vehicles to students.\"}, {\"ar\": \"تقارير النقل: عرض بيانات الخطوط والمركبات والطلاب المشتركين.\", \"en\": \"Transport reports: View route, vehicle, and enrolled student data.\"}, {\"ar\": \"السكن المدرسي: إدارة المباني وأنواع الغرف والغرف وتسكين الطلاب وتقاريره.\", \"en\": \"School hostel: Manage buildings, room types, rooms, student allocation, and reports.\"}, {\"ar\": \"الأصناف والمخازن: تعريف المواد والتصنيفات والمخازن والكميات.\", \"en\": \"Items and warehouses: Define materials, categories, warehouses, and quantities.\"}, {\"ar\": \"حركة المخزون: تسجيل الشراء والاستلام والتسليم والتحويل والبيع.\", \"en\": \"Inventory movement: Record purchase, receive, issue, transfer, and sale.\"}, {\"ar\": \"الموردون: تعريف الموردين وربطهم بالمشتريات.\", \"en\": \"Suppliers: Define suppliers and link them to purchases.\"}, {\"ar\": \"تقارير المخزون: حركة الأصناف والمشتريات والمبيعات والأرصدة.\", \"en\": \"Inventory reports: Item movement, purchases, sales, and balances.\"}, {\"ar\": \"إعدادات نقطة البيع: إعداد تصنيفات البيع والشراء وخيارات البيع.\", \"en\": \"POS settings: Configure sales and purchase categories and selling options.\"}]}, {\"title\": {\"ar\": \"التواصل وشؤون الإدارة\", \"en\": \"Communication & Administration\"}, \"points\": [{\"ar\": \"لوحة الإعلانات: نشر الإعلانات وعرضها للطلاب وأولياء الأمور.\", \"en\": \"Notice board: Publish announcements and show them to students and parents.\"}, {\"ar\": \"الأحداث والتقويم: إنشاء الفعاليات والرجوع إلى التقويم الدراسي.\", \"en\": \"Events and calendar: Create events and access the school calendar.\"}, {\"ar\": \"البريد والرسائل القصيرة: إرسال الرسائل وإدارة القوالب وإعدادات البوابات وسجل الإرسال.\", \"en\": \"Email and SMS: Send messages, manage templates and gateways, and review sending logs.\"}, {\"ar\": \"الإشعارات: ضبط أنواع الإشعارات وإعدادات إرسالها.\", \"en\": \"Notifications: Configure notification types and delivery settings.\"}, {\"ar\": \"الدردشة: محادثات فردية وجماعية ومجموعات الصفوف عند تفعيل الوحدة.\", \"en\": \"Chat: One-to-one and group chats, including class groups when the module is enabled.\"}, {\"ar\": \"دعم واتساب: إعداد قناة الدعم والوكلاء وإرسال الرسائل ومتابعة التحليلات.\", \"en\": \"WhatsApp support: Configure support channels and agents, send messages, and monitor analytics.\"}, {\"ar\": \"سجل الزوار: تسجيل الزائر وسبب الزيارة والمستندات.\", \"en\": \"Visitor log: Register visitors, visit reasons, and documents.\"}, {\"ar\": \"الشكاوى: تسجيل الشكاوى ومتابعة حالاتها.\", \"en\": \"Complaints: Register complaints and track their status.\"}, {\"ar\": \"المكالمات: تسجيل المكالمات الهاتفية والرجوع إليها.\", \"en\": \"Calls: Log phone calls and review their history.\"}, {\"ar\": \"البريد الوارد والصادر: قيد المراسلات والطرود والوثائق.\", \"en\": \"Incoming and outgoing mail: Record correspondence, parcels, and documents.\"}, {\"ar\": \"سجلات السلوك والحوادث: تعريف الحوادث وإسنادها إلى الطلاب، التعليقات والتقارير والترتيب السلوكي.\", \"en\": \"Behaviour and incident records: Define incidents, assign them to students, and manage comments, reports, and ranking.\"}]}, {\"title\": {\"ar\": \"البوابة العامة والمحتوى\", \"en\": \"Public Portal & Content\"}, \"points\": [{\"ar\": \"الموقع التعريفي للمدرسة: إدارة الصفحة الرئيسية والصفحات التعريفية وقوائم الموقع.\", \"en\": \"School website: Manage the homepage, about pages, and site menus.\"}, {\"ar\": \"الأخبار والتعليقات: نشر الأخبار، تصنيفها ومراجعة تعليقات الزوار.\", \"en\": \"News and comments: Publish and categorize news and moderate visitor comments.\"}, {\"ar\": \"المعارض: إدارة الصور والفيديوهات والشرائح الرئيسية.\", \"en\": \"Galleries: Manage photos, videos, and homepage sliders.\"}, {\"ar\": \"الدورات والمعلمون: عرض الدورات وفئاتها والمعلمين المميزين.\", \"en\": \"Courses and teachers: Showcase courses, categories, and featured teachers.\"}, {\"ar\": \"نماذج التواصل: استقبال رسائل الموقع وإدارة بيانات الاتصال وروابط التواصل الاجتماعي.\", \"en\": \"Contact forms: Receive website messages and manage contact details and social links.\"}, {\"ar\": \"التقويم والنتائج العامة: نشر الجداول والنتائج والتقويم وفق إعدادات الواجهة.\", \"en\": \"Public calendar and results: Publish schedules, results, and calendars based on frontend settings.\"}, {\"ar\": \"نماذج التنزيل والشهادات: إتاحة ملفات ونماذج عبر الواجهة العامة.\", \"en\": \"Downloadable forms and certificates: Provide files and templates through the public site.\"}, {\"ar\": \"تسجيل ولي الأمر: صفحة تسجيل مرتبطة بوحدة التسجيل المفعّلة.\", \"en\": \"Parent registration: A registration page linked to the enabled registration module.\"}, {\"ar\": \"منشئ الصفحات: تحرير الصفحات وإعداداتها من الحزمة الموجودة في المشروع.\", \"en\": \"Page builder: Edit pages and settings using the package included in the project.\"}]}, {\"title\": {\"ar\": \"حساب الطالب وولي الأمر\", \"en\": \"Student & Parent Accounts\"}, \"points\": [{\"ar\": \"حساب الطالب: الملف الشخصي، الحضور، الجدول، المواد، الواجبات، الاختبارات والنتائج.\", \"en\": \"Student account: Profile, attendance, timetable, subjects, homework, exams, and results.\"}, {\"ar\": \"خدمات الطالب: الرسوم، النقل، السكن، المكتبة، الإعلانات والمواد القابلة للتحميل.\", \"en\": \"Student services: Fees, transport, hostel, library, notices, and downloadable materials.\"}, {\"ar\": \"حساب ولي الأمر: اختيار أحد الأبناء ومتابعة ملفه ورسومه وحضوره وجدوله وواجباته ونتائجه.\", \"en\": \"Parent account: Select a child and follow their profile, fees, attendance, timetable, homework, and results.\"}, {\"ar\": \"طلبات ولي الأمر: طلب الإجازات، تأكيد استلام الاستدعاء وتغيير طريقة انصراف الطالب.\", \"en\": \"Parent requests: Leave requests, summons acknowledgment, and pickup method changes.\"}, {\"ar\": \"متابعة تعليم الأبناء: عرض المعلمين والمواد والمكتبة والنقل والسكن لكل ابن.\", \"en\": \"Children learning follow-up: View teachers, subjects, library, transport, and hostel for each child.\"}, {\"ar\": \"حساب الخريج: لوحة للخريج مع ملفه والأحداث والمستندات.\", \"en\": \"Alumni account: An alumni dashboard with profile, events, and documents.\"}]}, {\"title\": {\"ar\": \"الطباعة والتصدير والتقارير\", \"en\": \"Printing, Export & Reports\"}, \"points\": [{\"ar\": \"الطباعة الجماعية: بطاقات الطلاب والموظفين والشهادات وإيصالات/فواتير الرسوم وكشوف الرواتب.\", \"en\": \"Bulk printing: Student and staff cards, certificates, fee receipts/invoices, and payroll sheets.\"}, {\"ar\": \"تخصيص نماذج الطباعة: إعداد شكل الفاتورة وبطاقة الاختبار وخطة الجلوس والشهادات.\", \"en\": \"Print template customization: Configure invoice, exam card, seating plan, and certificate layouts.\"}, {\"ar\": \"تصدير البيانات: تصدير بيانات الطلاب والموظفين وتقارير حسابية ومالية إلى Excel.\", \"en\": \"Data export: Export student and staff data and accounting/financial reports to Excel.\"}, {\"ar\": \"مراكز التقارير: صفحات تجمع تقارير الطلاب والأكاديميات والاختبارات والرسوم والحسابات والموظفين والمخزون والنقل والسلوك.\", \"en\": \"Report centers: Pages that gather student, academic, exam, fee, accounting, staff, inventory, transport, and behaviour reports.\"}]}]', NULL, NULL, NULL, 15, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-05 06:43:53', '2026-09-30 15:18:48', NULL);
INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(23, '{\"ar\":\"تعمير — منصة إدارة المرافق والصيانة\",\"en\":\"Tameer — Facilities & Maintenance\"}', 'tameer-facilities-maintenance', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة متكاملة لإدارة المرافق والأصول وأعمال الصيانة، تجمع إدارة المواقع، وأوامر العمل، والصيانة الوقائية، ومتابعة أداء فرق التشغيل في نظام مركزي واحد.\",\"en\":\"An integrated platform for managing facilities, assets, and maintenance operations, bringing multiple sites, work orders, preventive maintenance, and team performance into one centralized system.\"}', '{\"ar\":\"تعمير منصة رقمية تساعد الشركات وفرق إدارة المرافق على تنظيم عمليات التشغيل والصيانة عبر مواقع متعددة. تربط المنصة بين المواقع والمباني والأصول وفرق العمل، وتتيح متابعة طلبات الصيانة من تسجيل البلاغ وتعيين الفني وحتى التنفيذ والمراجعة والإغلاق.\\r\\n\\r\\nوتجمع المنصة بين جدولة الصيانة الوقائية، وإدارة الأعطال، ومتابعة اتفاقيات مستوى الخدمة، وتوثيق الحوادث ومتطلبات تصاريح العمل. كما توفر تقارير ومؤشرات أداء تمنح الإدارة رؤية أوضح لحالة الأصول، وتقدم الأعمال، وأداء الفرق.\",\"en\":\"Tameer is a digital platform that helps companies and facilities management teams coordinate operations and maintenance across multiple sites. It connects locations, buildings, assets, and teams, allowing maintenance requests to be tracked from initial reporting and technician assignment through execution, review, and closure.\\r\\n\\r\\nThe platform combines preventive maintenance scheduling, corrective work orders, service level tracking, incident documentation, and work permit requirements. Reports and performance indicators give management clearer visibility into asset condition, work progress, and team performance.\"}', '{\"ar\":\"تواجه إدارة المرافق صعوبة في متابعة الأصول وأعمال الصيانة عند توزيع البيانات بين ملفات منفصلة وقنوات تواصل متعددة. ويزداد التحدي مع تعدد المواقع وفرق العمل، مما يصعّب تحديد المسؤوليات، ومتابعة الطلبات المتأخرة، والالتزام بمواعيد الصيانة الدورية.\\r\\n\\r\\nكذلك، فإن غياب سجل موحد للأعمال ومؤشرات واضحة للأداء يحدّ من قدرة الإدارة على تقييم جودة الخدمة واتخاذ قرارات مبنية على بيانات.\",\"en\":\"Managing facilities becomes difficult when asset records and maintenance activities are spread across separate files and communication channels. As the number of sites and teams grows, assigning responsibility, tracking overdue requests, and keeping up with scheduled maintenance become increasingly challenging.\\r\\n\\r\\nWithout a unified maintenance history and clear performance indicators, management has limited visibility into service quality and fewer reliable insights to support operational decisions.\"}', '{\"ar\":\"توحّد تعمير بيانات المرافق وعمليات الصيانة داخل منصة واحدة، تربط كل طلب بالموقع والأصل والفريق المسؤول. وتوفر مسارًا واضحًا لتنفيذ أوامر العمل، مع توليد أوامر الصيانة الوقائية تلقائيًا وفق الجداول المحددة، ومتابعة أوقات الاستجابة والإنجاز.\\r\\n\\r\\nومن خلال سجلات الصيانة، والإشعارات، والتقارير، تساعد المنصة على تنظيم العمل اليومي، وتقليل المتابعة اليدوية، وتحسين التنسيق بين الإدارة والمشرفين والفنيين.\",\"en\":\"Tameer centralizes facilities data and maintenance workflows, connecting each request to its location, asset, and responsible team. It provides a structured work order lifecycle, automatically generates preventive maintenance work orders according to configured schedules, and tracks response and resolution targets.\\r\\n\\r\\nThrough maintenance records, notifications, and reporting, the platform helps organize daily operations, reduce manual follow-ups, and improve coordination between managers, supervisors, and technicians.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة الشركات\", \"en\": \"Company Management\"}, \"points\": [{\"ar\": \"إنشاء الشركات وعرض تفاصيلها وتعديلها وحذفها.\", \"en\": \"Create, view, update, and delete companies.\"}, {\"ar\": \"تصفية قائمة الشركات والبحث فيها وعرض إحصاءاتها وتصدير بياناتها.\", \"en\": \"Filter and search companies, view their statistics, and export their data.\"}, {\"ar\": \"إدارة معلومات العميل وبيانات التواصل والبريد المخصص للمشتريات والمكتب الخلفي.\", \"en\": \"Manage client information, contact details, and procurement and back-office email addresses.\"}, {\"ar\": \"ضبط إعدادات الإشعارات والأمان لكل شركة.\", \"en\": \"Configure notification and security settings for each company.\"}]}, {\"title\": {\"ar\": \"إدارة المواقع\", \"en\": \"Site Management\"}, \"points\": [{\"ar\": \"إنشاء المواقع وعرضها وتعديلها وحذفها وتعطيلها.\", \"en\": \"Create, view, update, delete, and deactivate sites.\"}, {\"ar\": \"ربط المواقع بالشركات وتعيين مدير لكل موقع.\", \"en\": \"Link sites to companies and assign a manager to each site.\"}, {\"ar\": \"حفظ بيانات الموقع وساعات عمله ومعلوماته الجغرافية.\", \"en\": \"Store site details, working hours, and geographic information.\"}, {\"ar\": \"تحديد الموقع الحالي للمستخدم وحصر البيانات بالمواقع المسموح له الوصول إليها.\", \"en\": \"Select a user\'s current site and scope data to sites they can access.\"}, {\"ar\": \"تنزيل قالب المواقع واستيرادها جماعيًا وتصدير بياناتها، بما في ذلك تصدير شامل لبيانات المواقع.\", \"en\": \"Download a site template, bulk import sites, and export site data, including a full site data export.\"}]}, {\"title\": {\"ar\": \"هيكل المواقع والوحدات\", \"en\": \"Location Hierarchy\"}, \"points\": [{\"ar\": \"إدارة المناطق والمباني والأدوار والوحدات داخل المواقع.\", \"en\": \"Manage zones, buildings, floors, and units within sites.\"}, {\"ar\": \"استعراض أدوار ووحدات المبنى ووحدات كل دور.\", \"en\": \"Browse a building\'s floors and units and the units on each floor.\"}, {\"ar\": \"استيراد المباني والأدوار والوحدات من قوالب جاهزة.\", \"en\": \"Import buildings, floors, and units using downloadable templates.\"}, {\"ar\": \"التحقق من اتساق الموقع والمبنى والدور والوحدة عند تسجيل أوامر العمل.\", \"en\": \"Validate the site, building, floor, and unit hierarchy when creating work orders.\"}]}, {\"title\": {\"ar\": \"المستخدمون والفرق\", \"en\": \"Users and Teams\"}, \"points\": [{\"ar\": \"إنشاء المستخدمين وعرض ملفاتهم وتعديل بياناتهم وحذفهم.\", \"en\": \"Create users, view their profiles, update their details, and delete them.\"}, {\"ar\": \"ربط المستخدمين بموقع واحد أو أكثر وبالأقسام المناسبة وإزالة ارتباطهم بموقع.\", \"en\": \"Assign users to one or more sites and departments, and remove site assignments.\"}, {\"ar\": \"تفعيل المستخدمين أو إيقافهم، مع إمكانية التفعيل الجماعي.\", \"en\": \"Activate or suspend users, including bulk activation.\"}, {\"ar\": \"استعراض الفنيين وإحصاءات المستخدمين وأداء أوامر العمل المرتبطة بهم.\", \"en\": \"List technicians and view user statistics and related work order performance.\"}, {\"ar\": \"إدارة الأقسام وتوزيع المستخدمين عليها.\", \"en\": \"Manage departments and assign users to them.\"}]}, {\"title\": {\"ar\": \"الحسابات والأمان\", \"en\": \"Accounts and Security\"}, \"points\": [{\"ar\": \"تسجيل حساب جديد وتسجيل الدخول والخروج باستخدام جلسات API.\", \"en\": \"Register accounts and sign in and out through API sessions.\"}, {\"ar\": \"عرض الملف الشخصي وتعديله وتغيير كلمة المرور وحذف الحساب.\", \"en\": \"View and update profiles, change passwords, and delete accounts.\"}, {\"ar\": \"استعادة كلمة المرور باستخدام رمز تحقق يُرسل بالبريد الإلكتروني.\", \"en\": \"Reset forgotten passwords using an email verification code.\"}, {\"ar\": \"إرسال رمز التحقق بخطوتين والتحقق منه، مع إعداد لإلزام الشركة به.\", \"en\": \"Send and verify two-factor authentication codes, with a company setting to require them.\"}, {\"ar\": \"عرض الحالة الأمنية للحساب وإلغاء الجلسات المسجلة.\", \"en\": \"View account security status and revoke active sessions.\"}, {\"ar\": \"التحكم في الصلاحيات حسب الدور، وعرض صلاحيات الأدوار وتحديثها.\", \"en\": \"Control access by role, view role permissions, and update permission assignments.\"}]}, {\"title\": {\"ar\": \"الأصول وتصنيفاتها\", \"en\": \"Assets and Categories\"}, \"points\": [{\"ar\": \"تسجيل الأصول وعرضها وتعديلها وحذفها وتصفيتها حسب الموقع والحالة والتصنيف.\", \"en\": \"Register, view, update, delete, and filter assets by site, status, and category.\"}, {\"ar\": \"إدارة تصنيفات الأصول الهرمية والبحث ضمن التصنيفات الفرعية.\", \"en\": \"Manage hierarchical asset categories and search through child categories.\"}, {\"ar\": \"توليد رقم تسلسلي للأصل وربطه بالموقع والتصنيف.\", \"en\": \"Generate asset serial numbers associated with their site and category.\"}, {\"ar\": \"إنشاء رمز QR للأصل وتنزيله ومسحه لعرض بيانات الأصل وجدول صيانته.\", \"en\": \"Generate and download asset QR codes, and scan them to view asset details and maintenance schedules.\"}, {\"ar\": \"إظهار أمر العمل المفتوح المسند للفني على الأصل عند مسح رمزه.\", \"en\": \"Show the scanning technician\'s assigned open work order for the asset.\"}, {\"ar\": \"عرض خطط الصيانة الوقائية المرتبطة بالأصل وإحصاءات الأصول.\", \"en\": \"View an asset\'s related preventive maintenance plans and asset statistics.\"}, {\"ar\": \"رفع صور وملفات الأصول بصورة فردية أو جماعية.\", \"en\": \"Upload asset images and files individually or in bulk.\"}, {\"ar\": \"تنزيل قالب الأصول واستيرادها جماعيًا وتصدير بياناتها.\", \"en\": \"Download an asset template, bulk import assets, and export asset data.\"}]}, {\"title\": {\"ar\": \"خطط الصيانة الوقائية\", \"en\": \"Preventive Maintenance Plans\"}, \"points\": [{\"ar\": \"إنشاء خطط صيانة وقائية وعرضها وتعديلها وحذفها وتجديدها.\", \"en\": \"Create, view, update, delete, and renew preventive maintenance plans.\"}, {\"ar\": \"تحديد دورية الخطة اليومية أو الأسبوعية أو الشهرية أو الربع سنوية أو السنوية.\", \"en\": \"Set daily, weekly, monthly, quarterly, or yearly plan frequencies.\"}, {\"ar\": \"تحديد تاريخ البداية والاستحقاق التالي والمدة التقديرية ومهلة الإسناد.\", \"en\": \"Set start dates, next due dates, estimated durations, and assignment windows.\"}, {\"ar\": \"ربط الخطة بأصول وقوائم فحص متعددة وعرض الفنيين المناسبين لها.\", \"en\": \"Link plans to multiple assets and checklists and list suitable technicians.\"}, {\"ar\": \"عرض إحصاءات الخطط وتنزيل قالبها واستيرادها وتصديرها.\", \"en\": \"View plan statistics, download a template, and import or export plans.\"}, {\"ar\": \"إنشاء أوامر صيانة وقائية تلقائيًا من الخطط المستحقة عبر مهمة يومية مجدولة.\", \"en\": \"Automatically generate preventive work orders from due plans through a daily scheduled job.\"}]}, {\"title\": {\"ar\": \"قوائم الفحص ومهام الصيانة\", \"en\": \"Checklists and Maintenance Tasks\"}, \"points\": [{\"ar\": \"إنشاء قوائم الفحص وعرضها وتعديلها وحذفها وربطها بالأصول وخطط الصيانة.\", \"en\": \"Create, view, update, and delete checklists linked to assets and maintenance plans.\"}, {\"ar\": \"تنظيم مهام القائمة داخل مجموعات قابلة للإدارة والترتيب.\", \"en\": \"Organize checklist tasks into manageable, ordered groups.\"}, {\"ar\": \"إنشاء مهام الصيانة وتعديلها وحذفها وتحديد تفاصيلها.\", \"en\": \"Create, update, and delete maintenance tasks and define their details.\"}, {\"ar\": \"عرض إحصاءات قوائم الفحص وتصفية الأصول المناسبة لها.\", \"en\": \"View checklist statistics and filter eligible assets.\"}, {\"ar\": \"تنزيل قوالب قوائم الفحص ومهام الصيانة واستيرادها، مع تصدير قوائم الفحص.\", \"en\": \"Download and import checklist and maintenance task templates, and export checklists.\"}]}, {\"title\": {\"ar\": \"أوامر الصيانة الوقائية المفتوحة\", \"en\": \"Open Preventive Work Orders\"}, \"points\": [{\"ar\": \"عرض أوامر الصيانة الوقائية المفتوحة وتفاصيل الخطة والأصل والمهام المرتبطة بها.\", \"en\": \"View open preventive work orders with their related plan, asset, and task details.\"}, {\"ar\": \"تصفية الأوامر حسب الحالة والدورية والتاريخ والموقع وفئة الخدمة وقطع الغيار، مع البحث النصي.\", \"en\": \"Filter orders by status, frequency, date, location, service class, and spare parts, with text search.\"}, {\"ar\": \"إسناد أمر وقائي إلى فني وتحديد موعد انتهاء الإسناد.\", \"en\": \"Assign a preventive work order to a technician with an assignment deadline.\"}, {\"ar\": \"إسناد أو حذف عدة أوامر وقائية دفعة واحدة وفق الصلاحيات.\", \"en\": \"Assign or delete multiple preventive work orders in one authorized action.\"}, {\"ar\": \"إيقاف أمر الصيانة الوقائية مؤقتًا مع السبب والملاحظات، ثم استئناف تنفيذه.\", \"en\": \"Put a preventive work order on hold with a reason and remarks, then resume it.\"}, {\"ar\": \"إكمال الأمر بعد إنجاز مهام الفحص وإرفاق صورة، مع حفظ الملاحظات.\", \"en\": \"Complete the order after checklist tasks are done and a photo is attached, with optional notes.\"}, {\"ar\": \"عرض إحصاءات الأوامر الوقائية وتصديرها.\", \"en\": \"View preventive work order statistics and export their data.\"}]}, {\"title\": {\"ar\": \"أوامر الصيانة التصحيحية\", \"en\": \"Corrective Work Orders\"}, \"points\": [{\"ar\": \"إنشاء طلب صيانة تصحيحية مرتبط بالموقع والمكان والقسم والأصل ونوع الخدمة والأولوية.\", \"en\": \"Create corrective requests linked to a site, location, department, asset, service type, and priority.\"}, {\"ar\": \"إرفاق الصور والوصف ومصدر الطلب الخارجي عند تسجيل الطلب.\", \"en\": \"Attach photos and descriptions and record an external request source when creating a request.\"}, {\"ar\": \"عرض الطلبات والبحث فيها وتصفيتها وعرض تفاصيلها وتعديلها وحذفها.\", \"en\": \"List, search, filter, view, update, and delete corrective requests.\"}, {\"ar\": \"إسناد الطلب إلى فني وإعادة إسناده وتسجيل سجل الإسناد وتغيرات الحالة.\", \"en\": \"Assign and reassign requests to technicians and record assignment and status history.\"}, {\"ar\": \"إدارة مراحل الاستجابة وبدء العمل والإيقاف المؤقت والاستئناف والإكمال والمراجعة والإغلاق.\", \"en\": \"Manage response, start, hold, resume, completion, review, and closure stages.\"}, {\"ar\": \"إعادة الطلب إلى الفني نفسه مع ملاحظات عند الحاجة إلى استكمال العمل.\", \"en\": \"Return a request to the same technician with remarks when more work is needed.\"}, {\"ar\": \"عرض إحصاءات الطلبات التصحيحية والفنيين المتاحين للإسناد.\", \"en\": \"View corrective request statistics and technicians available for assignment.\"}]}, {\"title\": {\"ar\": \"اتفاقيات مستوى الخدمة\", \"en\": \"Service Level Agreements\"}, \"points\": [{\"ar\": \"إعداد مدد الاستجابة والحل حسب الموقع ونوع الخدمة والأولوية.\", \"en\": \"Configure response and resolution targets by site, service type, and priority.\"}, {\"ar\": \"احتساب مواعيد الاستجابة والحل عند إنشاء طلب الصيانة التصحيحية مع مراعاة ساعات عمل الموقع.\", \"en\": \"Calculate response and resolution deadlines when corrective requests are created, using site working hours.\"}, {\"ar\": \"إيقاف احتساب مدة SLA أثناء تعليق الطلب وتمديد موعد الاستحقاق عند استئنافه.\", \"en\": \"Pause SLA time while a request is on hold and extend deadlines when work resumes.\"}, {\"ar\": \"إظهار زمن العمل الفعلي والوقت المجمّد ومدى الالتزام بمواعيد الاستجابة والحل.\", \"en\": \"Show active work time, frozen time, and response and resolution SLA performance.\"}, {\"ar\": \"استخدام نتائج SLA في اللوحات والتقارير وإحصاءات المواقع والفنيين.\", \"en\": \"Use SLA results in dashboards, reports, and site and technician statistics.\"}]}, {\"title\": {\"ar\": \"تنفيذ أوامر العمل وقطع الغيار\", \"en\": \"Work Execution and Spare Parts\"}, \"points\": [{\"ar\": \"عرض أوامر العمل المسندة للفني وإحصاءاتها ومؤشرات أدائه.\", \"en\": \"View a technician\'s assigned work orders, statistics, and performance metrics.\"}, {\"ar\": \"عرض مهام أمر العمل وإكمالها وتعديل نتيجة كل مهمة أو التراجع عن إكمالها.\", \"en\": \"View work order tasks, complete them, update task results, or undo completion.\"}, {\"ar\": \"إضافة قطع الغيار المستخدمة في أمر العمل وتعديلها وحذفها وربطها بالأصل.\", \"en\": \"Add, update, and remove spare parts used on a work order and link them to its asset.\"}, {\"ar\": \"إنشاء طلبات قطع غيار للأوامر التصحيحية وعرضها.\", \"en\": \"Create and view spare parts requests for corrective work orders.\"}, {\"ar\": \"حفظ صور العمل والملاحظات وسجل الحالة أثناء تنفيذ الأوامر.\", \"en\": \"Save work photos, notes, and status history during order execution.\"}]}, {\"title\": {\"ar\": \"البلاغات والحوادث\", \"en\": \"Incidents\"}, \"points\": [{\"ar\": \"تسجيل الحوادث وعرضها وتعديلها وحذفها ومتابعة حالتها.\", \"en\": \"Record, view, update, delete, and track incidents.\"}, {\"ar\": \"تحديد تصنيف الحادث وشدته وموقعه ووقته والمتضررين والشهود.\", \"en\": \"Record incident classification, severity, location, time, affected people, and witnesses.\"}, {\"ar\": \"توثيق الإجراءات الفورية والعوامل المساهمة والملاحظات والحاجة إلى التصعيد.\", \"en\": \"Document immediate actions, contributing factors, notes, and escalation needs.\"}, {\"ar\": \"إرفاق صور وملفات بالحادث وإضافة بلاغ مبسط من الموبايل.\", \"en\": \"Attach incident media and submit a simplified incident report from mobile.\"}, {\"ar\": \"عرض إحصاءات الحوادث وتنزيل قالبها واستيرادها وتصديرها.\", \"en\": \"View incident statistics, download a template, and import or export incidents.\"}]}, {\"title\": {\"ar\": \"تصاريح العمل والسلامة\", \"en\": \"Work Permits and Safety\"}, \"points\": [{\"ar\": \"إنشاء تصاريح وقوائم سلامة للعمل وعرضها وتعديلها وحذفها.\", \"en\": \"Create, view, update, and delete work permits and safety checklists.\"}, {\"ar\": \"تحديد فئة السلامة ونوع العمل والمهام المطلوبة وترتيبها.\", \"en\": \"Set safety categories, work types, required tasks, and task order.\"}, {\"ar\": \"ربط الأصول بالتصريح وإضافتها أو إزالتها أو مزامنة قائمتها.\", \"en\": \"Link assets to permits, add or remove them, or synchronize the asset list.\"}, {\"ar\": \"إدارة قوالب مهام التصاريح بصورة مستقلة.\", \"en\": \"Manage reusable work permit task templates separately.\"}, {\"ar\": \"عرض إحصاءات التصاريح وتنزيل قوالب التصاريح والمهام واستيرادها وتصدير التصاريح.\", \"en\": \"View permit statistics, download and import permit and task templates, and export permits.\"}]}, {\"title\": {\"ar\": \"لوحات المتابعة\", \"en\": \"Dashboards\"}, \"points\": [{\"ar\": \"لوحة رئيسية تعرض مؤشرات أوامر العمل وبطاقات الحالات وتفاصيل كل بطاقة.\", \"en\": \"View a main dashboard with work order KPIs, status cards, and card details.\"}, {\"ar\": \"عرض اتجاه الالتزام باتفاقية الخدمة وتوزيع مصادر الطلبات ومستويات الأولوية.\", \"en\": \"See SLA compliance trends and request source and urgency distributions.\"}, {\"ar\": \"تصفية مؤشرات اللوحة حسب الشركة والموقع والفترة المسموح بها للمستخدم.\", \"en\": \"Filter dashboard metrics by authorized company, site, and date range.\"}, {\"ar\": \"لوحة مخصصة لمدير الموقع تشمل ملخص العمل والتحليلات.\", \"en\": \"Use a site manager dashboard with work summaries and analytics.\"}, {\"ar\": \"لوحة للمشرف تشمل المهام وأعضاء الفريق وتفاصيل المهام وتحليلات الأداء.\", \"en\": \"Use a supervisor dashboard with tasks, team members, task details, and performance analytics.\"}, {\"ar\": \"لوحة موبايل تعرض إجمالي الأوامر وحالاتها والاتجاهات الشهرية وأداء المواقع.\", \"en\": \"Use a mobile dashboard showing order totals, statuses, monthly trends, and site performance.\"}]}, {\"title\": {\"ar\": \"التقارير والتحليلات\", \"en\": \"Reports and Analytics\"}, \"points\": [{\"ar\": \"تحليل إجمالي الطلبات ونسبة الإنجاز ومتوسط الاستجابة ونسبة الالتزام بـSLA.\", \"en\": \"Analyze request totals, completion rate, average response time, and SLA compliance.\"}, {\"ar\": \"عرض اتجاهات الأداء الشهرية ومقارنة المواقع وتوزيع الأولويات وأوقات الحل.\", \"en\": \"View monthly performance trends, site comparisons, priority distribution, and resolution times.\"}, {\"ar\": \"تحليل الأداء حسب نوع الخدمة وإظهار أفضل الفنيين أداءً.\", \"en\": \"Analyze performance by service type and identify top-performing technicians.\"}, {\"ar\": \"تصفية التحليلات حسب الشركة والموقع والقسم ونوع أمر العمل والفترة الزمنية.\", \"en\": \"Filter analytics by company, site, department, work order type, and date range.\"}, {\"ar\": \"تقارير موبايل للعمليات الشهرية وأداء الأصول وإنتاجية الفريق.\", \"en\": \"Access mobile reports for monthly operations, asset performance, and team productivity.\"}, {\"ar\": \"عرض الأصول الأكثر ارتباطًا بأوامر العمل وقياس الإنجاز حسب الموقع والفني.\", \"en\": \"Identify assets with the most work orders and measure completion by site and technician.\"}]}, {\"title\": {\"ar\": \"الإشعارات\", \"en\": \"Notifications\"}, \"points\": [{\"ar\": \"عرض الإشعارات وتفاصيلها وعدد غير المقروء منها وتحديدها كمقروءة.\", \"en\": \"View notifications and details, count unread items, and mark them as read.\"}, {\"ar\": \"إرسال إشعارات مرتبطة بإنشاء أوامر العمل والأحداث المتعلقة بها.\", \"en\": \"Send notifications for work order creation and related events.\"}, {\"ar\": \"دعم الإشعارات الفورية والبريد الإلكتروني وإشعارات الأجهزة المسجلة.\", \"en\": \"Support real-time, email, and registered-device notifications.\"}, {\"ar\": \"تسجيل رموز أجهزة المستخدمين وحذفها لإدارة الإشعارات المحمولة.\", \"en\": \"Register and remove user device tokens for mobile notifications.\"}, {\"ar\": \"ضبط قنوات الإشعار والتنبيهات وملخصات التقارير من إعدادات الشركة والموقع.\", \"en\": \"Configure notification channels, alerts, and report summaries at company and site level.\"}, {\"ar\": \"إرسال ملخص يومي وتقرير أسبوعي مجدولين للمسؤولين عند تفعيلهما.\", \"en\": \"Send scheduled daily summaries and weekly reports to managers when enabled.\"}]}, {\"title\": {\"ar\": \"الاستيراد والتصدير\", \"en\": \"Import and Export\"}, \"points\": [{\"ar\": \"توفير قوالب جاهزة لاستيراد المواقع والمباني والأدوار والوحدات والأصول والخطط وقوائم الفحص والمهام والحوادث والتصاريح.\", \"en\": \"Provide import templates for sites, buildings, floors, units, assets, plans, checklists, tasks, incidents, and permits.\"}, {\"ar\": \"معالجة الاستيراد الكبير على دفعات مع تتبع حالة الدفعة ونتائجها.\", \"en\": \"Process large imports in batches and track batch status and results.\"}, {\"ar\": \"تصدير بيانات الوحدات التشغيلية المتاحة بصيغ جداول بيانات.\", \"en\": \"Export available operational data in spreadsheet formats.\"}, {\"ar\": \"تشغيل التصدير الكبير في الخلفية ومتابعة حالته ثم تنزيل الملف الناتج.\", \"en\": \"Run large exports in the background, track progress, and download the resulting file.\"}, {\"ar\": \"حصر الاستيراد والتصدير ببيانات المواقع التي يحق للمستخدم الوصول إليها.\", \"en\": \"Scope imports and exports to sites the user is authorized to access.\"}]}, {\"title\": {\"ar\": \"الملفات والوسائط\", \"en\": \"Files and Media\"}, \"points\": [{\"ar\": \"رفع ملف واحد أو عدة ملفات عبر API قبل ربطها بالسجلات.\", \"en\": \"Upload one or multiple files through the API before attaching them to records.\"}, {\"ar\": \"ربط الصور والملفات بالأصول والحوادث وأوامر العمل.\", \"en\": \"Attach images and files to assets, incidents, and work orders.\"}, {\"ar\": \"حفظ الملفات المرفوعة مؤقتًا قبل نقلها وربطها بالسجل المناسب.\", \"en\": \"Store uploaded files temporarily before attaching them to the relevant record.\"}]}, {\"title\": {\"ar\": \"سجلات النظام والحوكمة\", \"en\": \"System Logs and Governance\"}, \"points\": [{\"ar\": \"تسجيل أنشطة النظام المهمة وعرض قائمة السجلات وتفاصيل كل سجل.\", \"en\": \"Record important system activity and view system log lists and details.\"}, {\"ar\": \"الاحتفاظ بسجل تغيرات حالات أوامر العمل وإسناداتها.\", \"en\": \"Keep a history of work order status changes and assignments.\"}, {\"ar\": \"تطبيق صلاحيات مفصلة على وحدات الإدارة والعمليات الحساسة.\", \"en\": \"Apply granular permissions to management modules and sensitive operations.\"}, {\"ar\": \"عزل بيانات المواقع بين المستخدمين حسب عضويتهم وصلاحياتهم.\", \"en\": \"Isolate site data according to user membership and permissions.\"}]}]', NULL, NULL, NULL, 42, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-06 05:32:06', '2026-10-01 05:44:29', NULL);
INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(24, '{\"ar\":\"Future ERP\",\"en\":\"Future ERP\"}', 'future-erp', NULL, NULL, NULL, 'web', '{\"ar\":\"Future ERP منصة متكاملة لإدارة موارد المؤسسات، تجمع المحاسبة والمبيعات والمخزون والموارد البشرية وإدارة العملاء والمشروعات في نظام واحد، لمساعدة الشركات على تنظيم أعمالها ومتابعة أدائها بكفاءة.\",\"en\":\"Future ERP is an integrated enterprise resource planning platform that brings accounting, sales, inventory, HR, customer relationships, and project management into one system, helping businesses organize operations and monitor performance efficiently.\"}', '{\"ar\":\"Future ERP نظام لإدارة الأعمال يوحّد العمليات المالية والإدارية والتشغيلية داخل منصة مركزية. يتيح للشركات إدارة دورة العمل بدايةً من متابعة العملاء وإعداد عروض الأسعار، مرورًا بالمبيعات والمشتريات والمخازن، وصولًا إلى المحاسبة والرواتب والتقارير.\\r\\n\\r\\nيعتمد النظام على وحدات قابلة للتفعيل حسب احتياجات كل شركة، مع دعم مساحات عمل متعددة وصلاحيات للمستخدمين وواجهات متعددة اللغات، بما فيها العربية والإنجليزية. كما يضم وحدات متخصصة لقطاعات مختلفة، لتوسيع نطاق الاستخدام مع نمو الأعمال.\",\"en\":\"Future ERP centralizes financial, administrative, and operational processes in a single business management platform. It supports the business cycle from lead tracking and quotations to sales, purchasing, inventory, accounting, payroll, and reporting.\\r\\n\\r\\nIts modular architecture allows companies to activate capabilities according to their needs. With multiple workspaces, user permissions, and multilingual interfaces—including Arabic and English—the platform supports different organizational structures. Industry-specific modules extend its functionality as business requirements evolve.\"}', '{\"ar\":\"تواجه الشركات صعوبة في إدارة أعمالها عندما تتوزع البيانات بين ملفات Excel وبرامج منفصلة لكل قسم. يؤدي ذلك إلى تكرار إدخال المعلومات، وصعوبة مطابقة المبيعات والمخزون والحسابات، وتأخر التقارير، وضعف التنسيق بين فرق العمل.\\r\\n\\r\\nومع زيادة حجم العمليات، تصبح متابعة المستحقات والمصروفات والموظفين والمشروعات أكثر تعقيدًا، وتفتقر الإدارة إلى رؤية موحّدة تساعدها على اتخاذ القرارات.\",\"en\":\"Businesses often manage their operations through spreadsheets and separate applications for each department. This creates duplicate data entry, makes sales, inventory, and accounting records difficult to reconcile, delays reporting, and limits coordination between teams.\\r\\n\\r\\nAs operations grow, tracking outstanding payments, expenses, employees, and projects becomes increasingly complex. Management lacks a consolidated view of the business to support informed decisions.\"}', '{\"ar\":\"يوفّر Future ERP منصة موحّدة تجمع بيانات الأقسام وعملياتها، وتربط متابعة المبيعات والمشتريات والمخزون بالإدارة المالية، مع أدوات لتنظيم شؤون الموظفين والعملاء والمشروعات.\\r\\n\\r\\nومن خلال التقارير والصلاحيات وأتمتة إجراءات العمل، يساعد النظام على تقليل العمل اليدوي، وتسهيل الوصول إلى المعلومات، وتحسين الرقابة على العمليات. وتتيح بنيته المرنة تفعيل الوحدات المناسبة لطبيعة النشاط واحتياجات الشركة.\",\"en\":\"Future ERP brings departmental data and processes into a unified platform, connecting sales, purchasing, and inventory management with financial operations while providing tools for managing employees, customers, and projects.\\r\\n\\r\\nReporting, access controls, and workflow automation help reduce manual work, improve access to information, and strengthen operational oversight. Its flexible module structure allows businesses to activate the capabilities relevant to their industry and requirements.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"المنصة وإدارة الشركات\", \"en\": \"Platform & Company Management\"}, \"points\": [{\"ar\": \"لوحة تحكم لإدارة الأعمال ومتابعة المؤشرات\", \"en\": \"Business dashboard for monitoring operations and key metrics.\"}, {\"ar\": \"إدارة شركات ومساحات عمل متعددة مع التنقل بينها\", \"en\": \"Manage multiple companies and workspaces and switch between them.\"}, {\"ar\": \"إدارة المستخدمين وملفاتهم الشخصية وكلمات المرور\", \"en\": \"Manage users, profiles, and passwords.\"}, {\"ar\": \"أدوار وصلاحيات قابلة للتخصيص حسب الوحدة\", \"en\": \"Custom roles and permissions by module.\"}, {\"ar\": \"إدارة الخطط والاشتراكات والتجارب والوحدات الإضافية\", \"en\": \"Manage plans, subscriptions, trials, and add-on modules.\"}, {\"ar\": \"كوبونات خصم للاشتراكات والعملاء\", \"en\": \"Create discount coupons for subscriptions and customers.\"}, {\"ar\": \"إعدادات الشركة والعملات والمناطق الزمنية واللغة\", \"en\": \"Configure company settings, currencies, time zones, and languages.\"}, {\"ar\": \"قوالب البريد والإشعارات وإعدادات الإرسال\", \"en\": \"Configure email and notification templates and delivery settings.\"}, {\"ar\": \"استيراد المستخدمين وتصدير البيانات إلى Excel\", \"en\": \"Import users and export data to Excel.\"}, {\"ar\": \"إدارة طلبات النطاق المخصص وبرنامج الإحالة\", \"en\": \"Manage custom domain requests and referrals.\"}]}, {\"title\": {\"ar\": \"العملاء والموردون والحسابات الأساسية\", \"en\": \"Customers, Vendors & Core Accounts\"}, \"points\": [{\"ar\": \"إدارة العملاء والموردين وتصنيفاتهم\", \"en\": \"Manage customers, vendors, and their categories.\"}, {\"ar\": \"إدارة الحسابات البنكية والتحويلات بين الحسابات\", \"en\": \"Manage bank accounts and transfers between accounts.\"}, {\"ar\": \"تسجيل الإيرادات والمصروفات والمدفوعات والفواتير الواردة\", \"en\": \"Record revenue, expenses, payments, and bills.\"}, {\"ar\": \"مراكز تكلفة وأنواعها وربط العمليات بها\", \"en\": \"Create cost centers and assign transactions to them.\"}, {\"ar\": \"كشف حساب العميل والمورد ومتابعة الأرصدة\", \"en\": \"View customer and vendor statements and balances.\"}, {\"ar\": \"إشعارات دائنة ومدينة للعملاء\", \"en\": \"Create customer credit and debit notes.\"}]}, {\"title\": {\"ar\": \"المنتجات والمشتريات والمبيعات\", \"en\": \"Products, Purchasing & Sales\"}, \"points\": [{\"ar\": \"إدارة المنتجات والخدمات والفئات والوحدات والضرائب\", \"en\": \"Manage products, services, categories, units, and taxes.\"}, {\"ar\": \"دعم الباركود وصور المنتجات والمخزون\", \"en\": \"Use barcodes, product images, and stock data.\"}, {\"ar\": \"عروض أسعار ومقترحات مع التحويل إلى مستندات بيع\", \"en\": \"Create quotations and proposals and convert them into sales documents.\"}, {\"ar\": \"أوامر شراء، مشتريات، فواتير بيع، ومدفوعات مرتبطة بها\", \"en\": \"Manage purchase orders, purchases, sales invoices, and related payments.\"}, {\"ar\": \"مرتجعات المبيعات والمشتريات وتسوياتها ومدفوعاتها\", \"en\": \"Handle sales and purchase returns, settlements, and payments.\"}, {\"ar\": \"دفعات جماعية للفواتير والمشتريات والمرتجعات\", \"en\": \"Record bulk payments for invoices, purchases, and returns.\"}, {\"ar\": \"قوالب طباعة للفواتير والمشتريات وأوامر الشراء والمرتجعات\", \"en\": \"Customize print templates for invoices, purchases, purchase orders, and returns.\"}, {\"ar\": \"إرسال الفواتير والمقترحات وتذكيرات الدفع بالبريد\", \"en\": \"Email invoices and proposals and send payment reminders.\"}, {\"ar\": \"نسخ المستندات وإرفاق الملفات وتصدير PDF وExcel\", \"en\": \"Duplicate documents, attach files, and export PDF or Excel.\"}, {\"ar\": \"تقارير المبيعات والمشتريات والمرتجعات وأعمار الديون\", \"en\": \"View sales, purchasing, returns, and aging reports.\"}, {\"ar\": \"ربط الفواتير والمرتجعات بتكامل الفوترة الإلكترونية ZATCA\", \"en\": \"Submit invoices and returns through the ZATCA integration.\"}]}, {\"title\": {\"ar\": \"المخازن والمخزون\", \"en\": \"Warehouses & Inventory\"}, \"points\": [{\"ar\": \"إدارة مخازن متعددة وأرصدة المنتجات داخل كل مخزن\", \"en\": \"Manage multiple warehouses and stock balances by location.\"}, {\"ar\": \"تحويل الأصناف بين المخازن مع مستندات قابلة للطباعة\", \"en\": \"Transfer stock between warehouses with printable documents.\"}, {\"ar\": \"أذون إضافة وصرف وتسوية وإهلاك المخزون\", \"en\": \"Create stock addition, removal, adjustment, and depreciation vouchers.\"}, {\"ar\": \"سجل حركة الأصناف وحركات كل إذن ومرفقاته\", \"en\": \"Review item movements, voucher transactions, and attachments.\"}, {\"ar\": \"تقارير رصيد أول المدة والمشتريات والمبيعات والتحويلات\", \"en\": \"View opening balance, purchasing, sales, and transfer reports.\"}, {\"ar\": \"تقارير تفصيلية وملخصة لأذون المخزون مع تصدير Excel\", \"en\": \"Export detailed and summary inventory voucher reports to Excel.\"}]}, {\"title\": {\"ar\": \"المحاسبة والقيد المزدوج\", \"en\": \"Accounting & Double Entry\"}, \"points\": [{\"ar\": \"شجرة حسابات وفترات مالية وقيود يومية\", \"en\": \"Manage chart of accounts, financial periods, and journal entries.\"}, {\"ar\": \"قوالب قيود وإعدادات محاسبية للشركة\", \"en\": \"Use journal templates and company accounting settings.\"}, {\"ar\": \"دفتر الأستاذ وكشف الحساب وتقارير الحسابات\", \"en\": \"View ledgers, statements, and account reports.\"}, {\"ar\": \"تقارير مالية مع تصدير Excel\", \"en\": \"Generate financial reports with Excel export.\"}]}, {\"title\": {\"ar\": \"نقطة البيع\", \"en\": \"Point of Sale\"}, \"points\": [{\"ar\": \"شاشة بيع سريع وبحث بالاسم والباركود\", \"en\": \"Fast checkout with product name and barcode search.\"}, {\"ar\": \"سلة بيع مرتبطة بالأصناف والمخزن والوحدة\", \"en\": \"Cart linked to products, warehouse, and unit.\"}, {\"ar\": \"إعدادات نقطة البيع وتقارير أداء المبيعات\", \"en\": \"Configure POS and review sales performance.\"}]}, {\"title\": {\"ar\": \"الموارد البشرية والرواتب\", \"en\": \"HR & Payroll\"}, \"points\": [{\"ar\": \"ملفات الموظفين والفروع والأقسام والمسميات الوظيفية\", \"en\": \"Manage employee records, branches, departments, and designations.\"}, {\"ar\": \"الحضور والانصراف مع إعدادات الموقع الجغرافي وقيود IP\", \"en\": \"Track attendance with location settings and IP restrictions.\"}, {\"ar\": \"الإجازات والعطلات والتصاريح والخروج في مهام عمل\", \"en\": \"Manage leave, holidays, exit permissions, and business trips.\"}, {\"ar\": \"الرواتب والبدلات والعمولات والقروض والخصومات والعمل الإضافي\", \"en\": \"Manage payroll, allowances, commissions, loans, deductions, and overtime.\"}, {\"ar\": \"الترقيات والنقل والاستقالات وإنهاء الخدمة\", \"en\": \"Record promotions, transfers, resignations, and terminations.\"}, {\"ar\": \"الشكاوى والإنذارات والمكافآت والإعلانات والسياسات\", \"en\": \"Manage complaints, warnings, awards, announcements, and policies.\"}, {\"ar\": \"مستندات الموظفين والفعاليات وتقارير الموارد البشرية\", \"en\": \"Store employee documents and events and view HR reports.\"}]}, {\"title\": {\"ar\": \"التوظيف والأداء والتدريب\", \"en\": \"Recruitment, Performance & Training\"}, \"points\": [{\"ar\": \"وظائف ومرشحون وطلبات توظيف ومراحل فرز ومقابلات\", \"en\": \"Manage jobs, candidates, applications, screening stages, and interviews.\"}, {\"ar\": \"مؤهلات ومهارات وخبرات وأسئلة مخصصة للمرشحين\", \"en\": \"Record candidate qualifications, skills, experience, and custom questions.\"}, {\"ar\": \"أهداف أداء وكفاءات ومؤشرات وتقييمات موظفين\", \"en\": \"Track performance goals, competencies, indicators, and appraisals.\"}, {\"ar\": \"دورات تدريب ومدربون وأنواع تدريب مع تقارير\", \"en\": \"Manage training courses, trainers, training types, and reports.\"}]}, {\"title\": {\"ar\": \"إدارة علاقات العملاء والبيع\", \"en\": \"CRM & Sales Pipeline\"}, \"points\": [{\"ar\": \"عملاء محتملون وصفقات ومراحل وخطوط بيع\", \"en\": \"Manage leads, deals, stages, and pipelines.\"}, {\"ar\": \"تصنيفات ومصادر للفرص مع تقارير ولوحة تحكم CRM\", \"en\": \"Classify lead sources and view CRM reports and dashboard.\"}, {\"ar\": \"جهات اتصال وحسابات وفرص ومكالمات واجتماعات\", \"en\": \"Manage contacts, accounts, opportunities, calls, and meetings.\"}, {\"ar\": \"عروض أسعار وأوامر بيع وفواتير بيع ومستندات العملاء\", \"en\": \"Create quotes, sales orders, sales invoices, and customer documents.\"}, {\"ar\": \"إدارة مندوبي المبيعات وبرامجهم وطلبات انضمامهم وتقاريرهم\", \"en\": \"Manage sales agents, programs, join requests, and reports.\"}, {\"ar\": \"عمولات بخططها وإيصالاتها وتحويلاتها البنكية\", \"en\": \"Manage commission plans, receipts, and bank transfers.\"}]}, {\"title\": {\"ar\": \"المشاريع والمهام والإنتاجية\", \"en\": \"Projects, Tasks & Productivity\"}, \"points\": [{\"ar\": \"مشاريع ومراحل ومهام ومهام فرعية وأخطاء وتقارير\", \"en\": \"Manage projects, stages, tasks, subtasks, bugs, and reports.\"}, {\"ar\": \"قوالب مشاريع ونسخ المشاريع المتكررة\", \"en\": \"Reuse project templates and duplicate projects.\"}, {\"ar\": \"سجلات وقت وجداول ساعات العمل وأعباء الفريق\", \"en\": \"Track time, timesheets, and team workload.\"}, {\"ar\": \"جداول مناوبات وتوافر الموظفين وإجازاتهم\", \"en\": \"Plan rotas, staff availability, and leave.\"}, {\"ar\": \"قوائم مهام مع عرض لوحة وتقويم وتقارير\", \"en\": \"Manage to-do lists with board, calendar, and reports.\"}, {\"ar\": \"ملاحظات وأهداف وتنبيهات وتذكيرات\", \"en\": \"Manage notes, goals, alerts, and reminders.\"}]}, {\"title\": {\"ar\": \"المستندات والتواصل والأتمتة\", \"en\": \"Documents, Communication & Automation\"}, \"points\": [{\"ar\": \"مستندات وتصنيفاتها وحالاتها وقوالبها ونسخها\", \"en\": \"Manage documents, types, statuses, templates, and duplicates.\"}, {\"ar\": \"مشاركة ملفات بروابط تنزيل وحماية بكلمة مرور\", \"en\": \"Share files with download links and password protection.\"}, {\"ar\": \"نماذج مخصصة مع حقول واستجابات قابلة للتصدير\", \"en\": \"Build custom forms and export their responses.\"}, {\"ar\": \"حقول مخصصة للوحدات وسير عمل آلي مرتبط بالأحداث\", \"en\": \"Add custom fields and event based workflows.\"}, {\"ar\": \"صندوق بريد ومكالمات وتذاكر دعم فني وملاحظاتها\", \"en\": \"Use mailbox, call management, and helpdesk tickets with notes.\"}, {\"ar\": \"قوالب رسائل SMS وWhatsApp وإعدادات الإرسال\", \"en\": \"Configure SMS and WhatsApp messaging.\"}, {\"ar\": \"محادثات ومساعد وصور ومستندات بأدوات الذكاء الاصطناعي\", \"en\": \"Use AI chat, assistant, image, and document tools.\"}, {\"ar\": \"سجل نشاط المستخدمين ونسخ احتياطي واستعادة\", \"en\": \"Review activity logs and manage backup and restore.\"}]}, {\"title\": {\"ar\": \"الواجهة والتسويق\", \"en\": \"Website & Marketing\"}, \"points\": [{\"ar\": \"تخصيص الصفحة التعريفية وأقسامها ومميزاتها وصورها\", \"en\": \"Customize landing page sections, features, and screenshots.\"}, {\"ar\": \"صفحات مخصصة وأسئلة شائعة ومراجعات وخطط أسعار\", \"en\": \"Publish custom pages, FAQs, reviews, and pricing plans.\"}, {\"ar\": \"نماذج طلبات واستفسارات وربطها بالواجهة\", \"en\": \"Collect requests and inquiries through website forms.\"}, {\"ar\": \"بطاقات أعمال رقمية مع قوالب ومواعيد ونطاقات\", \"en\": \"Create digital business cards with themes, appointments, and domains.\"}, {\"ar\": \"إعدادات SEO والخطوط والكوكيز وقائمة جانبية قابلة للتخصيص\", \"en\": \"Configure SEO, fonts, cookie notice, and sidebar menus.\"}]}, {\"title\": {\"ar\": \"التقارير والتصدير والتكاملات\", \"en\": \"Reports, Exports & Integrations\"}, \"points\": [{\"ar\": \"تصدير بيانات وتقارير متعددة إلى Excel وPDF\", \"en\": \"Export many records and reports to Excel and PDF.\"}, {\"ar\": \"واجهات API للوظائف المدعومة وتوثيق API داخل النظام\", \"en\": \"Access supported APIs and their in-app documentation.\"}, {\"ar\": \"ربط ZATCA للفوترة الإلكترونية السعودية\", \"en\": \"Integrate Saudi electronic invoicing through ZATCA.\"}, {\"ar\": \"بوابات دفع Stripe وPayPal وتحويل بنكي\", \"en\": \"Accept payments through Stripe, PayPal, and bank transfer.\"}, {\"ar\": \"حضور بالبصمة مع مزامنة بيانات الجهاز\", \"en\": \"Sync biometric attendance records.\"}]}, {\"title\": {\"ar\": \"إدارة الأصول\", \"en\": \"Assets\"}, \"points\": [{\"ar\": \"تسجيل الأصول وتصنيفاتها ومجموعاتها وتاريخها\", \"en\": \"Record assets, categories, groups, and history.\"}, {\"ar\": \"تسليم الأصول وسحبها ومتابعة حالتها\", \"en\": \"Distribute, withdraw, and track asset status.\"}]}, {\"title\": {\"ar\": \"الموازنات\", \"en\": \"Budget Planner\"}, \"points\": [{\"ar\": \"إنشاء موازنات ومتابعة بنودها\", \"en\": \"Create budgets and track their items.\"}]}, {\"title\": {\"ar\": \"السيارات والمعارض\", \"en\": \"Car Dealership\"}, \"points\": [{\"ar\": \"إدارة السيارات والموديلات والماركات والفئات والتجهيزات\", \"en\": \"Manage cars, models, brands, categories, and variants.\"}, {\"ar\": \"مبيعات السيارات ومدفوعاتها ومشترياتها\", \"en\": \"Record car sales, payments, and purchases.\"}, {\"ar\": \"تجارب القيادة والخدمات والضمان والتأمين\", \"en\": \"Manage test drives, services, warranties, and insurance.\"}]}, {\"title\": {\"ar\": \"خدمات التنظيف\", \"en\": \"Cleaning Management\"}, \"points\": [{\"ar\": \"فرق تنظيف وحجوزات العملاء\", \"en\": \"Manage cleaning teams and customer bookings.\"}, {\"ar\": \"مراجعة الحجوزات والموافقة أو الرفض\", \"en\": \"Review, approve, or reject bookings.\"}]}, {\"title\": {\"ar\": \"الصيانة الوقائية وأوامر العمل\", \"en\": \"CMMS\"}, \"points\": [{\"ar\": \"طلبات وأوامر صيانة وقطع غيار ومكونات ومواقع\", \"en\": \"Manage maintenance requests, work orders, parts, components, and locations.\"}, {\"ar\": \"خطط صيانة وقائية وسجلات عمل وفواتير\", \"en\": \"Plan preventive maintenance and track work logs and invoices.\"}, {\"ar\": \"رموز QR لطلبات العمل\", \"en\": \"Use QR codes for work requests.\"}]}, {\"title\": {\"ar\": \"البضاعة بنظام الأمانة\", \"en\": \"Consignment Management\"}, \"points\": [{\"ar\": \"إدارة أصناف الأمانة وعملياتها\", \"en\": \"Manage consignment products and transactions.\"}, {\"ar\": \"أوامر شراء وبيع مرتبطة بالأمانات\", \"en\": \"Create consignment purchase and sales orders.\"}]}, {\"title\": {\"ar\": \"العقود والقوالب\", \"en\": \"Contracts & Templates\"}, \"points\": [{\"ar\": \"أنواع عقود وعقود قابلة للمتابعة والطباعة\", \"en\": \"Manage contract types and contracts.\"}, {\"ar\": \"قوالب عقود قابلة للنسخ وتحويلها إلى PDF\", \"en\": \"Duplicate contract templates and export them to PDF.\"}]}, {\"title\": {\"ar\": \"خدمات الشحن والتوصيل\", \"en\": \"Courier Management\"}, \"points\": [{\"ar\": \"تسجيل شحنات وشركات أو مندوبي التوصيل\", \"en\": \"Register shipments and courier details.\"}, {\"ar\": \"متابعة الشحنة برقم التتبع\", \"en\": \"Track shipments by tracking number.\"}]}, {\"title\": {\"ar\": \"مدرسة القيادة\", \"en\": \"Driving School\"}, \"points\": [{\"ar\": \"إدارة الطلاب والمركبات والفصول والدروس\", \"en\": \"Manage students, vehicles, classes, and lessons.\"}, {\"ar\": \"اختبارات ورخص وفواتير وتقارير تقدم\", \"en\": \"Track tests, licenses, invoices, and progress reports.\"}]}, {\"title\": {\"ar\": \"حجز المرافق\", \"en\": \"Facilities\"}, \"points\": [{\"ar\": \"إدارة الخدمات والمساحات وساعات العمل\", \"en\": \"Manage facilities, services, spaces, and working hours.\"}, {\"ar\": \"حجوزات المرافق وطلبات الحجز\", \"en\": \"Handle facility bookings and orders.\"}]}, {\"title\": {\"ar\": \"إصلاح المعدات\", \"en\": \"Fix Equipment\"}, \"points\": [{\"ar\": \"تسجيل المعدات وطلبات إصلاحها ومتابعة حالتها\", \"en\": \"Record equipment repair jobs and track their status.\"}]}, {\"title\": {\"ar\": \"الأسطول والمركبات\", \"en\": \"Fleet\"}, \"points\": [{\"ar\": \"إدارة المركبات والسائقين والرخص والتأمين والوقود\", \"en\": \"Manage vehicles, drivers, licenses, insurance, and fuel.\"}, {\"ar\": \"حجوزات المركبات والوجهات وتسليمها واستلامها\", \"en\": \"Manage vehicle bookings, destinations, and handovers.\"}, {\"ar\": \"الصيانة والمصروفات والفواتير وعروض الأسعار\", \"en\": \"Track maintenance, expenses, invoices, and quotations.\"}, {\"ar\": \"تقارير المركبات والسائقين والتأمين والوقود والحجوزات\", \"en\": \"View vehicle, driver, insurance, fuel, and booking reports.\"}]}, {\"title\": {\"ar\": \"الشحن الدولي والتخليص\", \"en\": \"Freight Management\"}, \"points\": [{\"ar\": \"شحنات وحاويات وموانئ ومناشئ ووكلاء وساحات\", \"en\": \"Manage shipments, containers, ports, origins, agents, and yards.\"}, {\"ar\": \"طلبات حجز وإشعارات وصول وتخليص ومستندات\", \"en\": \"Handle booking requests, arrival notices, clearance, and paperwork.\"}, {\"ar\": \"عروض أسعار وفواتير شحن ومردوداتها ومدفوعاتها\", \"en\": \"Manage freight quotations, invoices, returns, and payments.\"}, {\"ar\": \"حالات الشحن وخدماته ومصاريفه\", \"en\": \"Track shipping statuses, services, and expenses.\"}]}, {\"title\": {\"ar\": \"صالات الألعاب\", \"en\": \"Game Zone\"}, \"points\": [{\"ar\": \"ألعاب ومناطق لعب ولاعبون وحجوزات\", \"en\": \"Manage games, zones, players, and rentals.\"}, {\"ar\": \"عضويات وخطط وكوبونات ومدفوعات واستردادات\", \"en\": \"Manage memberships, plans, coupons, payments, and refunds.\"}, {\"ar\": \"أطعمة وطلبات بيع داخل الصالة\", \"en\": \"Sell food and manage orders.\"}]}, {\"title\": {\"ar\": \"مراكز صيانة السيارات\", \"en\": \"Garage Management\"}, \"points\": [{\"ar\": \"بيانات المركبات وأنواعها وماركاتها وخدماتها\", \"en\": \"Manage vehicles, types, brands, and services.\"}, {\"ar\": \"كروت أعمال الصيانة وقطع العمل\", \"en\": \"Create garage job cards and track repair work.\"}]}, {\"title\": {\"ar\": \"الفنادق والحجوزات\", \"en\": \"Hotels & Holidayz\"}, \"points\": [{\"ar\": \"فنادق وغرف وخدمات ومرافق ومميزات للغرف\", \"en\": \"Manage hotels, rooms, services, facilities, and room features.\"}, {\"ar\": \"عملاء وحجوزات غرف وكوبونات ودفع بتحويل بنكي\", \"en\": \"Manage guests, room bookings, coupons, and bank transfer payments.\"}, {\"ar\": \"صفحات تعريفية مخصصة للفنادق\", \"en\": \"Publish custom hotel pages.\"}]}, {\"title\": {\"ar\": \"المستشفيات\", \"en\": \"Hospital Management\"}, \"points\": [{\"ar\": \"مرضى وأطباء وتخصصات وأجنحة وأسرة ومواعيد\", \"en\": \"Manage patients, doctors, specialties, wards, beds, and appointments.\"}, {\"ar\": \"سجلات طبية وأدوية وتحاليل وجراحات\", \"en\": \"Maintain medical records, medicines, tests, and surgeries.\"}, {\"ar\": \"طوارئ وإسعاف وزيارات ومرضى خارجيون\", \"en\": \"Handle emergencies, ambulances, visitors, and outpatients.\"}]}, {\"title\": {\"ar\": \"البحث عن وظائف\", \"en\": \"Job Search\"}, \"points\": [{\"ar\": \"عرض الوظائف للباحثين عنها والتقديم الإلكتروني\", \"en\": \"Publish jobs and accept online applications.\"}, {\"ar\": \"إدارة طلبات التوظيف ومتابعة المتقدمين\", \"en\": \"Manage job applications and applicants.\"}]}, {\"title\": {\"ar\": \"القضايا والاستشارات القانونية\", \"en\": \"Legal Case Management\"}, \"points\": [{\"ar\": \"قضايا ومحاكم ومحامون وتصنيفات وحالات ومراحل\", \"en\": \"Manage cases, courts, advocates, categories, statuses, and levels.\"}, {\"ar\": \"استشارات قانونية ومصاريف القضايا والأتعاب المحصلة\", \"en\": \"Track consultations, case expenses, and received fees.\"}, {\"ar\": \"تقارير قانونية ومتابعة تفاصيل القضايا\", \"en\": \"Generate legal reports and follow case details.\"}]}, {\"title\": {\"ar\": \"المعامل الطبية\", \"en\": \"Medical Lab Management\"}, \"points\": [{\"ar\": \"مرضى ومواعيد وطلبات فحوصات ونتائجها\", \"en\": \"Manage patients, appointments, test requests, and results.\"}, {\"ar\": \"وحدات الاختبار والمحتوى ومخزون المعمل والفواتير\", \"en\": \"Manage test units, content, inventory, and billing.\"}, {\"ar\": \"بطاقات المرضى وتاريخهم وتقارير النتائج\", \"en\": \"View patient cards, histories, and result reports.\"}]}, {\"title\": {\"ar\": \"الصيدليات\", \"en\": \"Pharmacy Management\"}, \"points\": [{\"ar\": \"أدوية وتصنيفات وأنواع ومخزون\", \"en\": \"Manage medicines, categories, types, and stock.\"}, {\"ar\": \"فواتير بيع وشراء ومرتجعات وخصومات\", \"en\": \"Manage sales, purchase bills, returns, and discounts.\"}, {\"ar\": \"تسجيل تصنيع الأدوية وتقارير الصيدلية\", \"en\": \"Record medicine manufacturing and view pharmacy dashboard.\"}]}, {\"title\": {\"ar\": \"إدارة العقارات\", \"en\": \"Property Management\"}, \"points\": [{\"ar\": \"عقارات ووحدات ومستأجرون وتصنيفاتهم\", \"en\": \"Manage properties, units, tenants, and categories.\"}, {\"ar\": \"عروض ومقترحات وإعلانات العقارات\", \"en\": \"Create property quotations, proposals, and listings.\"}, {\"ar\": \"عقود تأجير وصيانة ومصروفات ومستندات\", \"en\": \"Track rentals, maintenance requests, expenses, and documents.\"}, {\"ar\": \"فواتير عقارية ومدفوعاتها وإشعاراتها الدائنة واسترداداتها\", \"en\": \"Manage property invoices, payments, credit notes, and refunds.\"}]}, {\"title\": {\"ar\": \"تنظيم الطوابير\", \"en\": \"Queue Management\"}, \"points\": [{\"ar\": \"خدمات وشبابيك وتذاكر انتظار\", \"en\": \"Set up services, counters, and queue tickets.\"}, {\"ar\": \"استدعاء العملاء وقياس أوقات الخدمة\", \"en\": \"Call customers and track service times.\"}]}, {\"title\": {\"ar\": \"الحجوزات والتأجير\", \"en\": \"Rental Management\"}, \"points\": [{\"ar\": \"إدارة عمليات التأجير وعناصرها وحالاتها\", \"en\": \"Manage rentals, line items, and statuses.\"}, {\"ar\": \"إعدادات التأجير وعرض الشبكة\", \"en\": \"Configure rental settings and grid view.\"}]}, {\"title\": {\"ar\": \"تأجير المخازن\", \"en\": \"Rental Warehouse\"}, \"points\": [{\"ar\": \"مخازن مؤجرة وتصنيفات وطلبات تأجير\", \"en\": \"Manage rental warehouses, categories, and orders.\"}, {\"ar\": \"أصناف الطلبات وحالاتها وتسويات المخزن\", \"en\": \"Track order items, statuses, and warehouse adjustments.\"}]}, {\"title\": {\"ar\": \"طلبات الإصلاح\", \"en\": \"Repair Management\"}, \"points\": [{\"ar\": \"طلبات إصلاح ومراحل تنفيذ وسجل حركة\", \"en\": \"Manage repair requests, work stages, and movement history.\"}, {\"ar\": \"قطع غيار مرتبطة بأوامر الإصلاح\", \"en\": \"Add repair parts to work orders.\"}]}, {\"title\": {\"ar\": \"طلبات العملاء\", \"en\": \"Requests\"}, \"points\": [{\"ar\": \"نماذج طلبات بفئات وفئات فرعية وحقول مخصصة\", \"en\": \"Build request forms with categories, subcategories, and custom fields.\"}, {\"ar\": \"استقبال الطلبات والرد عليها\", \"en\": \"Receive requests and manage responses.\"}]}, {\"title\": {\"ar\": \"الدفعات المقدمة\", \"en\": \"Retainer\"}, \"points\": [{\"ar\": \"إنشاء مستندات الدفعات المقدمة وإرسالها ونسخها\", \"en\": \"Create, send, and duplicate retainer documents.\"}, {\"ar\": \"متابعة حالة الدفعة وعناصرها\", \"en\": \"Track retainer status and items.\"}]}, {\"title\": {\"ar\": \"الأندية والأكاديميات الرياضية\", \"en\": \"Sports Club & Academy\"}, \"points\": [{\"ar\": \"ملاعب وأندية ومرافق وحجوزات واعتماداتها\", \"en\": \"Manage grounds, clubs, facilities, and booking approvals.\"}, {\"ar\": \"أعضاء واشتراكات وخطط تدريب ومدربون\", \"en\": \"Manage members, membership plans, and coaches.\"}, {\"ar\": \"أنشطة وجلسات ومعدات وإيصالات واستردادات\", \"en\": \"Track activities, sessions, equipment, receipts, and refunds.\"}]}, {\"title\": {\"ar\": \"السياحة والسفر\", \"en\": \"Tour & Travel\"}, \"points\": [{\"ar\": \"رحلات ومواسم واستفسارات وحجوزات سياحية\", \"en\": \"Manage tours, seasons, inquiries, and bookings.\"}, {\"ar\": \"مرشدون ووسائل نقل وعروض وتغطية تأمينية\", \"en\": \"Manage guides, transport, promotions, and travel insurance.\"}]}, {\"title\": {\"ar\": \"فواتير الرحلات والأسطول\", \"en\": \"Trip & Fleet Invoicing\"}, \"points\": [{\"ar\": \"فواتير مرتبطة بالأسطول مع حالات ومدفوعات ومرفقات\", \"en\": \"Manage fleet invoices with statuses, payments, and attachments.\"}, {\"ar\": \"إرسال الفواتير وتذكير العملاء وتصدير PDF وExcel\", \"en\": \"Send invoices and reminders and export PDF or Excel.\"}, {\"ar\": \"مرتجعات فواتير الأسطول واسترداداتها وتقاريرها\", \"en\": \"Manage fleet invoice returns, refunds, and reports.\"}]}, {\"title\": {\"ar\": \"حجز المركبات وخطوط السير\", \"en\": \"Vehicle Booking\"}, \"points\": [{\"ar\": \"حجوزات مركبات وخطوط سير ولوحة متابعة\", \"en\": \"Manage vehicle bookings, routes, and dashboard.\"}]}, {\"title\": {\"ar\": \"فحص المركبات\", \"en\": \"Vehicle Inspection\"}, \"points\": [{\"ar\": \"نماذج فحص وطلبات فحص وقوائم متابعة\", \"en\": \"Manage inspection forms, requests, and checklists.\"}, {\"ar\": \"إرسال نتائج الفحص وربطها ببيانات المركبة\", \"en\": \"Send inspection results linked to vehicle data.\"}]}, {\"title\": {\"ar\": \"الزوار\", \"en\": \"Visitor Management\"}, \"points\": [{\"ar\": \"تسجيل الزوار وأسباب الزيارة والدخول والخروج\", \"en\": \"Register visitors, visit reasons, check-ins, and departures.\"}, {\"ar\": \"تسجيل مسبق وبطاقات زوار ومستندات\", \"en\": \"Handle preregistration, visitor badges, and documents.\"}, {\"ar\": \"حوادث وامتثال وإخلاء طوارئ وتقارير زيارات\", \"en\": \"Track incidents, compliance, emergency evacuation, and reports.\"}]}, {\"title\": {\"ar\": \"وحدات مساندة إضافية\", \"en\": \"Additional Supporting Modules\"}, \"points\": [{\"ar\": \"محرر جداول وملفات داخل النظام\", \"en\": \"Create and edit spreadsheets and files in the system.\"}, {\"ar\": \"منشئ قوائم جانبية مخصصة وروابط داخلية\", \"en\": \"Build custom side menus and embedded links.\"}, {\"ar\": \"إنشاء صور ومحتوى ومستندات بمساعدة الذكاء الاصطناعي\", \"en\": \"Generate images, content, and documents with AI tools.\"}, {\"ar\": \"تكرار الفواتير وفواتير الموردين وفق إعدادات التكرار\", \"en\": \"Configure recurring invoices and bills.\"}, {\"ar\": \"قوالب مستندات وتقارير أنشطة وتذكيرات\", \"en\": \"Use document templates, activity reports, and reminders.\"}]}]', NULL, NULL, NULL, 41, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-06 08:36:34', '2026-09-30 15:09:40', NULL),
(25, '{\"ar\":\"استشاري\",\"en\":\"Asteshary\"}', 'asteshary', NULL, NULL, NULL, 'web', '{\"ar\":\"لوحة تحكم طبية لإدارة العيادات والأطباء والمرضى والمواعيد والفواتير والإعلانات وتشغيل المنصة مع APIs لتطبيقات الموبايل.\",\"en\":\"A healthcare admin dashboard for managing clinics, doctors, patients, appointments, billing, ads, and platform operations with APIs for mobile apps.\"}', '{\"ar\":\"Asteshary Admin Dashboard لوحة تحكم مركزية لمنصة حجز طبي. بتمكّن فريق التشغيل من إدارة المنشآت الطبية (عيادات\\/مستشفيات)، الأطباء، المرضى، الحجوزات، التقييمات، الحسابات المالية، الإعلانات، الكورسات، الوظائف، والدعم الفني من مكان واحد.\\r\\n وتوفر APIs للتطبيقات، إشعارات Push، صلاحيات حسب الأدوار، وتقارير تشغيلية.\",\"en\":\"Asteshary Admin Dashboard is a centralized control panel for a medical booking platform. It helps the operations team manage medical enterprises (clinics\\/hospitals), doctors, patients, reservations, reviews, finances, marketing ads, courses, jobs, and support tickets from one place.\\r\\nit also exposes APIs for mobile apps, push notifications, role-based access, and reporting.\"}', '{\"ar\":\"منصات الرعاية الصحية غالبًا بتشتغل بشكل متفرق: العيادات والأطباء والمواعيد كل واحد لوحده، متابعة الحضور والإلغاء صعبة، طلبات انضمام الأطباء والتقييمات محتاجة مراجعة، الفوترة يدوية، والإعلانات بدون تحكم مركزي. النتيجة: ضياع وقت وضعف في الرؤية والتحكم.\",\"en\":\"Healthcare platforms often struggle with fragmented operations: clinics, doctors, and appointments are managed separately; booking confirmation and attendance are hard to track; reviews and doctor applications need moderation; invoicing is manual; and marketing\\/ads lack centralized control. Without one admin system, teams waste time and lose visibility.\"}', '{\"ar\":\"عملنا لوحة أدمن كاملة بتجمع تشغيل المنصة: إدارة المنشآت والفروع، قبول\\/إدارة الأطباء، جدولة المواعيد، تأكيد الحضور، مراجعة التقييمات، إصدار الفواتير، إدارة الإعلانات، ومتابعة الدعم مع APIs تربط تجربة المريض والطبيب على الموبايل بنفس البيانات.\",\"en\":\"We built a full admin dashboard that unifies the platform’s operations: manage enterprises and branches, onboard\\/approve doctors, schedule appointments, track attendance, moderate reviews, generate invoices, run ads, and handle support plus APIs so the patient\\/doctor mobile experience stays in sync.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المنشآت والفروع\", \"en\": \"Enterprise & Branch Management\"}, \"points\": [{\"ar\": \"إنشاء وإدارة العيادات/المستشفيات\", \"en\": \"Create and manage clinics/hospitals (enterprises)\"}, {\"ar\": \"دعم فروع متعددة لكل منشأة\", \"en\": \"Multi-branch support per enterprise\"}, {\"ar\": \"جداول العمل، إظهار/إيقاف المنشأة، وإدارة الملفات والصور\", \"en\": \"Working schedules, visibility controls (hide/stop), and media files\"}]}, {\"title\": {\"ar\": \"إدارة الأطباء\", \"en\": \"Doctors Management\"}, \"points\": [{\"ar\": \"ملفات الأطباء والتخصصات وربطهم بالمنشآت\", \"en\": \"Doctor profiles, specializations, and enterprise linking\"}, {\"ar\": \"الجداول، المواعيد، الإجازات، والترتيب/الـ Ranking\", \"en\": \"Schedules, appointments, vacations, and ranking\"}, {\"ar\": \"قبول أو رفض طلبات الانضمام وتسجيلات التطبيق\", \"en\": \"Approve/decline doctor applications and app registrations\"}, {\"ar\": \"فيديوهات الطبيب وإعدادات التفضيلات\", \"en\": \"Doctor videos and preference settings\"}]}, {\"title\": {\"ar\": \"المرضى والحجوزات\", \"en\": \"Patients & Reservations\"}, \"points\": [{\"ar\": \"ملفات المرضى وسجلاتهم\", \"en\": \"Patient profiles and history\"}, {\"ar\": \"إنشاء وتعديل وفلترة ومتابعة الحجوزات\", \"en\": \"Create, edit, filter, and track reservations\"}, {\"ar\": \"تأكيد الحضور، الإلغاء، وإعادة الجدولة\", \"en\": \"Attendance confirmation, cancellation, and rescheduling\"}, {\"ar\": \"رفع الروشتات ومتابعة حالات الحجز\", \"en\": \"Prescription upload and reservation status workflow\"}, {\"ar\": \"تقارير الحجوزات والمرضى\", \"en\": \"Reservation and patient reports\"}]}, {\"title\": {\"ar\": \"التقييمات وضبط الجودة\", \"en\": \"Reviews & Quality Control\"}, \"points\": [{\"ar\": \"عرض ومراجعة التقييمات (قبول/إخفاء/حذف)\", \"en\": \"Review listing and moderation (accept/hide/delete)\"}, {\"ar\": \"قائمة التقييمات المعلّقة وفلترة حسب المنشأة/الطبيب/المريض\", \"en\": \"Pending review queue and filtering by enterprise/doctor/patient\"}]}, {\"title\": {\"ar\": \"الإدارة المالية\", \"en\": \"Financial Management\"}, \"points\": [{\"ar\": \"إعدادات مالية وإصدار فواتير لكل منشأة\", \"en\": \"Financial settings and invoice generation per enterprise\"}, {\"ar\": \"تفاصيل الفاتورة حسب الشهر/السنة/الطبيب\", \"en\": \"Invoice details by month/year/doctor\"}, {\"ar\": \"تحميل الفاتورة PDF\", \"en\": \"PDF invoice download\"}]}, {\"title\": {\"ar\": \"الإعلانات والتسويق\", \"en\": \"Ads & Marketing\"}, \"points\": [{\"ar\": \"إعلانات حسب المدينة والمنطقة\", \"en\": \"Ads by city and area\"}, {\"ar\": \"إدارة إعلانات Google والسوشيال والإعلانات المخصصة\", \"en\": \"Google, social, and custom ads management\"}, {\"ar\": \"إعدادات الإعلانات والملاحظات والتواريخ والحد الأدنى والتقارير\", \"en\": \"Ad settings, notes, dates, minimums, and reports\"}]}, {\"title\": {\"ar\": \"العمليات والكورسات والوظائف\", \"en\": \"Operations, Courses & Jobs\"}, \"points\": [{\"ar\": \"إدارة العمليات/الإجراءات الطبية وطلبات الحجز\", \"en\": \"Medical operations/procedures and booking requests\"}, {\"ar\": \"إدارة المستشفيات\", \"en\": \"Hospital management\"}, {\"ar\": \"الكورسات ومتابعة الاشتراكات\", \"en\": \"Courses and enrollment tracking\"}, {\"ar\": \"نشر الوظائف وتفعيل/إيقافها\", \"en\": \"Job posts with toggle activation\"}, {\"ar\": \"ملفات الشركات وسجل الإجراءات\", \"en\": \"Company profiles and action logs\"}]}, {\"title\": {\"ar\": \"إعدادات المنصة\", \"en\": \"Platform Settings\"}, \"points\": [{\"ar\": \"المدن والمناطق والتأمينات ومميزات الموقع\", \"en\": \"Cities, areas, insurances, location features\"}, {\"ar\": \"التخصصات والتخصصات الفرعية\", \"en\": \"Specializations and sub-specializations\"}, {\"ar\": \"الخدمات والأعراض والاستشاريين والأدوية\", \"en\": \"Services, symptoms, consultants, medicines\"}, {\"ar\": \"الخصومات وكوبونات الخصم\", \"en\": \"Services, symptoms, consultants, medicines\"}]}, {\"title\": {\"ar\": \"الإشعارات والدعم والأمان\", \"en\": \"Notifications, Support & Security\"}, \"points\": [{\"ar\": \"إشعارات Push (شاملة إشعارات المنشآت)\", \"en\": \"Push notifications (including enterprise notifications)\"}, {\"ar\": \"الدعم الفني ومتابعة الشكاوى/المشاكل\", \"en\": \"Technical support and problem/ticket handling\"}, {\"ar\": \"أدوار وصلاحيات لمستخدمي الأدمن\", \"en\": \"Roles & permissions for admin users\"}, {\"ar\": \"سجل نشاطات للمراجعة والتدقيق\", \"en\": \"Activity logs for auditability\"}, {\"ar\": \"REST APIs لتطبيقات الموبايل + تكامل Chatbot\", \"en\": \"REST APIs for mobile apps + chatbot integration\"}]}]', NULL, NULL, NULL, 19, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-07 03:46:08', '2026-09-07 04:02:15', NULL),
(26, '{\"ar\":\"ايزي ليست\",\"en\":\"EasyList\"}', 'easylist', NULL, NULL, NULL, 'web', '{\"ar\":\"EasyList منصة إدارية متكاملة لإدارة المستقلين والعملاء والطلبات والتقارير المالية والفرانشايز في مكان واحد.\",\"en\":\"EasyList is an all-in-one operations platform for managing freelancers, clients, orders, financial reports, and franchises in one place.\"}', '{\"ar\":\"EasyList نظام ويب مبني لإدارة عمليات الشركات العاملة بنموذج المستقلين والوكلاء. يوفّر لوحة تحكم شاملة لإدارة العملاء والمستقلين والطلبات والحوالات، مع نظام تسويق بالعمولة، وتقارير مالية حسب الأدوار، وإدارة فرانشايز، وصلاحيات مستخدمين، ومكتبة تعليمية  مع دعم كامل للغتين العربية والإنجليزية.\",\"en\":\"EasyList is a web system built for businesses that run on freelancers and sales agents. It provides a full admin dashboard to manage clients, freelancers, orders, and transfers with affiliate marketing, role-based financial reports, franchise management, user permissions, and an educational library fully supporting Arabic and English.\"}', '{\"ar\":\"الشركات اللي بتشتغل مع مستقلين ووكلاء مبيعات غالبًا بتواجه:\\r\\n\\r\\nتشتت بيانات العملاء والمستقلين بين ملفات وإكسل ودفاتر\\r\\nصعوبة متابعة الطلبات والحوالات والمستحقات\\r\\nغياب رؤية مالية واضحة لكل دور (مبيعات، موارد بشرية، مدير مالي، CEO)\\r\\nصعوبة تنظيم التسويق بالعمولة وشجرة إحالة العملاء\\r\\nضعف التحكم في الصلاحيات بين الفريق والفرانشايز\",\"en\":\"Companies working with freelancers and sales agents often struggle with:\\r\\n\\r\\nScattered client and freelancer data across Excel sheets and files\\r\\nHard-to-track orders, transfers, and dues\\r\\nNo clear financial visibility per role (Sales, HR, Finance, CEO)\\r\\nComplex affiliate marketing and client referral trees\\r\\nWeak access control across teams and franchise partners\"}', '{\"ar\":\"EasyList بيجمع كل العمليات في منصة واحدة: إدارة المستقلين والعملاء والطلبات، تتبع الحوالات، التسويق بالعمولة، التقارير المالية التفصيلية، الفرانشايز، الأدوار والصلاحيات، والجرد عشان القرار يبقى أسرع والتشغيل أوضح.\",\"en\":\"EasyList unifies operations in one platform: freelancers, clients, orders, transfers, affiliate marketing, detailed financial reporting, franchises, roles & permissions, and inventory so teams move faster with clearer visibility.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المستقلين\", \"en\": \"Freelancer Management\"}, \"points\": [{\"ar\": \"إضافة وإدارة المستقلين وطلبات الانضمام\", \"en\": \"Add and manage freelancers and join requests\"}, {\"ar\": \"تصنيف مجالات العمل (رئيسية وفرعية)\", \"en\": \"Main and sub work-field categorization\"}, {\"ar\": \"تقييم المستقلين ومتابعة الإجازات\", \"en\": \"Freelancer ratings and holiday tracking\"}, {\"ar\": \"استيراد وتصدير بيانات المستقلين\", \"en\": \"Import/export freelancer data\"}]}, {\"title\": {\"ar\": \"إدارة العملاء والطلبات\", \"en\": \"Clients & Orders\"}, \"points\": [{\"ar\": \"إدارة كاملة لبيانات العملاء\", \"en\": \"Full client data management\"}, {\"ar\": \"إنشاء ومتابعة الطلبات\", \"en\": \"Create and track orders\"}, {\"ar\": \"تسجيل الحوالات وبيانات التحويل مع إمكانية التحميل\", \"en\": \"Record transfers and transfer data with download support\"}]}, {\"title\": {\"ar\": \"التسويق بالعمولة\", \"en\": \"Affiliate Marketing\"}, \"points\": [{\"ar\": \"إسناد العملاء ومتابعة الإحالات\", \"en\": \"Client assignment and referral tracking\"}, {\"ar\": \"عرض شجرة العملاء\", \"en\": \"Client tree visualization\"}, {\"ar\": \"إعدادات نسب العمولة\", \"en\": \"Commission settings management\"}]}, {\"title\": {\"ar\": \"التقارير المالية والتحليلات\", \"en\": \"Financial Reports & Analytics\"}, \"points\": [{\"ar\": \"تقارير حسب الدور (مبيعات، موارد بشرية، مدير فني، مدير مالي، CEO)\", \"en\": \"Role-based reports (Sales, HR, Technical Director, Finance, CEO)\"}, {\"ar\": \"رسوم بيانية للإيرادات والمستحقات وصافي الربح\", \"en\": \"Charts for revenue, dues, and net profit\"}, {\"ar\": \"إدارة الميزانيات وتقارير الجرد\", \"en\": \"Budget management and inventory reports\"}]}, {\"title\": {\"ar\": \"إدارة الفرانشايز والصلاحيات\", \"en\": \"Franchise & Access Control\"}, \"points\": [{\"ar\": \"إضافة وإدارة الفرانشايز\", \"en\": \"Add and manage franchises\"}, {\"ar\": \"أدوار وصلاحيات دقيقة للفريق\", \"en\": \"Granular roles and permissions\"}, {\"ar\": \"إدارة المستخدمين والملفات الشخصية\", \"en\": \"User and profile management\"}]}, {\"title\": {\"ar\": \"المكتبة التعليمية وتجربة الاستخدام\", \"en\": \"Learning Hub & UX\"}, \"points\": [{\"ar\": \"مكتبة محتوى تعليمي للفريق\", \"en\": \"Educational content library for the team\"}, {\"ar\": \"دعم العربية والإنجليزية (RTL/LTR)\", \"en\": \"Arabic & English support (RTL/LTR)\"}, {\"ar\": \"لوحة تحكم ولوحات معلومات مركزية\", \"en\": \"Central dashboard and reporting views\"}]}]', NULL, NULL, NULL, 18, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-07 03:54:03', '2026-09-07 03:54:07', NULL),
(27, '{\"ar\":\"نظام محاسبة ومبيعات وإدارة مخزون\",\"en\":\"Accounting, Sales & Inventory Management System\"}', 'accounting-sales-inventory-management-system', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة موحدة لإدارة المبيعات والمشتريات ونقاط البيع والمخزون والعملاء والموردين، مع تقارير لمتابعة العمليات اليومية.\",\"en\":\"An integrated platform for managing sales, purchases, point-of-sale, inventory, customers, and suppliers, with reports for day-to-day operations.\"}', '{\"ar\":\"يجمع النظام العمليات اليومية في منصة واحدة، تشمل إدارة المنتجات والمخزون، وتنفيذ المبيعات عبر نقطة البيع، وتسجيل المشتريات وعروض الأسعار والمصروفات والإيرادات. كما يتيح إدارة بيانات العملاء والموردين والتحويلات والمرتجعات، ومراجعة التقارير التشغيلية؛ للحد من تشتت البيانات وتسهيل متابعة العمل.\",\"en\":\"This web-based system brings daily business operations together in one place. It supports product and inventory management, point-of-sale transactions, purchases, quotations, expenses, and income. Teams can also manage customer and supplier records, transfers, and returns, and review operational reports.\"}', '{\"ar\":\"كانت العمليات التجارية موزعة بين سجلات وأدوات متعددة، مما صعّب متابعة المخزون والمعاملات اليومية والوصول إلى صورة واضحة عن سير العمل\",\"en\":\"Business operations were spread across multiple records and tools, making it harder to track inventory, follow daily transactions, and maintain a clear view of operations.\"}', '{\"ar\":\"إنشاء نظام مركزي يربط عمليات البيع والشراء والمخزون وإدارة العملاء والموردين، ويعرض بيانات العمليات في تقارير تساعد على المتابعة اليومية.\",\"en\":\"A centralized system connecting sales, purchasing, inventory, and customer and supplier management, with operational reports to support day-to-day tracking.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"المبيعات ونقطة البيع\", \"en\": \"Sales & Point of Sale\"}, \"points\": [{\"ar\": \"إدارة معاملات البيع من نقطة البيع\", \"en\": \"Process sales through the POS\"}, {\"ar\": \"إنشاء عروض الأسعار ومتابعة المرتجعات\", \"en\": \"Manage quotations and returns\"}]}, {\"title\": {\"ar\": \"المخزون والمشتريات\", \"en\": \"Inventory & Purchasing\"}, \"points\": [{\"ar\": \"تنظيم المنتجات ومتابعة المخزون\", \"en\": \"Organize products and track inventory\"}, {\"ar\": \"تسجيل المشتريات وإدارة التحويلات بين المستودعات\", \"en\": \"Record purchases and manage warehouse transfers\"}]}, {\"title\": {\"ar\": \"إدارة العمليات والتقارير\", \"en\": \"Operations & Reporting\"}, \"points\": [{\"ar\": \"إدارة بيانات العملاء والموردين\", \"en\": \"Manage customer and supplier records\"}, {\"ar\": \"تسجيل المصروفات والإيرادات ومراجعة التقارير\", \"en\": \"Record expenses and income, and review reports\"}]}]', NULL, NULL, NULL, 36, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-29 15:47:34', '2026-09-29 15:47:37', NULL),
(28, '{\"ar\":\"منصة تجارة إلكترونية متكاملة\",\"en\":\"Ecommerce Platform\"}', 'ecommerce-platform', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة تجارة إلكترونية لإدارة المتجر والمنتجات والطلبات والبائعين من خلال واجهة متجاوبة تدعم العربية والإنجليزية.\",\"en\":\"A full-featured e-commerce platform for managing storefronts, products, orders, and sellers, with a responsive interface and Arabic-English support.\"}', '{\"ar\":\"طوّرنا منصة تجارة إلكترونية تجمع تجربة التسوق وإدارة العمليات في نظام واحد. تتيح المنصة عرض المنتجات وتصنيفها، وإتمام الطلبات، وإدارة البائعين والمخزون والمحتوى من لوحة تحكم. كما تدعم اتجاهي العرض RTL وLTR، مع وحدات للعروض الترويجية وتتبع الطلبات وخيارات الدفع والتوصيل القابلة للتهيئة.\",\"en\":\"We built an e-commerce platform that brings the shopping experience and business operations together in one system. It supports product catalogs and categories, checkout, seller and inventory management, and content administration through a central dashboard. The platform supports both RTL and LTR layouts, with configurable modules for promotions, order tracking, payments, and delivery.\"}', '{\"ar\":\"احتاج المشروع إلى تنظيم عمليات البيع وإدارة المنتجات والطلبات والبائعين ضمن منصة واحدة، مع الحفاظ على تجربة استخدام مناسبة للأسواق متعددة اللغات واحتياجات المتاجر المختلفة.\",\"en\":\"The project needed to bring sales operations, product and order management, and seller workflows into one platform while supporting multilingual experiences and the varying needs of online stores.\"}', '{\"ar\":\"بنينا منصة مرنة تضم واجهة للمتسوقين ولوحات لإدارة المتجر والبائعين. أضفنا أدوات لإدارة المنتجات والطلبات والعروض، مع دعم العربية والإنجليزية وإمكانية تهيئة وحدات الدفع والتوصيل حسب إعدادات النشاط التجاري.\",\"en\":\"We built a flexible platform with a customer-facing storefront and management dashboards for store operators and sellers. It includes tools for products, orders, and promotions, with Arabic-English support and configurable payment and delivery modules.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة المتجر\", \"en\": \"Store Management\"}, \"points\": [{\"ar\": \"إدارة المنتجات والتصنيفات\", \"en\": \"Product and category management\"}, {\"ar\": \"سلة تسوق وإتمام الطلب\", \"en\": \"Shopping cart and checkout\"}, {\"ar\": \"إدارة الطلبات وتتبعها\", \"en\": \"Order management and tracking\"}]}, {\"title\": {\"ar\": \"أدوات البيع\", \"en\": \"Sales Tools\"}, \"points\": [{\"ar\": \"العروض والصفقات الترويجية\", \"en\": \"Promotions and flash deals\"}, {\"ar\": \"الكوبونات والخصومات\", \"en\": \"Coupons and discounts\"}, {\"ar\": \"تقييمات المنتجات وتفاعل العملاء\", \"en\": \"Product reviews and customer engagement\"}]}, {\"title\": {\"ar\": \"الإدارة والتوسع\", \"en\": \"Administration & Growth\"}, \"points\": [{\"ar\": \"لوحات تحكم للإدارة والبائعين\", \"en\": \"Admin and seller dashboards\"}, {\"ar\": \"واجهة متجاوبة تدعم العربية والإنجليزية\", \"en\": \"Responsive Arabic and English interface\"}, {\"ar\": \"وحدات قابلة للتهيئة للدفع والتوصيل\", \"en\": \"Configurable payment and delivery modules\"}]}]', NULL, NULL, NULL, 37, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-30 08:33:23', '2026-09-30 08:33:29', NULL);
INSERT INTO `projects` (`id`, `title`, `slug`, `client_name`, `industry`, `year`, `project_type`, `short_description`, `description`, `challenge`, `solution`, `approach`, `design_notes`, `development_notes`, `key_features`, `results`, `timeline`, `featured_image_id`, `cover_image_id`, `live_url`, `video_url`, `github_url`, `completion_date`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(29, '{\"ar\":\"منصة طلب وتوصيل الطعام\",\"en\":\"Food Ordering and Delivery Platform\"}', 'food-ordering-and-delivery-platform', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة لإدارة طلبات الطعام تربط العملاء بالمطاعم ومندوبي التوصيل من خلال لوحة تحكم مركزية.\",\"en\":\"A food ordering platform connecting customers, restaurants, and delivery drivers through a central management dashboard.\"}', '{\"ar\":\"يتيح ريمبيريو إدارة المطاعم وقوائم الطعام والطلبات ومناطق الخدمة ومندوبي التوصيل من مكان واحد. وتعرض لوحة الإدارة إحصاءات الطلبات والأداء، مع أدوات لإدارة العروض والتقييمات ومتابعة مراحل الطلب حتى التسليم.\",\"en\":\"Rimberio brings restaurant, menu, order, service zone, and delivery management into one platform. Its admin dashboard shows order and performance statistics, with tools for promotions, reviews, and tracking each order through delivery.\"}', '{\"ar\":\"تنسيق الطلبات بين العملاء والمطاعم ومندوبي التوصيل، مع متابعة حالات الطلب ومناطق الخدمة والأداء التشغيلي في نظام واحد.\",\"en\":\"Coordinating customers, restaurants, and delivery drivers while keeping order status, service zones, and operational performance visible in one system.\"}', '{\"ar\":\"لوحة إدارة موحدة لتنظيم المطاعم والمنتجات والطلبات والتوصيل، مع إحصاءات حسب المنطقة وأدوات للعروض والتقييمات.\",\"en\":\"A unified dashboard for managing restaurants, products, orders, and delivery, with statistics by service zone and tools for promotions and reviews.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"إدارة الطلبات\", \"en\": \"Order Management\"}, \"points\": [{\"ar\": \"متابعة الطلبات حسب حالتها\", \"en\": \"Track orders by status\"}, {\"ar\": \"إدارة الطلبات المجدولة\", \"en\": \"Manage scheduled orders\"}, {\"ar\": \"متابعة الإلغاء والاسترداد\", \"en\": \"Monitor cancellations and refunds\"}]}, {\"title\": {\"ar\": \"إدارة المطاعم والقوائم\", \"en\": \"Restaurant and Menu Management\"}, \"points\": [{\"ar\": \"إدارة المطاعم\", \"en\": \"Manage restaurants\"}, {\"ar\": \"إضافة الأصناف وتعديلها\", \"en\": \"Add and update menu items\"}, {\"ar\": \"تنظيم الفئات والإضافات\", \"en\": \"Organize categories and add-ons\"}]}, {\"title\": {\"ar\": \"التوصيل ومناطق الخدمة\", \"en\": \"Delivery and Service Zones\"}, \"points\": [{\"ar\": \"إدارة مندوبي التوصيل\", \"en\": \"Manage delivery drivers\"}, {\"ar\": \"تحديد مناطق الخدمة\", \"en\": \"Configure service zones\"}, {\"ar\": \"متابعة الطلب حتى التسليم\", \"en\": \"Track orders through delivery\"}]}, {\"title\": {\"ar\": \"التحليلات والتسويق\", \"en\": \"Analytics and Promotions\"}, \"points\": [{\"ar\": \"إحصاءات الطلبات والأداء\", \"en\": \"View order and performance statistics\"}, {\"ar\": \"إدارة الكوبونات والحملات\", \"en\": \"Manage coupons and campaigns\"}, {\"ar\": \"متابعة التقييمات\", \"en\": \"Monitor reviews\"}]}]', NULL, NULL, NULL, 38, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-30 09:57:51', '2026-09-30 14:44:04', NULL),
(30, '{\"ar\":\"منصة تعليم إلكتروني وإدارة دورات متكاملة\",\"en\":\"Online Learning and Course Management Platform\"}', 'online-learning-and-course-management-platform', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة تعليم إلكتروني تجمع الدورات المباشرة والمسجلة، إدارة الطلاب والمدربين، الاختبارات والشهادات، والمدفوعات في نظام واحد.\",\"en\":\"An e-learning platform bringing live and recorded courses, student and instructor management, quizzes, certificates, and payments into one system.\"}', '{\"ar\":\"يوفر تجربة تعليمية تبدأ من استعراض الدورات والالتحاق بها، مرورًا بمشاهدة الدروس المباشرة والمسجلة وحل الواجبات والاختبارات، وصولًا إلى متابعة التقدم والحصول على الشهادات. تتيح لوحة الإدارة تنظيم المحتوى والمدربين والطلاب، إدارة التسجيلات والمبيعات والمدفوعات، ومتابعة الأداء من خلال التقارير والإحصاءات. تشمل المنصة أدوات للتواصل والدعم، بالإضافة إلى متجر للمنتجات الرقمية والمادية وخيارات تسويقية متنوعة.\",\"en\":\"Supports the full learning journey: discovering and enrolling in courses, attending live or recorded lessons, completing assignments and quizzes, tracking progress, and earning certificates. Its admin dashboard manages content, instructors, students, enrollments, sales, and payments with reports and analytics. The platform also includes communication and support tools, a product store, and marketing features.\"}', '{\"ar\":\"إدارة المحتوى التعليمي والطلاب والمدربين والحصص المباشرة والتقييمات والمدفوعات عبر أدوات متفرقة تجعل المتابعة اليومية أصعب وتشتت تجربة المتعلم.\",\"en\":\"Managing learning content, students, instructors, live classes, assessments, and payments across separate tools complicates daily operations and fragments the learner experience.\"}', '{\"ar\":\"منصة موحدة بلوحات للإدارة والمدرب والمتعلم، تجمع نشر الدورات وإدارة التسجيلات والتعلم والتقييم والشهادات والمعاملات المالية في مسار واضح قابل للمتابعة.\",\"en\":\"A unified platform with admin, instructor, and learner dashboards for publishing courses, managing enrollments, delivering lessons, assessing progress, issuing certificates, and handling transactions.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"لوحة الإدارة والتحليلات\", \"en\": \"Admin Dashboard and Analytics\"}, \"points\": [{\"ar\": \"لوحة تحكم لمتابعة نشاط المنصة\", \"en\": \"Central dashboard for platform activity\"}, {\"ar\": \"إحصاءات المبيعات والدخل والطلبات الجديدة\", \"en\": \"Sales, income, and new order statistics\"}, {\"ar\": \"رسوم بيانية للمبيعات ونمو المستخدمين\", \"en\": \"Sales and user growth charts\"}, {\"ar\": \"متابعة أحدث الدورات والتعليقات وتذاكر الدعم\", \"en\": \"Monitor recent courses, comments, and support tickets\"}, {\"ar\": \"لوحة تسويق تعرض الأرباح وأفضل الدورات والمدربين\", \"en\": \"Marketing dashboard for profit and top performing courses and instructors\"}]}, {\"title\": {\"ar\": \"إدارة الدورات والمحتوى\", \"en\": \"Course and Content Management\"}, \"points\": [{\"ar\": \"إنشاء دورات مسجلة وحصص مباشرة ودروس نصية\", \"en\": \"Create recorded courses, live classes, and text lessons\"}, {\"ar\": \"تنظيم المحتوى في فصول وجلسات وملفات ودروس\", \"en\": \"Organize content into chapters, sessions, files, and lessons\"}, {\"ar\": \"جدولة الجلسات التعليمية وإدارة روابط حضورها\", \"en\": \"Schedule learning sessions and manage join links\"}, {\"ar\": \"إضافة المتطلبات السابقة والدورات ذات الصلة\", \"en\": \"Add course prerequisites and related courses\"}, {\"ar\": \"إنشاء باقات تضم عدة دورات\", \"en\": \"Create bundles of multiple courses\"}, {\"ar\": \"عرض الدورات القادمة وجمع المهتمين بها\", \"en\": \"Publish upcoming courses and collect interested learners\"}, {\"ar\": \"إبراز دورات مختارة وتصنيف الدورات بالوسوم والفلاتر\", \"en\": \"Feature selected courses and organize them with tags and filters\"}, {\"ar\": \"إتاحة الملاحظات الشخصية داخل الدورات\", \"en\": \"Let learners save personal course notes\"}]}, {\"title\": {\"ar\": \"التعلم المباشر والتفاعل\", \"en\": \"Live Learning and Engagement\"}, \"points\": [{\"ar\": \"إدارة الحصص المباشرة والتعلم المسجل من المنصة\", \"en\": \"Manage live classes and recorded learning from the platform\"}, {\"ar\": \"تشغيل جلسات مباشرة عبر تكاملات الاجتماعات المدعومة\", \"en\": \"Run live sessions through supported meeting integrations\"}, {\"ar\": \"منتديات أسئلة وأجوبة مرتبطة بالدورات\", \"en\": \"Course question and answer forums\"}, {\"ar\": \"نشر إعلانات للطلاب داخل الدورات\", \"en\": \"Post course announcements for learners\"}, {\"ar\": \"تعليقات وتقييمات على الدورات والمنتجات\", \"en\": \"Comments and reviews for courses and products\"}, {\"ar\": \"حفظ الدورات المفضلة والعودة إليها\", \"en\": \"Save favorite courses for later\"}]}, {\"title\": {\"ar\": \"الطلاب والمدربون والصلاحيات\", \"en\": \"Users, Instructors, and Permissions\"}, \"points\": [{\"ar\": \"إدارة حسابات الطلاب والمدربين والمؤسسات والموظفين\", \"en\": \"Manage students, instructors, organizations, and staff\"}, {\"ar\": \"مراجعة طلبات التحول إلى مدرب أو مؤسسة\", \"en\": \"Review instructor and organization applications\"}, {\"ar\": \"توزيع صلاحيات الإدارة حسب الأدوار\", \"en\": \"Assign role based admin permissions\"}, {\"ar\": \"إنشاء مجموعات للمستخدمين وإدارتها\", \"en\": \"Create and manage user groups\"}, {\"ar\": \"متابعة سجل تسجيل الدخول وإنهاء الجلسات\", \"en\": \"Review login history and end sessions\"}, {\"ar\": \"إدارة شارات المستخدمين ومكافآتهم\", \"en\": \"Manage user badges and rewards\"}]}, {\"title\": {\"ar\": \"التسجيل والتقدم الدراسي\", \"en\": \"Enrollment and Learning Progress\"}, \"points\": [{\"ar\": \"تسجيل الطلاب في الدورات وإدارة سجلات الالتحاق\", \"en\": \"Enroll students and manage enrollment records\"}, {\"ar\": \"قوائم انتظار للدورات عند عدم توفر مقاعد\", \"en\": \"Waitlists for courses without available seats\"}, {\"ar\": \"متابعة مشتريات الطالب ودوراته من لوحته\", \"en\": \"Track student purchases and courses in the learner panel\"}, {\"ar\": \"إحصاءات لكل دورة وقوائم الطلاب المسجلين\", \"en\": \"Per course statistics and enrolled student lists\"}, {\"ar\": \"استكمال التعلم من آخر محتوى تمت مشاهدته\", \"en\": \"Resume learning from the last viewed content\"}]}, {\"title\": {\"ar\": \"الواجبات والاختبارات والشهادات\", \"en\": \"Assignments, Quizzes, and Certificates\"}, \"points\": [{\"ar\": \"إنشاء واجبات للطلاب ومتابعة تسليمها\", \"en\": \"Create assignments and track submissions\"}, {\"ar\": \"إعداد اختبارات وأسئلة وإدارة النتائج\", \"en\": \"Build quizzes and questions and manage results\"}, {\"ar\": \"ربط الاختبارات بالدورات التعليمية\", \"en\": \"Link quizzes to courses\"}, {\"ar\": \"إصدار شهادات إتمام أو اجتياز\", \"en\": \"Issue completion or achievement certificates\"}, {\"ar\": \"تصميم قوالب شهادات وإدارة إعداداتها\", \"en\": \"Design certificate templates and configure certificates\"}, {\"ar\": \"التحقق من الشهادات الصادرة\", \"en\": \"Validate issued certificates\"}]}, {\"title\": {\"ar\": \"الجلسات الاستشارية\", \"en\": \"Consultations and Appointments\"}, \"points\": [{\"ar\": \"عرض المستشارين والمدربين المتاحين للجلسات\", \"en\": \"List consultants and instructors available for sessions\"}, {\"ar\": \"حجز مواعيد فردية ومتابعة الحجوزات\", \"en\": \"Book one to one meetings and track reservations\"}, {\"ar\": \"إدارة إعدادات الاجتماعات من لوحة المستخدم\", \"en\": \"Manage meeting settings from the user panel\"}]}, {\"title\": {\"ar\": \"المبيعات والمدفوعات\", \"en\": \"Sales and Payments\"}, \"points\": [{\"ar\": \"بيع الدورات والباقات والمنتجات\", \"en\": \"Sell courses, bundles, and products\"}, {\"ar\": \"متابعة المبيعات والفواتير والرصيد المالي\", \"en\": \"Track sales, invoices, and financial balances\"}, {\"ar\": \"إعداد وسائل دفع إلكترونية متعددة\", \"en\": \"Configure multiple online payment methods\"}, {\"ar\": \"مراجعة المدفوعات البنكية أو اليدوية\", \"en\": \"Review bank transfers and offline payments\"}, {\"ar\": \"إدارة طلبات سحب أرباح المدربين\", \"en\": \"Manage instructor payout requests\"}, {\"ar\": \"إنشاء اشتراكات وباقات تسجيل\", \"en\": \"Offer subscriptions and registration packages\"}, {\"ar\": \"جدولة الدفع بالأقساط ومتابعة طلباته\", \"en\": \"Set up installments and track installment orders\"}, {\"ar\": \"دعم إعدادات العملات والبنوك\", \"en\": \"Configure currencies and banks\"}]}, {\"title\": {\"ar\": \"Marketing and Promotions\", \"en\": \"Marketing and Promotions\"}, \"points\": [{\"ar\": \"كوبونات خصم وعروض خاصة\", \"en\": \"Discount coupons and special offers\"}, {\"ar\": \"ترويج الدورات والمدربين داخل المنصة\", \"en\": \"Promote courses and instructors on the platform\"}, {\"ar\": \"لافتات إعلانية ونوافذ ترويجية\", \"en\": \"Advertising banners and promotional popups\"}, {\"ar\": \"إرسال رسائل النشرات البريدية\", \"en\": \"Send newsletter campaigns\"}, {\"ar\": \"برنامج إحالة ومكافآت ونقاط\", \"en\": \"Referral, rewards, and points programs\"}, {\"ar\": \"عروض استرداد نقدي وهدايا\", \"en\": \"Cashback offers and gifts\"}, {\"ar\": \"قواعد لعروض سلات الشراء المتروكة\", \"en\": \"Campaign rules for abandoned carts\"}]}, {\"title\": {\"ar\": \"المتجر الإلكتروني\", \"en\": \"Online Store\"}, \"points\": [{\"ar\": \"إدارة المنتجات الرقمية والمادية\", \"en\": \"Manage digital and physical products\"}, {\"ar\": \"تصنيفات ومواصفات وفلاتر للمنتجات\", \"en\": \"Product categories, specifications, and filters\"}, {\"ar\": \"إدارة البائعين ومنتجات المنصة\", \"en\": \"Manage sellers and in house products\"}, {\"ar\": \"متابعة طلبات المتجر والمبيعات\", \"en\": \"Track store orders and sales\"}, {\"ar\": \"ملفات مرتبطة بالمنتجات وأسئلة شائعة وتقييمات\", \"en\": \"Product files, FAQs, and reviews\"}, {\"ar\": \"خصومات وشارات ترويجية للمنتجات\", \"en\": \"Product discounts and promotional badges\"}]}, {\"title\": {\"ar\": \"التواصل والدعم والمجتمع\", \"en\": \"Communication, Support, and Community\"}, \"points\": [{\"ar\": \"نظام تذاكر دعم مع أقسام متخصصة\", \"en\": \"Support ticket system with dedicated departments\"}, {\"ar\": \"إشعارات داخل النظام وقوالب للرسائل\", \"en\": \"In app notifications and message templates\"}, {\"ar\": \"لوحات إعلانات عامة وإعلانات خاصة بالدورات\", \"en\": \"General noticeboards and course announcements\"}, {\"ar\": \"منتديات ونقاشات وموضوعات مميزة\", \"en\": \"Forums, discussions, and featured topics\"}, {\"ar\": \"إدارة البلاغات والتعليقات والمراجعات\", \"en\": \"Moderate reports, comments, and reviews\"}, {\"ar\": \"نماذج تواصل واستقبال الرسائل\", \"en\": \"Contact forms and message handling\"}]}, {\"title\": {\"ar\": \"الذكاء الاصطناعي\", \"en\": \"AI Content Tools\"}, \"points\": [{\"ar\": \"قوالب لإنشاء المحتوى بمساعدة الذكاء الاصطناعي\", \"en\": \"Templates for AI assisted content creation\"}, {\"ar\": \"إدارة سجل المحتوى المنشأ\", \"en\": \"Manage generated content history\"}, {\"ar\": \"ضبط حدود استخدام أدوات الذكاء الاصطناعي\", \"en\": \"Configure access and usage limits for AI tools\"}]}, {\"title\": {\"ar\": \"الإعدادات والأمان\", \"en\": \"Settings and Security\"}, \"points\": [{\"ar\": \"ضبط إعدادات المنصة العامة والمظهر\", \"en\": \"Configure general platform settings and appearance\"}, {\"ar\": \"إدارة قنوات الدفع والتكاملات الخارجية\", \"en\": \"Manage payment channels and external integrations\"}, {\"ar\": \"صلاحيات تفصيلية للأقسام والإجراءات\", \"en\": \"Granular permissions for sections and actions\"}, {\"ar\": \"قيود وصول حسب عنوان IP وسجل الجلسات\", \"en\": \"IP access restrictions and session history\"}, {\"ar\": \"مراجعة طلبات حذف الحساب أو المحتوى\", \"en\": \"Review account and content deletion requests\"}]}]', NULL, NULL, NULL, 39, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-30 13:27:12', '2026-09-30 14:43:59', NULL),
(31, '{\"ar\":\"منصة إدارة الصالونات وحجز خدمات التجميل متعددة البائعين\",\"en\":\"Multi-Vendor Salon & Beauty Booking Platform\"}', 'multi-vendor-salon-beauty-booking-platform', NULL, NULL, NULL, 'web', '{\"ar\":\"منصة رقمية تجمع الصالونات وخبراء التجميل المستقلين والعملاء في مكان واحد. تتيح استكشاف الخدمات والمنتجات، حجز المواعيد، شراء المنتجات، والاستفادة من العروض، مع لوحة لإدارة التشغيل والطلبات والمدفوعات.\",\"en\":\"A multi-vendor beauty platform connecting salons, independent professionals, and customers. Users can discover services and products, book appointments, shop online, and use offers, while administrators manage operations, orders, and payments.\"}', '{\"ar\":\"مشروع متكامل لإدارة سوق خدمات التجميل والصالونات. يستطيع العميل البحث عن الصالونات ومقدمي الخدمة حسب المدينة والتصنيف، الاطلاع على التفاصيل والتقييمات، اختيار الخدمة أو الباقة والموعد المتاح، ثم إتمام الحجز أو طلب المنتجات. يدعم المشروع إدارة الصالونات والمتخصصين والخبراء المستقلين والخدمات والباقات والمنتجات والمخزون والعروض والطلبات. تشمل لوحة الإدارة متابعة الحجوزات والمبيعات والإحصاءات، إدارة المستخدمين والمحتوى والعمولات والمدفوعات، والرد على الاستفسارات والشكاوى. توجد واجهة ويب للعملاء، ولوحة إدارة، وواجهة API لتطبيقات العميل ومقدم الخدمة.\",\"en\":\"A complete marketplace for salon and beauty services. Customers can browse salons and independent professionals by city and category, review profiles and ratings, select a service or package and an available time slot, then book an appointment or place a product order. The platform includes management of salons, specialists, freelancers, services, packages, products, stock, offers, and orders. The admin dashboard covers bookings, sales statistics, users, content, commissions, payments, inquiries, and complaints. The project includes a customer web interface, an admin dashboard, and an API for customer and provider apps.\"}', '{\"ar\":\"تشغيل عدة صالونات وخبراء مستقلين ومنتجاتهم من نظام واحد، مع تنسيق المواعيد، متابعة الحجوزات والطلبات، وتوفير تجربة واضحة للعملاء عبر مواقع ومقدمي خدمات مختلفين.\",\"en\":\"Managing multiple salons, independent professionals, and their products in one system while coordinating availability, tracking bookings and orders, and giving customers a clear experience across locations and providers.\"}', '{\"ar\":\"منصة موحدة تربط اكتشاف الخدمات والمنتجات بالحجز والشراء والدفع والمتابعة. توفر لكل جانب أدواته: تجربة للعميل، وإدارة للخدمات والطلبات لدى مقدمي الخدمة، ولوحة مركزية للإشراف على المحتوى والعمليات والإحصاءات.\",\"en\":\"A unified platform that connects service and product discovery with booking, shopping, payment, and order tracking. It provides a customer experience, provider tools for services and orders, and a central dashboard for content, operations, and reporting.\"}', NULL, NULL, NULL, '[{\"title\": {\"ar\": \"اكتشاف الصالونات والخبراء\", \"en\": \"Discover Salons & Professionals\"}, \"points\": [{\"ar\": \"تصفح الصالونات وخبراء التجميل المستقلين حسب المدينة والتصنيف.\", \"en\": \"Browse salons and independent beauty professionals by city and category.\"}, {\"ar\": \"البحث عن مقدمي الخدمات واستعراض النتائج القريبة والتفاصيل.\", \"en\": \"Search providers and explore nearby results and detailed profiles.\"}, {\"ar\": \"عرض معلومات الصالون، الصور، الموقع، مواعيد العمل والتقييمات.\", \"en\": \"View salon information, photos, location, opening hours, and ratings.\"}, {\"ar\": \"إبراز الصالونات والخبراء الأكثر شهرة في واجهة الاكتشاف.\", \"en\": \"Highlight popular salons and professionals in discovery views.\"}]}, {\"title\": {\"ar\": \"حجز المواعيد\", \"en\": \"Appointment Booking\"}, \"points\": [{\"ar\": \"اختيار الخدمة أو الباقة والموعد من الفترات المتاحة.\", \"en\": \"Choose a service or package and book an available time slot.\"}, {\"ar\": \"ربط الحجز بالصالون أو الخبير المستقل أو المتخصص المناسب.\", \"en\": \"Assign bookings to a salon, freelancer, or specialist.\"}, {\"ar\": \"دعم بيانات العنوان وملاحظات العميل والتكلفة والخصم والضريبة.\", \"en\": \"Capture addresses, customer notes, pricing, discounts, and tax.\"}, {\"ar\": \"متابعة حالة الحجز وعرض تفاصيله وسجل المواعيد.\", \"en\": \"Track booking status, details, and appointment history.\"}, {\"ar\": \"عرض الحجوزات في التقويم والاستعلام عنها حسب التاريخ.\", \"en\": \"View appointments on a calendar and filter them by date.\"}, {\"ar\": \"إنشاء وعرض فواتير الحجوزات القابلة للطباعة.\", \"en\": \"Generate and view printable appointment invoices.\"}]}, {\"title\": {\"ar\": \"الخدمات والباقات\", \"en\": \"Services & Packages\"}, \"points\": [{\"ar\": \"إدارة تصنيفات خدمات التجميل والخدمات المرتبطة بها.\", \"en\": \"Manage beauty service categories and their services.\"}, {\"ar\": \"تحديد مدة الخدمة وسعرها ووصفها وصورها وحالتها.\", \"en\": \"Set service duration, price, description, images, and status.\"}, {\"ar\": \"إنشاء باقات تضم عدة خدمات مع سعر ومدة وخصم.\", \"en\": \"Create multi-service packages with pricing, duration, and discounts.\"}, {\"ar\": \"ربط الباقات والخدمات بالصالونات أو الخبراء المتاحين.\", \"en\": \"Associate packages and services with salons or available professionals.\"}]}, {\"title\": {\"ar\": \"الصالونات ومقدمو الخدمة\", \"en\": \"Salons & Providers\"}, \"points\": [{\"ar\": \"إدارة ملفات الصالونات وبياناتها وصورها وعناوينها ومواقعها.\", \"en\": \"Manage salon profiles, photos, addresses, and locations.\"}, {\"ar\": \"إدارة ملفات خبراء التجميل المستقلين وخدماتهم ومواعيد عملهم.\", \"en\": \"Manage independent professionals, services, and working hours.\"}, {\"ar\": \"إدارة المتخصصين العاملين بالصالون وربطهم بالحجوزات.\", \"en\": \"Manage salon specialists and connect them to bookings.\"}, {\"ar\": \"استقبال طلبات انضمام الصالونات والخبراء ومراجعتها.\", \"en\": \"Receive and review salon and professional registration requests.\"}, {\"ar\": \"إعداد خيارات الخدمة المنزلية والمتجر والتوفر لكل مقدم خدمة.\", \"en\": \"Configure home service, shop, and availability options per provider.\"}]}, {\"title\": {\"ar\": \"متجر المنتجات\", \"en\": \"Product Marketplace\"}, \"points\": [{\"ar\": \"عرض منتجات التجميل حسب التصنيف والتصنيف الفرعي والعلامة التجارية.\", \"en\": \"Browse beauty products by category, subcategory, and brand.\"}, {\"ar\": \"إدارة صور المنتجات ووصفها وأسعارها وخصوماتها وخصائصها.\", \"en\": \"Manage product photos, descriptions, prices, discounts, and attributes.\"}, {\"ar\": \"متابعة توفر المنتج في المخزون وإظهاره في العروض والواجهة الرئيسية.\", \"en\": \"Track stock availability and feature products in offers or home views.\"}, {\"ar\": \"إضافة المنتجات إلى المفضلة والاطلاع على تقييماتها.\", \"en\": \"Save favorite products and view product ratings.\"}]}, {\"title\": {\"ar\": \"الطلبات والتوصيل\", \"en\": \"Orders & Delivery\"}, \"points\": [{\"ar\": \"إنشاء طلبات المنتجات ومتابعة حالتها وتفاصيلها.\", \"en\": \"Place product orders and track their status and details.\"}, {\"ar\": \"دعم عنوان التسليم ورسوم التوصيل والضريبة والخصومات.\", \"en\": \"Support delivery addresses, delivery fees, tax, and discounts.\"}, {\"ar\": \"عرض طلبات الصالونات والخبراء والعملاء كل بحسب دوره.\", \"en\": \"View orders for salons, professionals, and customers by role.\"}, {\"ar\": \"إنشاء فواتير طلبات المنتجات وعرضها للطباعة.\", \"en\": \"Generate and view printable product order invoices.\"}]}, {\"title\": {\"ar\": \"الدفع والمحفظة\", \"en\": \"Payments & Wallet\"}, \"points\": [{\"ar\": \"إدارة طرق الدفع وسجلات المدفوعات الخاصة بالحجوزات والطلبات.\", \"en\": \"Manage payment methods and payment records for bookings and orders.\"}, {\"ar\": \"دعم الدفع عند الاستلام وتكاملات دفع إلكتروني متعددة بحسب الإعدادات.\", \"en\": \"Support cash on delivery and configurable online payment integrations.\"}, {\"ar\": \"استخدام رصيد المحفظة في الحجوزات وطلبات المنتجات.\", \"en\": \"Apply wallet balance to appointments and product orders.\"}, {\"ar\": \"توفير عمليات استرداد مدفوعات لبعض بوابات الدفع المتكاملة.\", \"en\": \"Process refunds through supported payment gateway integrations.\"}]}, {\"title\": {\"ar\": \"العروض والتسويق\", \"en\": \"Offers & Marketing\"}, \"points\": [{\"ar\": \"إنشاء قسائم وعروض بخصومات وحدود استخدام وتواريخ انتهاء.\", \"en\": \"Create coupons and offers with discounts, usage limits, and expiry dates.\"}, {\"ar\": \"تخصيص العروض للصالونات أو الخبراء المستقلين.\", \"en\": \"Target offers to salons or independent professionals.\"}, {\"ar\": \"إدارة اللافتات الإعلانية ومحتوى الواجهة الرئيسية.\", \"en\": \"Manage banners and homepage promotional content.\"}, {\"ar\": \"إدارة أكواد الإحالة واسترداد مكافآت الدعوات.\", \"en\": \"Manage referral codes and redeem referral rewards.\"}, {\"ar\": \"نشر المقالات والأخبار عبر قسم المدونة.\", \"en\": \"Publish articles and updates through a blog.\"}]}, {\"title\": {\"ar\": \"الحسابات والتواصل\", \"en\": \"Accounts & Communication\"}, \"points\": [{\"ar\": \"تسجيل حسابات العملاء والصالونات والخبراء وتسجيل الدخول.\", \"en\": \"Register customer, salon, and professional accounts and sign in.\"}, {\"ar\": \"تحديث الملف الشخصي والمدينة واللغة وبيانات الاتصال.\", \"en\": \"Update profile, city, language, and contact details.\"}, {\"ar\": \"التحقق من الهاتف أو البريد الإلكتروني واستعادة كلمة المرور.\", \"en\": \"Verify phone or email and recover passwords.\"}, {\"ar\": \"تبادل الرسائل عبر غرف المحادثة بين المستخدمين.\", \"en\": \"Exchange messages through user chat rooms.\"}, {\"ar\": \"إرسال إشعارات ورسائل بريد إلى شرائح مختلفة من المستخدمين.\", \"en\": \"Send notifications and emails to selected user groups.\"}, {\"ar\": \"استقبال رسائل التواصل والشكاوى والرد عليها.\", \"en\": \"Receive and respond to contact messages and complaints.\"}]}, {\"title\": {\"ar\": \"التقييمات والثقة\", \"en\": \"Reviews & Trust\"}, \"points\": [{\"ar\": \"تقييم الصالونات ومقدمي الخدمات.\", \"en\": \"Rate salons and service providers.\"}, {\"ar\": \"تقييم الخدمات والباقات والمنتجات بعد استخدامها.\", \"en\": \"Review services, packages, and products.\"}, {\"ar\": \"عرض متوسط التقييمات وعددها في الملفات والمنتجات.\", \"en\": \"Display rating averages and counts on profiles and products.\"}, {\"ar\": \"إدارة التقييمات ومراجعتها من لوحة الإدارة.\", \"en\": \"Manage and review feedback from the admin dashboard.\"}]}, {\"title\": {\"ar\": \"لوحة الإدارة والتقارير\", \"en\": \"Admin Dashboard & Reports\"}, \"points\": [{\"ar\": \"إدارة المستخدمين والمديرين والصالونات والخبراء من مكان واحد.\", \"en\": \"Manage users, administrators, salons, and professionals centrally.\"}, {\"ar\": \"متابعة إحصاءات الحجوزات وطلبات المنتجات حسب الفترات.\", \"en\": \"Track appointment and product order statistics over time.\"}, {\"ar\": \"إدارة التصنيفات والمدن والعلامات التجارية والمحتوى الثابت.\", \"en\": \"Manage categories, cities, brands, and static pages.\"}, {\"ar\": \"متابعة العمولات والمدفوعات وطلبات الانضمام والشكاوى.\", \"en\": \"Monitor commissions, payments, registration requests, and complaints.\"}, {\"ar\": \"ضبط الضرائب ورسوم التوصيل والعملة ونطاق البحث وإعدادات التطبيق.\", \"en\": \"Configure tax, delivery fees, currency, search radius, and app settings.\"}]}, {\"title\": {\"ar\": \"واجهات متعددة\", \"en\": \"Multiple Interfaces\"}, \"points\": [{\"ar\": \"واجهة ويب للعملاء لاستكشاف الخدمات والمنتجات.\", \"en\": \"Customer web interface for discovering services and products.\"}, {\"ar\": \"لوحة إدارة مستقلة لمتابعة وتشغيل المنصة.\", \"en\": \"Dedicated admin dashboard for platform operations.\"}, {\"ar\": \"واجهة API تدعم تطبيقات العملاء ومقدمي الخدمات.\", \"en\": \"API supporting customer and provider applications.\"}, {\"ar\": \"إعدادات للغة واتجاه العرض بحسب تهيئة المنصة.\", \"en\": \"Language and layout direction settings based on platform configuration.\"}]}]', NULL, NULL, NULL, 40, NULL, NULL, NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-30 14:43:33', '2026-09-30 14:45:45', NULL);

