(1, 'home', '/', '{\"ar\":\"Ytech | السعودية\",\"en\":\"Ytech | Saudi Arabia\"}', NULL, '{\"ar\":\"Ytech | شركة تطوير برمجيات في السعودية\",\"en\":\"Ytech | Software Development Company in Saudi Arabia\"}', '{\"ar\":\"Ytech تبني تطبيقات ويب مخصصة وتطبيقات جوال وحلول مؤسسية للشركات في السعودية والخليج.\",\"en\":\"Ytech builds custom web applications, mobile apps, and enterprise solutions for businesses across Saudi Arabia and the GCC.\"}', '{\"ar\":\"Ytech - نبني حلولاً رقمية قابلة للتوسع\",\"en\":\"Ytech - Building Digital Solutions That Scale\"}', '{\"ar\":\"شارك Ytech في تطوير الويب والجوال والتجارة الإلكترونية والحلول السحابية.\",\"en\":\"Partner with Ytech for web development, mobile apps, e-commerce, and cloud solutions.\"}', NULL, NULL, 1, '2026-08-30 17:49:37', '2026-10-01 06:27:12'),
(2, 'about', '/about', '{\"ar\":\"من نحن\",\"en\":\"About Us\"}', '{\"ar\":\"نبني حلولًا رقمية تساعد الشركات على النمو والتطور.\",\"en\":\"We build digital solutions that help businesses grow and evolve.\"}', '{\"ar\":\"عن Ytech | فريقنا ورسالتنا\",\"en\":\"About Ytech | Our Team & Mission\"}', '{\"ar\":\"تعرف على Ytech، شركة سعودية لتطوير البرمجيات ملتزمة بتحويل الأعمال عبر التقنية منذ 2018.\",\"en\":\"Learn about Ytech, a Saudi software development company dedicated to transforming businesses through technology since 2018.\"}', NULL, NULL, NULL, NULL, 1, '2026-08-30 17:49:37', '2026-10-01 06:27:12'),
(3, 'services', '/services', '{\"ar\":\"تقنية مبنية حول عملك.\",\"en\":\"Technology built around your business.\"}', '{\"ar\":\"قدرات برمجية متكاملة للمؤسسات المستعدة للاستثمار في بنية رقمية مستدامة.\",\"en\":\"End-to-end software capabilities for organizations ready to invest in lasting digital infrastructure.\"}', '{\"ar\":\"خدماتنا | تطوير الويب والجوال والسحابة\",\"en\":\"Our Services | Web, Mobile & Cloud Development\"}', '{\"ar\":\"استكشف خدمات Ytech: تطوير تطبيقات الويب والجوال والتجارة الإلكترونية وتصميم UI\\/UX وDevOps والاستشارات.\",\"en\":\"Explore Ytech services: web application development, mobile apps, e-commerce, UI\\/UX design, cloud DevOps, and IT consulting.\"}', NULL, NULL, NULL, NULL, 1, '2026-08-30 17:49:37', '2026-10-01 06:27:12'),
(4, 'projects', '/projects', '{\"ar\":\"أعمال مختارة.\",\"en\":\"Selected work.\"}', '{\"ar\":\"دراسات حالة من منصات مؤسسية ومنتجات SaaS وأنظمة أعمال حرجة.\",\"en\":\"Case studies from enterprise platforms, SaaS products, and mission-critical business systems.\"}', '{\"ar\":\"معرض الأعمال | مشاريع Ytech\",\"en\":\"Portfolio & Case Studies | Ytech Projects\"}', '{\"ar\":\"اطلع على محفظة Ytech من المشاريع الناجحة بما فيها منصات التجارة الإلكترونية وتطبيقات الرعاية الصحية.\",\"en\":\"View Ytech portfolio of successful projects including e-commerce platforms, healthcare apps, and enterprise dashboards.\"}', NULL, NULL, NULL, NULL, 1, '2026-08-30 17:49:37', '2026-10-01 06:27:12'),
(5, 'blog', '/blog', NULL, NULL, '{\"ar\":\"المدونة | رؤى Ytech ومقالات تقنية\",\"en\":\"Blog | Ytech Insights & Tech Articles\"}', '{\"ar\":\"اقرأ أحدث المقالات عن تطوير الويب والجوال والتحول الرقمي من فريق Ytech.\",\"en\":\"Read the latest articles on web development, mobile technology, and digital transformation from the Ytech team.\"}', NULL, NULL, NULL, NULL, 1, '2026-08-30 17:49:37', '2026-08-30 17:49:37'),
(6, 'contact', '/contact', '{\"ar\":\"لنبدأ محادثة\",\"en\":\"Start a conversation\"}', '{\"ar\":\"أخبرنا عن مشروعك. نرد خلال يوم عمل واحد.\",\"en\":\"Tell us about your project. We respond within one business day.\"}', '{\"ar\":\"تواصل مع Ytech | ابدأ مشروعك\",\"en\":\"Contact Ytech | Start Your Project\"}', '{\"ar\":\"تواصل مع Ytech لاستشارة مجانية. نرد خلال 24 ساعة.\",\"en\":\"Get in touch with Ytech for a free consultation. We respond within 24 hours.\"}', NULL, NULL, NULL, NULL, 1, '2026-08-30 17:49:37', '2026-10-01 06:27:12'),
(7, 'reviews', '/reviews', '{\"ar\":\"اسمع التجربة من أصحابها.\",\"en\":\"Hear it from our clients.\"}', '{\"ar\":\"تجارب حقيقية يحكيها عملاؤنا بأصواتهم.\",\"en\":\"Real stories, shared in the voices of the people we work with.\"}', '{\"ar\":\"آراء العملاء | Ytech\",\"en\":\"Client Reviews | Ytech\"}', '{\"ar\":\"تجارب حقيقية يحكيها عملاؤنا بأصواتهم.\",\"en\":\"Real stories, shared in the voices of the people we work with.\"}', NULL, NULL, NULL, NULL, 1, '2026-10-01 06:27:12', '2026-10-01 06:27:12');

