INSERT INTO `services` (`id`, `title`, `slug`, `short_description`, `description`, `capabilities`, `business_problems`, `icon`, `featured_image_id`, `is_featured`, `status`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '{\"ar\":\"تطوير المواقع وتطبيقات الويب\",\"en\":\"Web Development\"}', 'web-development', '{\"ar\":\"نطوّر مواقع وتطبيقات ويب سريعة وآمنة، مصممة لتناسب احتياجات عملك وقابلة للتوسع مع نموه.\",\"en\":\"We build fast, secure, and scalable web applications tailored to your business needs.\"}', '{\"ar\":\"نبني تطبيقات ويب مخصصة تدعم عمليات شركتك وتوفر تجربة استخدام سلسة لعملائك وفريقك. من لوحات التحكم والأنظمة الداخلية إلى المنصات الموجهة للعملاء، نطوّر حلولًا آمنة وقابلة للتوسع باستخدام تقنيات حديثة .\",\"en\":\"We build custom web applications that support your business operations and deliver smooth user experiences. From internal dashboards and management systems to customer-facing platforms, we create secure and scalable solutions using modern technologies.\"}', '{\"ar\": [\"تطوير تطبيقات ويب مخصصة\", \"لوحات تحكم وأنظمة إدارية\", \"تطوير وربط API\", \"تكامل الأنظمة والخدمات الخارجية\", \"بوابات العملاء والموظفين\", \"أنظمة الأعمال الداخلية\", \"تحسين الأداء وقابلية التوسع\", \"الأمان والصلاحيات\", \"تطوير الواجهات Front-end\", \"تطوير Back-end\"], \"en\": [\"Custom Web Applications\", \"Dashboards & Admin Panels\", \"API Development & Integration\", \"Third-Party Integrations\", \"Customer & Employee Portals\", \"Internal Business Systems\", \"Performance & Scalability Optimization\", \"Security & Access Control\", \"Front-end Development\", \"Back-end Development\"]}', '{\"ar\": [\"الاعتماد على العمليات اليدوية\", \"بطء الأنظمة الحالية وضعف الأداء\", \"عدم ترابط الأنظمة والبيانات\", \"صعوبة إدارة العمليات من مكان واحد\", \"تكرار إدخال البيانات والأخطاء\", \"ضعف تجربة المستخدم\", \"صعوبة التوسع مع نمو الشركة\", \"الحاجة إلى ربط الأنظمة والخدمات المختلفة\"], \"en\": [\"Manual and time-consuming processes\", \"Slow or outdated web systems\", \"Disconnected systems and data\", \"Difficulty managing operations in one place\", \"Duplicate data entry and human errors\", \"Poor user experience\", \"Scalability limitations\", \"Complex system and third-party integrations\"]}', 'code', NULL, 1, 'published', 1, NULL, NULL, '2026-08-30 17:49:36', '2026-09-26 17:13:18', NULL),
(2, '{\"ar\":\"تطوير تطبيقات الجوال\",\"en\":\"Mobile App Development\"}', 'mobile-app-development', '{\"ar\":\"تطبيقات جوال مصممة لتسهيل تجربة عملائك ودعم نمو أعمالك.\",\"en\":\"Mobile apps designed to simplify customer experiences and support business growth.\"}', '{\"ar\":\"نطوّر تطبيقات جوال تساعدك على الوصول إلى عملائك وتقديم خدماتك بشكل أسهل وأكثر احترافية. من التطبيقات المخصصة للعملاء إلى تطبيقات التشغيل الداخلي، نبني حلولًا مرنة وقابلة للتوسع مع إمكانية التكامل مع الأنظمة الحالية.\",\"en\":\"We build mobile applications that help you reach your customers and deliver services more efficiently. From customer-facing apps to internal business applications, we create flexible and scalable solutions with seamless integration into your existing systems.\"}', '{\"ar\": [\"تطبيقات iOS وAndroid\", \"تطبيقات متعددة المنصات\", \"تطبيقات مخصصة للأعمال\", \"ربط التطبيقات بالـ APIs\", \"تكامل أنظمة الدفع\", \"الإشعارات الفورية\", \"تسجيل الدخول والمصادقة\", \"لوحات تحكم وإدارة المحتوى\", \"تطبيقات تعمل دون اتصال\", \"نشر التطبيقات على المتاجر\"], \"en\": [\"iOS & Android Applications\", \"Cross-Platform Apps\", \"Custom Business Applications\", \"API Integration\", \"Payment Gateway Integration\", \"Push Notifications\", \"Authentication & User Accounts\", \"Admin Panels & Content Management\", \"Offline-First Applications\", \"App Store & Google Play Deployment\"]}', '{\"ar\": [\"عدم وجود تطبيق يخدم العملاء\", \"ضعف تجربة الاستخدام على الجوال\", \"الاعتماد على العمليات اليدوية\", \"صعوبة وصول العملاء إلى الخدمات\", \"عدم ترابط التطبيق مع الأنظمة الحالية\", \"بطء أو ضعف أداء التطبيقات الحالية\", \"الحاجة إلى تطبيق واحد يعمل على أكثر من منصة\", \"صعوبة إدارة المستخدمين والبيانات\"], \"en\": [\"No dedicated mobile experience for customers\", \"Poor mobile user experience\", \"Manual and time-consuming processes\", \"Difficulty accessing services on the go\", \"Disconnected mobile apps and business systems\", \"Slow or outdated existing applications\", \"Need for one app across multiple platforms\", \"Difficulty managing users and application data\"]}', 'smartphone', NULL, 1, 'published', 2, NULL, NULL, '2026-08-30 17:49:36', '2026-09-26 17:15:29', NULL),
(3, '{\"ar\":\"تطوير المتاجر الإلكترونية\",\"en\":\"E-commerce Development\"}', 'e-commerce-development', '{\"ar\":\"نبني تجارب تجارة إلكترونية متكاملة تجمع بين الأداء، سهولة الشراء، والإدارة الذكية للعمليات.\",\"en\":\"We build complete e-commerce experiences focused on performance, seamless purchasing, and efficient business operations.\"}', '{\"ar\":\"نطوّر منصات تجارة إلكترونية مخصصة تساعدك على إدارة المنتجات والطلبات والعملاء والمدفوعات من مكان واحد. نربط المتجر ببوابات الدفع، شركات الشحن، أنظمة المخزون وERP، ونبني تجربة شراء سريعة وسلسة وقابلة للتوسع مع نمو أعمالك.\",\"en\":\"We develop custom e-commerce platforms that bring products, orders, customers, and payments into one seamless experience. From payment gateways and shipping integrations to inventory and ERP connectivity, we build scalable online stores designed for smooth operations and long-term growth.\"}', '{\"ar\": [\"متاجر إلكترونية مخصصة\", \"إدارة المنتجات والتصنيفات\", \"إدارة الطلبات والعملاء\", \"تكامل بوابات الدفع\", \"تكامل شركات الشحن\", \"إدارة المخزون\", \"الربط مع ERP وCRM\", \"الكوبونات والعروض الترويجية\", \"حسابات العملاء وبرامج الولاء\", \"لوحات التحكم والتقارير\", \"تجربة شراء وCheckout محسّنة\", \"دعم تعدد اللغات والعملات\"], \"en\": [\"Custom E-commerce Platforms\", \"Product & Category Management\", \"Order & Customer Management\", \"Payment Gateway Integration\", \"Shipping & Logistics Integration\", \"Inventory Management\", \"ERP & CRM Integration\", \"Discounts & Promotions\", \"Customer Accounts & Loyalty Programs\", \"Dashboards & Reporting\", \"Optimized Checkout Experience\", \"Multi-language & Multi-currency Support\"]}', '{\"ar\": [\"تجربة شراء معقدة أو بطيئة\", \"ارتفاع معدل ترك سلة الشراء\", \"صعوبة إدارة الطلبات والمخزون\", \"عدم ترابط المتجر مع الأنظمة الداخلية\", \"تعدد الأدوات والمنصات المستخدمة\", \"ضعف أداء المتجر مع زيادة الطلبات\", \"صعوبة متابعة المبيعات والتقارير\", \"مشكلات الدفع والشحن والتكاملات\", \"الحاجة إلى متجر قابل للتوسع مع نمو الأعمال\"], \"en\": [\"Complex or slow buying experiences\", \"High cart abandonment rates\", \"Difficulty managing orders and inventory\", \"Disconnected e-commerce and internal systems\", \"Too many separate tools and platforms\", \"Performance issues as order volume grows\", \"Limited visibility into sales and reporting\", \"Payment, shipping, and integration challenges\", \"E-commerce platforms that cannot scale with business growth\"]}', 'shopping-cart', NULL, 1, 'published', 3, NULL, NULL, '2026-08-30 17:49:36', '2026-09-26 17:16:42', NULL),
(4, '{\"ar\":\"تصميم تجربة وواجهة المستخدم\",\"en\":\"UI\\/UX Design\"}', 'uiux-design', '{\"ar\":\"نصمم تجارب رقمية واضحة وسلسة تجعل كل تفاعل أسهل وأكثر تأثيرًا.\",\"en\":\"We design clear, seamless digital experiences that make every interaction simpler and more meaningful.\"}', '{\"ar\":\"نصمم تجارب وواجهات رقمية تجمع بين البساطة، الجمال، وسهولة الاستخدام. نبدأ بفهم المستخدم واحتياجات العمل، ثم نحولها إلى رحلات استخدام مدروسة وواجهات متناسقة تعكس هوية علامتك وتدعم أهداف المنتج.\",\"en\":\"We create digital experiences that balance clarity, aesthetics, and usability. By understanding both user needs and business goals, we shape thoughtful user journeys and refined interfaces that reflect your brand and support your product objectives.\"}', '{\"ar\": [\"أبحاث وتجربة المستخدم\", \"تحليل رحلة المستخدم\", \"هيكلة المحتوى والتنقل\", \"Wireframes\", \"تصميم واجهات المستخدم\", \"تصميم تطبيقات الويب والجوال\", \"النماذج التفاعلية Prototypes\", \"Design Systems\", \"اختبارات قابلية الاستخدام\", \"تحسين التجارب الحالية\"], \"en\": [\"User Research\", \"User Journey Mapping\", \"Information Architecture\", \"Wireframing\", \"User Interface Design\", \"Web & Mobile App Design\", \"Interactive Prototyping\", \"Design Systems\", \"Usability Testing\", \"Experience Optimization\"]}', '{\"ar\": [\"واجهات معقدة أو مربكة\", \"ضعف تجربة المستخدم\", \"صعوبة الوصول إلى المعلومة أو الخدمة\", \"عدم وضوح رحلة المستخدم\", \"تفاوت التصميم بين الشاشات\", \"ضعف الهوية البصرية داخل المنتج\", \"انخفاض التفاعل أو معدلات التحويل\", \"منتجات جيدة تقنيًا لكن صعبة الاستخدام\"], \"en\": [\"Complex or confusing interfaces\", \"Poor user experience\", \"Difficulty finding information or completing tasks\", \"Unclear user journeys\", \"Inconsistent design across screens\", \"Weak visual consistency within the product\", \"Low engagement or conversion rates\", \"Technically strong products that are difficult to use\"]}', 'palette', NULL, 0, 'published', 4, NULL, NULL, '2026-08-30 17:49:36', '2026-09-26 17:21:19', NULL),
(5, '{\"ar\":\"السحابة وDevOps\",\"en\":\"Cloud & DevOps\"}', 'cloud-devops', '{\"ar\":\"بنية AWS وAzure وخطوط CI\\/CD ومراقبة مستمرة.\",\"en\":\"AWS and Azure infrastructure setup, CI\\/CD pipelines, and monitoring.\"}', '{\"ar\":\"انتقل إلى السحابة بثقة. نصمم وننشر ونحافظ على البنية السحابية مع خطوط آلية ومراقبة وخطط استرداد من الكوارث.\",\"en\":\"Migrate to the cloud with confidence. We architect, deploy, and maintain cloud infrastructure with automated pipelines, monitoring, and disaster recovery planning.\"}', NULL, NULL, 'cloud', NULL, 0, 'published', 5, NULL, NULL, '2026-08-30 17:49:36', '2026-09-26 17:03:46', '2026-09-26 17:03:46'),
(6, '{\"ar\":\"استشارات تقنية\",\"en\":\"IT Consulting\"}', 'it-consulting', '{\"ar\":\"إرشاد تقني استراتيجي لمواءمة استثمارات IT مع أهداف العمل.\",\"en\":\"Strategic technology guidance to align IT investments with business goals.\"}', '{\"ar\":\"لست متأكداً من أين تبدأ؟ يقيّم مستشارونا أنظمتك الحالية ويحددون الفرص ويضعون خرائط طريق تقنية قابلة للتنفيذ للتحول الرقمي.\",\"en\":\"Not sure where to start? Our consultants assess your current systems, identify opportunities, and create actionable technology roadmaps for digital transformation.\"}', NULL, NULL, 'briefcase', NULL, 0, 'published', 6, NULL, NULL, '2026-08-30 17:49:36', '2026-09-14 12:09:12', NULL),
(10, '{\"ar\":\"تطوير الأنظمة المخصصة\",\"en\":\"Custom Software Development\"}', 'custom-software-development', '{\"ar\":\"أنظمة ERP، وCRM، والموارد البشرية، وإدارة المخزون، ونقاط البيع، والحجوزات، والمحاسبة، وسير العمل، بالإضافة إلى أنظمة الأعمال المخصصة.\",\"en\":\"ERP, CRM, HR, Inventory, POS, Booking, Accounting, Workflow, and custom business systems.\"}', '{\"ar\":\"نطوّر أنظمة برمجية مخصصة تتوافق مع طبيعة عملك واحتياجاتك التشغيلية، بدءًا من أنظمة ERP وCRM وصولًا إلى أنظمة الموارد البشرية، المخزون، المحاسبة، الحجوزات، نقاط البيع وسير العمل. نركز على بناء حلول مرنة، قابلة للتوسع، وسهلة التكامل مع أنظمتك الحالية.\",\"en\":\"We build custom software systems tailored to your business operations and specific requirements. From ERP and CRM platforms to HR, inventory, accounting, booking, POS, and workflow systems, we create scalable, flexible solutions that integrate smoothly with your existing tools.\"}', '{\"ar\": [\"أنظمة ERP وCRM\", \"أنظمة الموارد البشرية HR\", \"أنظمة إدارة المخزون\", \"أنظمة نقاط البيع POS\", \"أنظمة الحجز والمواعيد\", \"أنظمة المحاسبة والفواتير\", \"أنظمة إدارة سير العمل\", \"لوحات التحكم والتقارير\", \"تكامل الأنظمة وواجهات API\", \"أنظمة مخصصة حسب طبيعة النشاط\"], \"en\": [\"ERP & CRM Systems\", \"HR Management Systems\", \"Inventory Management Systems\", \"POS Systems\", \"Booking & Appointment Systems\", \"Accounting & Billing Systems\", \"Workflow Management Systems\", \"Dashboards & Reporting\", \"System Integrations & APIs\", \"Industry-Specific Custom Systems\"]}', '{\"ar\": [\"تعدد الأنظمة وعدم ترابطها\", \"الاعتماد على العمليات اليدوية\", \"صعوبة متابعة البيانات والتقارير\", \"تكرار إدخال البيانات والأخطاء\", \"ضعف إدارة العمليات الداخلية\", \"عدم توافق البرامج الجاهزة مع احتياجات الشركة\", \"صعوبة التوسع مع نمو الأعمال\", \"الحاجة إلى ربط الأقسام والأنظمة في منصة واحدة\"], \"en\": [\"Disconnected systems and tools\", \"Manual and repetitive processes\", \"Limited visibility into data and reports\", \"Duplicate data entry and human errors\", \"Inefficient internal operations\", \"Off-the-shelf software that does not fit business needs\", \"Systems that cannot scale with business growth\", \"Difficulty connecting departments and platforms\"]}', NULL, NULL, 1, 'published', 0, NULL, NULL, '2026-09-26 17:05:00', '2026-10-01 05:10:46', NULL),
(11, '{\"ar\":\"التسويق الرقمي\",\"en\":\"Digital Marketing\"}', 'digital-marketing', '{\"ar\":\"نبني استراتيجيات تسويق رقمي تساعد علامتك على الوصول للجمهور المناسب وتحويل الاهتمام إلى نمو فعلي.\",\"en\":\"We build digital marketing strategies that help your brand reach the right audience and turn attention into measurable growth.\"}', '{\"ar\":\"نطوّر استراتيجيات تسويق رقمي متكاملة تبدأ من فهم السوق والجمهور، وتمتد إلى صناعة المحتوى، إدارة الحملات الإعلانية، تحسين الظهور، وقياس الأداء. هدفنا ليس مجرد الوصول، بل بناء حضور رقمي يدعم المبيعات ويحقق نموًا مستدامًا.\",\"en\":\"We create integrated digital marketing strategies built around your market, audience, and business goals. From content and paid campaigns to visibility, performance tracking, and conversion optimization, we focus on building a digital presence that supports sales and long-term growth.\"}', '{\"ar\": [\"استراتيجية التسويق الرقمي\", \"إدارة وسائل التواصل الاجتماعي\", \"صناعة المحتوى\", \"الحملات الإعلانية المدفوعة\", \"Media Buying\", \"SEO وتحسين الظهور\", \"إدارة الحملات على Google وMeta\", \"Lead Generation\", \"تحسين معدلات التحويل\", \"التسويق عبر البريد الإلكتروني\", \"تحليل الأداء والتقارير\", \"تخطيط الحملات التسويقية\"], \"en\": [\"Digital Marketing Strategy\", \"Social Media Management\", \"Content Creation\", \"Paid Advertising Campaigns\", \"Media Buying\", \"SEO & Search Visibility\", \"Google & Meta Ads Management\", \"Lead Generation\", \"Conversion Rate Optimization\", \"Email Marketing\", \"Performance Analytics & Reporting\", \"Campaign Planning\"]}', '{\"ar\": [\"ضعف الوصول للجمهور المستهدف\", \"إنفاق إعلاني دون نتائج واضحة\", \"قلة العملاء المحتملين\", \"ضعف التفاعل مع العلامة التجارية\", \"غياب استراتيجية تسويق واضحة\", \"ضعف التحويل من الاهتمام إلى مبيعات\", \"عدم وضوح أداء الحملات\", \"تشتت القنوات التسويقية\", \"ضعف الظهور الرقمي أمام المنافسين\"], \"en\": [\"Difficulty reaching the right audience\", \"Ad spend without clear returns\", \"Low lead generation\", \"Weak brand engagement\", \"Lack of a clear marketing strategy\", \"Low conversion from interest to sales\", \"Limited visibility into campaign performance\", \"Disconnected marketing channels\", \"Weak digital presence against competitors\"]}', NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-26 17:24:06', '2026-09-26 17:47:20', NULL),
(12, '{\"ar\":\"تطوير الأعمال\",\"en\":\"Business Development\"}', 'business-development', '{\"ar\":\"نساعدك على اكتشاف فرص جديدة، بناء شراكات أقوى، وتحويل النمو إلى خطوات عملية قابلة للتنفيذ.\",\"en\":\"We help you identify new opportunities, build stronger partnerships, and turn growth into actionable business outcomes.\"}', '{\"ar\":\"نطوّر فرص نمو حقيقية من خلال دراسة السوق، تحديد الشرائح المناسبة، بناء الشراكات، وتطوير قنوات المبيعات. نعمل على تحويل الفرص التجارية إلى خطط واضحة تساعدك على التوسع، دخول أسواق جديدة، وزيادة فرص الإيرادات.\",\"en\":\"We create real growth opportunities by analyzing markets, identifying the right customer segments, building strategic partnerships, and strengthening sales channels. Our goal is to turn business opportunities into clear, actionable plans that support expansion and revenue growth.\"}', '{\"ar\": [\"دراسة السوق والفرص\", \"تحديد العملاء المستهدفين\", \"Lead Generation\", \"بناء الشراكات الاستراتيجية\", \"تطوير قنوات المبيعات\", \"دخول أسواق جديدة\", \"التواصل مع العملاء المحتملين\", \"تأهيل الفرص التجارية\", \"إعداد عروض الأعمال\", \"دعم عمليات التفاوض\", \"تطوير خطط النمو\", \"متابعة الـ Pipeline\"], \"en\": [\"Market & Opportunity Research\", \"Target Customer Identification\", \"Lead Generation\", \"Strategic Partnerships\", \"Sales Channel Development\", \"Market Expansion\", \"Prospect Outreach\", \"Opportunity Qualification\", \"Business Proposal Development\", \"Negotiation Support\", \"Growth Planning\", \"Pipeline Management\"]}', '{\"ar\": [\"ضعف تدفق الفرص البيعية\", \"صعوبة الوصول إلى العملاء المناسبين\", \"غياب خطة واضحة للتوسع\", \"الاعتماد على مصادر مبيعات محدودة\", \"صعوبة دخول أسواق جديدة\", \"ضعف بناء الشراكات\", \"عدم وجود Pipeline منظم\", \"هدر الوقت على فرص غير مؤهلة\", \"صعوبة تحويل الفرص إلى صفقات\"], \"en\": [\"Limited flow of sales opportunities\", \"Difficulty reaching the right prospects\", \"Lack of a clear expansion strategy\", \"Dependence on limited sales channels\", \"Challenges entering new markets\", \"Weak partnership development\", \"Unstructured sales pipelines\", \"Time wasted on unqualified opportunities\", \"Difficulty converting opportunities into deals\"]}', NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-26 17:24:23', '2026-09-26 17:47:39', NULL),
(13, '{\"ar\":\"فرق عمل مخصصة\",\"en\":\"Dedicated Teams\"}', 'dedicated-teams', '{\"ar\":\"فرق متخصصة تعمل كامتداد لفريقك، بخبرات مناسبة لاحتياجاتك وأهدافك.\",\"en\":\"Specialized teams that work as an extension of your business, aligned with your goals and operational needs.\"}', '{\"ar\":\"نوفر لك فرق عمل متخصصة ومخصصة حسب احتياجك، سواء في التقنية، المبيعات، التسويق، خدمة العملاء أو العمليات. يعمل الفريق وفق أهدافك وأدواتك وطريقة عملك، مع مرونة في التوسع أو تقليل الموارد حسب متطلبات المشروع.\",\"en\":\"We provide dedicated teams tailored to your business needs across technology, sales, marketing, customer support, and operations. Your team works with your tools, processes, and objectives, with the flexibility to scale resources as your needs evolve.\"}', '{\"ar\": [\"فرق تطوير برمجيات مخصصة\", \"فرق QA واختبار البرمجيات\", \"فرق مبيعات وتطوير أعمال\", \"فرق تسويق رقمي\", \"فرق خدمة عملاء\", \"فرق Back Office وعمليات\", \"إدارة الفريق والموارد\", \"مرونة في زيادة أو تقليل حجم الفريق\", \"اختيار المهارات والخبرات المناسبة\", \"نماذج تعاون قصيرة وطويلة المدى\"], \"en\": [\"Dedicated Software Development Teams\", \"QA & Testing Teams\", \"Sales & Business Development Teams\", \"Digital Marketing Teams\", \"Customer Support Teams\", \"Back Office & Operations Teams\", \"Team & Resource Management\", \"Flexible Team Scaling\", \"Skill & Expertise Matching\", \"Short-Term & Long-Term Engagement Models\"]}', '{\"ar\": [\"صعوبة توظيف الكفاءات المناسبة بسرعة\", \"ارتفاع تكلفة بناء فريق داخلي كامل\", \"الحاجة إلى خبرات متخصصة لفترة محددة\", \"ضغط العمل على الفريق الحالي\", \"صعوبة التوسع السريع في الموارد\", \"الحاجة إلى فريق جاهز دون دورة توظيف طويلة\", \"عدم توفر بعض المهارات داخل الشركة\", \"الحاجة إلى تشغيل فريق كامل دون عبء إداري كبير\"], \"en\": [\"Difficulty hiring the right talent quickly\", \"High cost of building a full in-house team\", \"Need for specialized expertise\", \"Overloaded internal teams\", \"Difficulty scaling resources quickly\", \"Long recruitment and onboarding cycles\", \"Missing skills within the existing team\", \"Need for a complete team without additional operational overhead\"]}', NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-26 17:24:56', '2026-09-26 17:47:47', NULL),
(14, '{\"ar\":\"التوظيف وتوفير الكفاءات\",\"en\":\"Recruitment & Talent Outsourcing\"}', 'recruitment-talent-outsourcing', '{\"ar\":\"نوفر لك الكفاءات المناسبة بسرعة ومرونة، بما يتوافق مع احتياجات فريقك وأهداف عملك.\",\"en\":\"We connect you with the right talent quickly and flexibly, aligned with your team needs and business goals.\"}', '{\"ar\":\"نساعدك على الوصول إلى الكفاءات المناسبة دون الدخول في دورة توظيف طويلة ومعقدة. من تحديد الاحتياج والبحث عن المرشحين إلى التصفية والتقييم، نوفر لك مواهب مؤهلة في مجالات التقنية، المبيعات، التسويق، خدمة العملاء والعمليات، بما يتناسب مع طبيعة عملك ونمو فريقك.\",\"en\":\"We help you access qualified talent without the complexity of a long recruitment cycle. From role definition and sourcing to screening and evaluation, we provide skilled professionals across technology, sales, marketing, customer support, and operations, aligned with your business needs and team growth.\"}', '{\"ar\": [\"تحديد احتياجات التوظيف\", \"البحث عن المرشحين المناسبين\", \"فرز وتقييم المتقدمين\", \"المقابلات الأولية\", \"التحقق من المهارات والخبرات\", \"توظيف الكفاءات التقنية\", \"توظيف فرق المبيعات والتسويق\", \"توظيف خدمة العملاء والعمليات\", \"التوظيف الدائم والمؤقت\", \"توفير موارد حسب المشروع\", \"دعم الـ Onboarding\", \"بناء فرق حسب الطلب\"], \"en\": [\"Workforce Requirement Planning\", \"Talent Sourcing\", \"Candidate Screening & Evaluation\", \"Initial Interviews\", \"Skills & Experience Assessment\", \"Technical Recruitment\", \"Sales & Marketing Recruitment\", \"Customer Support & Operations Hiring\", \"Permanent & Temporary Hiring\", \"Project-Based Staffing\", \"Onboarding Support\", \"On-Demand Team Building\"]}', '{\"ar\": [\"صعوبة الوصول إلى الكفاءات المناسبة\", \"طول دورة التوظيف\", \"ارتفاع تكلفة التوظيف الداخلي\", \"قلة المرشحين المؤهلين\", \"صعوبة تقييم المهارات الحقيقية\", \"الحاجة إلى التوظيف السريع\", \"الحاجة إلى موارد لفترة محددة\", \"صعوبة توسيع الفريق عند زيادة العمل\", \"الضغط على فرق الموارد البشرية الداخلية\"], \"en\": [\"Difficulty finding qualified talent\", \"Long recruitment cycles\", \"High in-house hiring costs\", \"Limited access to suitable candidates\", \"Difficulty assessing real skills\", \"Urgent hiring needs\", \"Need for temporary or project-based resources\", \"Difficulty scaling teams quickly\", \"Overloaded internal HR teams\"]}', NULL, NULL, 0, 'published', 0, NULL, NULL, '2026-09-26 17:33:42', '2026-09-26 17:47:56', NULL),
(15, '{\"ar\":\"تعليم البرمجة بطريقة عملية\",\"en\":\"Practical Programming Education\"}', 'practical-programming-education', '{\"ar\":\"نعلم البرمجة من خلال التطبيق، التفكير وحل المشكلات، وليس من خلال الحفظ النظري فقط.\",\"en\":\"We teach programming through hands-on practice, problem-solving, and real projects not theory alone.\"}', '{\"ar\":\"نقدم تجربة تعليمية مختلفة تساعد المتعلمين على فهم البرمجة من خلال الممارسة والتجربة وبناء مشاريع حقيقية. نركز على تطوير التفكير المنطقي، حل المشكلات، وفهم كيفية بناء الحلول خطوة بخطوة، بحيث يتحول التعلم من مجرد معرفة المفاهيم إلى القدرة على استخدامها عمليًا.\",\"en\":\"We offer a different learning experience built around practice, experimentation, and real projects. Our approach develops logical thinking, problem-solving skills, and a deeper understanding of how digital solutions are built step by step, turning programming concepts into practical skills.\"}', '{\"ar\": [\"أساسيات البرمجة\", \"التفكير المنطقي وحل المشكلات\", \"التعلم بالمشاريع\", \"تطبيقات وتمارين عملية\", \"تطوير الويب والتطبيقات\", \"مشاريع واقعية\", \"توجيه ومتابعة مستمرة\", \"مسارات تعليمية حسب المستوى\"], \"en\": [\"Programming Fundamentals\", \"Logical Thinking & Problem Solving\", \"Project-Based Learning\", \"Hands-On Exercises\", \"Web & App Development\", \"Real-World Projects\", \"Mentoring & Continuous Support\", \"Level-Based Learning Paths\"]}', '{\"ar\": [\"صعوبة فهم البرمجة بالطريقة التقليدية\", \"التركيز على الحفظ بدل الفهم\", \"قلة التطبيق العملي\", \"صعوبة ربط المفاهيم بمشاريع حقيقية\", \"الخوف من البدء في البرمجة\", \"عدم معرفة كيفية الانتقال من التعلم إلى التنفيذ\"], \"en\": [\"Difficulty understanding traditional programming lessons\", \"Memorizing concepts without real understanding\", \"Lack of hands-on practice\", \"Difficulty applying concepts to real projects\", \"Fear of getting started with coding\", \"Struggling to move from learning to building\"]}', NULL, 35, 0, 'published', 0, NULL, NULL, '2026-09-28 11:27:30', '2026-09-28 11:27:37', NULL);

