(2, 'tagline', '{\"ar\":\"نبني حلولاً رقمية قابلة للتوسع\",\"en\":\"Building Digital Solutions That Scale\"}', 'general', 'text', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
