(4, 'phone', '+201022020671', 'contact', 'text', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(5, 'address', '{\"ar\":\"طريق الملك فهد، الرياض، المملكة العربية السعودية\",\"en\":\"King Fahd Road, Riyadh, Saudi Arabia\"}', 'contact', 'textarea', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(6, 'about_summary', '{\"ar\":\"Ytech شركة سعودية متخصصة في تطوير البرمجيات، تشمل تطبيقات الويب والجوال والحلول المؤسسية. منذ 2018، ساعدنا الشركات في أنحاء الخليج على تحويل حضورها الرقمي.\",\"en\":\"Ytech is a Saudi-based software development company specializing in web applications, mobile apps, and enterprise solutions. Since 2018, we have helped businesses across the GCC transform their digital presence.\"}', 'about', 'textarea', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(7, 'about_mission', '{\"ar\":\"تمكين الشركات من خلال حلول تقنية مبتكرة تعزز النمو والكفاءة والميزة التنافسية في الاقتصاد الرقمي.\",\"en\":\"To empower businesses with innovative technology solutions that drive growth, efficiency, and competitive advantage in the digital economy.\"}', 'about', 'textarea', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(8, 'about_vision', '{\"ar\":\"أن نكون الشريك التقني الرائد للمؤسسات في الشرق الأوسط، المعروفين بالتميز والموثوقية والابتكار.\",\"en\":\"To become the leading technology partner for enterprises across the Middle East, known for excellence, reliability, and innovation.\"}', 'about', 'textarea', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(9, 'facebook_url', 'https://www.facebook.com/profile.php?id=61594731237612', 'social', 'url', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
(10, 'twitter_url', NULL, 'social', 'url', '2026-08-30 17:49:36', '2026-09-30 16:24:48'),
