(1, 'Yousef Yehia', 'yousef-yehia', '{\"ar\":\"المؤسس والرئيس التنفيذي\",\"en\":\"Founder & CEO\"}', '{\"ar\":\"أسس يوسف Ytech في 2018 برؤية لجلب تطوير برمجيات عالمي المستوى للشركات السعودية. بخبرة تتجاوز 12 عاماً في التقنية، يقود الاستراتيجية وعلاقات العملاء.\",\"en\":\"Yousef founded Ytech in 2018 with a vision to bring world-class software development to Saudi businesses. With 12+ years in tech, he leads strategy and client relationships.\"}', NULL, 31, NULL, NULL, NULL, 1, 1, 1, '2026-08-30 17:49:36', '2026-09-27 11:05:05', NULL),
(2, 'Noura Al-Shehri', 'noura-al-shehri', '{\"ar\":\"قائدة التطوير\",\"en\":\"Lead Developer\"}', '{\"ar\":\"تتخصص نورة في معماريات Laravel وReact. قادت التطوير في أكثر من 20 مشروعاً مؤسسياً وتوجّه فريق الهندسة.\",\"en\":\"Noura specializes in Laravel and React architectures. She has led development on 20+ enterprise projects and mentors the engineering team.\"}', 'noura@ytech.com', NULL, NULL, NULL, 'https://github.com/noura-shehri', 1, 1, 2, '2026-08-30 17:49:36', '2026-09-27 10:52:13', '2026-09-27 10:52:13'),
(3, 'Omar Al-Qahtani', 'omar-al-qahtani', '{\"ar\":\"مصمم UI\\/UX\",\"en\":\"UI\\/UX Designer\"}', '{\"ar\":\"يصنع عمر واجهات بديهية متناسقة مع الهوية البصرية. يمتد عمله عبر التجارة الإلكترونية والرعاية الصحية والتطبيقات المالية في الخليج.\",\"en\":\"Omar creates intuitive, brand-aligned interfaces. His design work spans e-commerce, healthcare, and fintech applications across the GCC.\"}', 'omar@ytech.com', NULL, 'https://linkedin.com/in/omar-qahtani', NULL, NULL, 1, 1, 3, '2026-08-30 17:49:36', '2026-09-27 10:52:40', '2026-09-27 10:52:40'),
(4, 'Layla Al-Dossari', 'layla-al-dossari', '{\"ar\":\"مديرة المشاريع\",\"en\":\"Project Manager\"}', '{\"ar\":\"تضمن ليلى بقاء كل مشروع على المسار بمنهجيات Agile. تربط التواصل بين العملاء وفريق التطوير.\",\"en\":\"Layla ensures every project stays on track with agile methodologies. She bridges communication between clients and the development team.\"}', 'layla@ytech.com', NULL, NULL, NULL, NULL, 0, 1, 4, '2026-08-30 17:49:36', '2026-09-27 10:52:16', '2026-09-27 10:52:16'),
(5, 'Faisal Al-Ghamdi', 'faisal-al-ghamdi', '{\"ar\":\"مهندس DevOps\",\"en\":\"DevOps Engineer\"}', '{\"ar\":\"يدير فيصل البنية السحابية على AWS وAzure وخطوط CI\\/CD ومراقبة الأنظمة لجميع نشرات Ytech.\",\"en\":\"Faisal manages cloud infrastructure on AWS and Azure, CI\\/CD pipelines, and system monitoring for all Ytech deployments.\"}', 'faisal@ytech.com', NULL, NULL, NULL, 'https://github.com/faisal-ghamdi', 0, 1, 5, '2026-08-30 17:49:36', '2026-09-27 10:52:19', '2026-09-27 10:52:19');

