(1, 'Ahmed Al-Rashid', 'CEO', 'AlNoor Trading Co.', '{\"ar\":\"حوّلت Ytech أعمالنا التجزئية بمنصة تتعامل مع آلاف الطلبات يومياً. فهم فريقهم سوقنا وقدّموا أكثر مما توقعنا.\",\"en\":\"Ytech transformed our retail business with a platform that handles thousands of orders daily. Their team understood our market and delivered beyond expectations.\"}', 5, NULL, NULL, 1, 'published', 1, '2026-08-30 17:49:36', '2026-09-29 16:39:26', '2026-09-29 16:39:26', NULL, NULL),
(2, 'Dr. Sarah Al-Mutairi', 'Director of Operations', 'MedTrack Clinics', '{\"ar\":\"أحدث تطبيق MedTrack ثورة في طريقة حجز مرضانا للمواعيد. قدمت Ytech منتجاً مصقولاً وموثوقاً في الوقت المحدد وضمن الميزانية.\",\"en\":\"The MedTrack app has revolutionized how our patients book appointments. Ytech delivered a polished, reliable product on time and within budget.\"}', 5, NULL, NULL, 1, 'published', 2, '2026-08-30 17:49:36', '2026-09-29 16:39:27', '2026-09-29 16:39:27', NULL, NULL),
(3, 'Khalid Al-Otaibi', 'Operations Manager', 'Gulf Logistics Group', '{\"ar\":\"خفّفت لوحة تتبع الأسطول لدينا تأخير التسليم بنسبة 35%. كان فريق Ytech سريع الاستجابة ومحترفاً ومستثمراً حقاً في نجاحنا.\",\"en\":\"Our fleet tracking dashboard reduced delivery delays by 35%. The Ytech team was responsive, professional, and truly invested in our success.\"}', 5, NULL, NULL, 1, 'published', 3, '2026-08-30 17:49:36', '2026-09-29 16:39:31', '2026-09-29 16:39:31', NULL, NULL),
(4, 'Fatima Al-Harbi', 'CTO', 'FinServe Capital', '{\"ar\":\"كان الأمان والامتثال غير قابلين للتفاوض. بنت Ytech بوابة تلبي متطلبات SAMA مع تجربة مستخدم ممتازة.\",\"en\":\"Security and compliance were non-negotiable for us. Ytech built a portal that meets SAMA requirements while providing an excellent user experience.\"}', 5, NULL, NULL, 0, 'published', 4, '2026-08-30 17:49:36', '2026-09-29 16:39:32', '2026-09-29 16:39:32', NULL, NULL),
(5, 'يوسف', NULL, NULL, NULL, 5, NULL, NULL, 0, 'published', 0, '2026-09-29 16:29:40', '2026-09-29 16:29:56', NULL, 'voice-reviews/qDsoDsQe1ZHQAiLTm7BDhPGGhXVI8wu6hKuJSI8D.webm', 9),
(6, 'هبه', NULL, NULL, NULL, 5, NULL, NULL, 0, 'published', 0, '2026-09-29 16:34:25', '2026-09-29 16:35:48', NULL, 'voice-reviews/CWApM4wzcCTlPcTMGbLWkRm5tf5fWmtjfLGV2MuW.webm', 5);

